(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-048"]={"sura":48,"name_ar":"الفتح","name_en":"Al-Fath","verses":29,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":29,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=3\" class=\"link\">48:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:3 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=3\" class=\"link\">48:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:3 ஐ பார்க்கவும்"},"3":{"html":"<strong>இது மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<strong>ஸூரத்துல் ஃபத்ஹின் சிறப்புகள்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் முகஃப்பல் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்கா வெற்றியின் போது தமது பெண் ஒட்டகத்தின் மீது பயணித்தவாறு ஸூரத்துல் ஃபத்ஹை ஓதினார்கள். அவர்கள் அதனை ராகத்துடனும் இனிய குரலிலும் ஓதினார்கள். முஆவியா (ரழி) (ஒரு துணை அறிவிப்பாளர்) மேலும் கூறினார்கள்: \"மக்கள் என்னைச் சூழ்ந்து கொள்வார்கள் என்ற அச்சம் மட்டும் எனக்கு இல்லையென்றால், நான் நிச்சயமாக அவர் ஓதியதைப் போன்றே ஓதிக் காட்ட முயற்சி செய்திருப்பேன்.\" புகாரி மற்றும் முஸ்லிம் ஆகிய இருவருமே இந்த ஹதீஸை ஷுஃபா (ரஹ்) வழியாகப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>ஸூரத்துல் ஃபத்ஹ் அருளப்பட்டதற்கான காரணம்</strong><br />\r\n<br />\r\nஇந்தக் கண்ணியமிக்க ஸூரா, ஹிஜ்ரி ஆறாம் ஆண்டு துல்கஃதா மாதத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஹுதைபிய்யா பகுதியிலிருந்து திரும்பிய பிறகு வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது. அவர்கள் நாடிய உம்ராவை நிறைவேற்ற மஸ்ஜிதுல் ஹராமை அடையவிடாமல் இணைவைப்பாளர்கள் அவர்களைத் தடுத்த தருணம் அது. அப்போது அவர்கள் நபியவர்களை (ஸல்) மக்காவிற்குள் நுழைய விடாமல் தடுத்தாலும், பின்னர் சமாதானப் பேச்சுவார்த்தைக்கு முன்வந்தனர். அதன்படி, தூதர் (ஸல்) அவர்கள் இந்த ஆண்டு திரும்பிச் சென்றுவிட்டு, அடுத்த ஆண்டு உம்ராவிற்காக வர வேண்டும் என்று ஒரு சமாதான உடன்படிக்கை செய்யப்பட்டது. தூதர் (ஸல்) அவர்கள் இதற்குச் சம்மதித்தார்கள். இருப்பினும், உமர் பின் அல்-கத்தாப் (ரழி) உள்ளிட்ட சில ஸஹாபாக்கள் இந்த நிபந்தனைகளை விரும்பவில்லை. அல்லாஹ் நாடினால், இந்த ஸூராவிற்கான விளக்கத்தில் இதனை விரிவாகக் காண்போம். நபி (ஸல்) அவர்கள் தடுத்து நிறுத்தப்பட்ட இடத்திலேயே தமது பலிப்பிராணிகளை அறுத்துவிட்டு மதீனாவிற்குத் திரும்பியபோது, அவர்களுக்கும் இணைவைப்பாளர்களுக்கும் இடையே நடந்தவை குறித்து மாண்பும் கண்ணியமும் மிக்க அல்லாஹ் இந்த ஸூராவை வஹீயாக (இறைச்செய்தியாக) அருளினான். ஹுதைபிய்யா சமாதான உடன்படிக்கையினால் ஏற்படவிருந்த நன்மைகள் மற்றும் அதன் நற்பலன்களைக் கருத்தில் கொண்டு, அல்லாஹ் அதனை ஒரு தெளிவான வெற்றி என்று அறிவித்தான். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களும் மற்ற ஸஹாபாக்களும் கூறினார்கள்: \"நீங்கள் மக்கா வெற்றியையே 'அல்-ஃபத்ஹ்' (வெற்றி) என்று கருதுகிறீர்கள், ஆனால் எங்களைப் பொறுத்தவரை ஹுதைபிய்யா உடன்படிக்கையே 'அல்-ஃபத்ஹ்' ஆகும்.\" ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் ஹுதைபிய்யா நாளையே வெற்றியாகக் கருதினோம்!\" புகாரி அவர்கள் பதிவு செய்துள்ளார்கள்: அல்-பரா பின் ஆஸிப் (ரழி) அவர்கள் கூறினார்கள்: \"நீங்கள் மக்கா வெற்றியையே 'அல்-ஃபத்ஹ்' என்று கருதுகிறீர்கள், அது நிச்சயமாக ஒரு வெற்றிதான். எனினும், நாங்கள் ஹுதைபிய்யா நாளில் மேற்கொள்ளப்பட்ட 'பைஅத்துர் ரிழ்வானையே' (அர்-ரிழ்வான் உடன்படிக்கை) 'அல்-ஃபத்ஹ்' என்று கருதுகிறோம். அப்போது நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் ஆயிரத்து நானூறு பேர் இருந்தோம். ஹுதைபிய்யாவில் ஒரு கிணறு இருந்தது, அதன் நீரை ஒரு சொட்டு கூட மிச்சமில்லாமல் நாங்கள் முழுமையாகப் பயன்படுத்தியிருந்தோம். இந்தச் செய்தி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு எட்டியதும், அவர்கள் எங்களிடம் வந்து கிணற்றின் விளிம்பில் அமர்ந்தார்கள். பின்னர் ஒரு வாலியில் தண்ணீர் கொண்டுவரச் சொல்லி, அதைக் கொண்டு உளூ செய்தார்கள். பிறகு வாய் கொப்பளித்து, அல்லாஹ்விடம் பிரார்த்தனை செய்துவிட்டு அந்தத் தண்ணீரை மீண்டும் கிணற்றுக்குள் ஊற்றினார்கள். சிறிது நேரத்திலேயே, அந்தக் கிணறு எங்களுக்கும் எங்கள் கால்நடைகளுக்கும் தேவையான அளவு நீரைத் தாராளமாக வழங்கியது.\"<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் ஒரு பயணத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்தோம். நான் அவர்களிடம் ஒரு விஷயத்தைப் பற்றி மூன்று முறை கேட்டேன், ஆனால் அவர்கள் எனக்குப் பதிலளிக்கவில்லை. எனவே நான் எனக்குள், 'கத்தாபின் மகனே! உன்னை உன் தாய் இழக்கட்டும்! அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் ஒரே கேள்வியை மூன்று முறை திரும்பத் திரும்பக் கேட்டுப் பிடிவாதம் செய்தாய்; ஆனால் ஒவ்வொரு முறையும் அவர்கள் உனக்குப் பதிலளிக்கவில்லை' என்று கூறிக் கொண்டேன். எனவே, என்னைக் குறித்து குர்ஆனின் ஏதேனும் பகுதி வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டு விடுமோ என்ற அச்சத்தில், எனது ஒட்டகத்தில் ஏறி முன்னே சென்றேன். திடீரென, 'உமரே!' என்று ஒரு அறிவிப்பாளர் அழைக்கும் சத்தம் கேட்டது. என்னைப் பற்றி குர்ஆன் வசனம் அருளப்பட்டுவிட்டதோ என்று அஞ்சியவாறே நான் தூதர் (ஸல்) அவர்களிடம் சென்றேன். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نَزَلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">الْبَارِحَةَ</span> <span class=\"quran-arabic-font text-success\">سُورَةٌ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">أَحَبُّ</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span>:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">فَتَحْنَا</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">فَتْحاً</span> <span class=\"quran-arabic-font text-success\">مُّبِيناً</span> <span class=\"quran-arabic-font text-success\">لِّيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقَدَّمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَأَخَّرَ</span>»<br />\r\n<br />\r\n(நேற்றிரவு எனக்கு ஒரு ஸூரா வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது. அது இந்த உலகத்தையும் அதிலுள்ள அனைத்தையும் விட எனக்கு மிகவும் பிரியமானது: (நிச்சயமாக நாம் உமக்கு ஒரு தெளிவான வெற்றியை வழங்கியுள்ளோம். உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக.)) புகாரி, திர்மிதி மற்றும் நஸாயீ ஆகிய அறிஞர்கள் இந்த ஹதீஸை மாலிக் (ரஹ்) அவர்களின் வழியாகப் பல்வேறு அறிவிப்பாளர் தொடர்களில் பதிவு செய்துள்ளனர். அலி பின் அல்-மதீனி அவர்கள் கூறும்போது, \"இது மதீனாவின் அறிஞர்களைக் கொண்ட ஒரு சிறந்த அறிவிப்பாளர் தொடராகும்\" என்றார்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள்: \"நபி (ஸல்) அவர்கள் ஹுதைபிய்யாவிலிருந்து திரும்பிக் கொண்டிருந்தபோது இந்த வசனம் அவர்களுக்கு வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقَدَّمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَأَخَّرَ</span><br />\r\n<br />\r\n(உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக,)<br />\r\n<br />\r\nநபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">أُنْزِلَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَةَ</span> <span class=\"quran-arabic-font text-success\">آيَةٌ</span> <span class=\"quran-arabic-font text-success\">أَحَبُّ</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْض</span>»<br />\r\n<br />\r\n(இன்றிரவு எனக்கு ஒரு வசனம் வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது, அது இப்பூமி சுமந்துள்ள அனைத்தையும் விட எனக்கு மிகவும் பிரியமானது.) நபி (ஸல்) அவர்கள் அந்த வசனத்தை அவர்களுக்கு ஓதிக் காட்டினார்கள். அப்போது அவர்கள், 'அல்லாஹ்வின் தூதரே! உங்களுக்கு நல்வாழ்த்துகள்! மாண்பும் கண்ணியமும் மிக்க அல்லாஹ் உங்களுக்கு என்ன செய்வான் என்பதைத் தெளிவுபடுத்திவிட்டான். அப்படியென்றால் எங்களுக்கு அவன் என்ன செய்வான்?' என்று கேட்டார்கள். அப்போது நபி (ஸல்) அவர்களுக்கு இந்த வசனங்கள் வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டன:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّيُدْخِلَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَاتِ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِي</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்ட ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச் சோலைகளுக்குள் அவன் நுழையச் செய்வதற்காக...),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَوْزاً</span> <span class=\"quran-arabic-font text-success\">عَظِيماً</span><br />\r\n<br />\r\n(...இதுவே மகத்தான வெற்றியாகும்.)\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: முகீரா பின் ஷுஃபா (ரழி) அவர்கள் கூறினார்கள்: \"நபி (ஸல்) அவர்கள் தமது இரு பாதங்களும் வீங்கும் அளவிற்குத் தொழுவார்கள்.\" அவர்களிடம், 'அல்லாஹ் உங்கள் முந்தைய மற்றும் பிந்தைய பாவங்கள் அனைத்தையும் மன்னித்துவிட்டானே (பிறகு ஏன் இவ்வளவு சிரமப்பட வேண்டும்)?' என்று கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَفَلَا</span> <span class=\"quran-arabic-font text-success\">أَكُونُ</span> <span class=\"quran-arabic-font text-success\">عَبْدًا</span> <span class=\"quran-arabic-font text-success\">شَكُورًا؟</span>»<br />\r\n<br />\r\n(நான் நன்றிமிக்க அடியானாக இருக்க வேண்டாமா?) புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும், அபூதாவூத் தவிர மற்ற சுனன் நூல்களிலும் இந்த ஹதீஸ் இடம்பெற்றுள்ளது.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">فَتَحْنَا</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">فَتْحاً</span> <span class=\"quran-arabic-font text-success\">مُّبِيناً</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உமக்கு ஒரு தெளிவான வெற்றியை வழங்கியுள்ளோம்) என்பதன் பொருள் மிகத்தெளிவான மற்றும் வெளிப்படையான வெற்றியாகும். இந்த வசனம் ஹுதைபிய்யா உடன்படிக்கையைப் பற்றியதாகும். இதன் விளைவாக மக்கள் பெரும் கூட்டமாக இஸ்லாத்தில் இணைந்தனர்; ஒருவரையொருவர் வெளிப்படையாகச் சந்திக்கும் வாய்ப்பு உருவானது எனப் பல நன்மைகள் விளைந்தன. அக்காலகட்டத்தில் முஃமின்கள் (நம்பிக்கையாளர்கள்) இணைவைப்பவர்களிடம் மார்க்கத்தைப் போதித்தனர், இதனால் பயனுள்ள அறிவும் ஈமானும் எங்கும் பரவியது.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقَدَّمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَأَخَّرَ</span><br />\r\n<br />\r\n(உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக,) என்பது தூதர் (ஸல்) அவர்களுக்கு மட்டுமே உரிய சிறப்புகளில் ஒன்றாகும். இந்தச் சிறப்பில் வேறு எவருக்கும் பங்கில்லை. தூதர் (ஸல்) அவர்களைத் தவிர வேறு எவருக்கும் நற்செயல்கள் செய்த காரணத்திற்காக முந்தைய மற்றும் பிந்தைய பாவங்கள் அனைத்தும் மன்னிக்கப்பட்டதாக எந்தவொரு ஆதாரப்பூர்வமான ஹதீஸும் இல்லை. இது நிச்சயமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு வழங்கப்பட்ட பெரும் கண்ணியமாகும். அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிவதிலும், நேர்மையிலும், வாய்மையிலும் முந்தைய தலைமுறையினர் எவராலும் எட்ட முடியாத, இனிவரும் தலைமுறையினர் யாராலும் எட்ட முடியாத ஒரு உச்சத்தை அவர்கள் எட்டினார்கள். முஹம்மது (ஸல்) அவர்கள் இவ்வுலகிலும் மறுமையிலும் ஒரு முழுமையான மனிதராகவும், ஒட்டுமொத்த மனிதகுலத்தின் தலைவராகவும் திகழ்கிறார்கள். அவர்கள் அல்லாஹ்வின் படைப்புகளிலேயே அவனுக்கு மிகவும் கீழ்ப்படிபவராகவும், அவனது ஏவல் விலக்கல்களை அதிகம் மதிப்பவராகவும் இருந்ததால், தங்களது பெண் ஒட்டகம் மண்டியிட்டு நகர மறுத்தபோது கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">حَبَسَها</span> <span class=\"quran-arabic-font text-success\">حَابِسُ</span> <span class=\"quran-arabic-font text-success\">الْفِيل</span>»<br />\r\n<br />\r\n(யானையைத் தடுத்தவனே இதையும் தடுத்துள்ளான்.)<br />\r\n<br />\r\nபின்னர் நபி (ஸல்) அவர்கள் அறிவித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَسْأَلُونِّي</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">يُعَظِّمُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">حُرُمَاتِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَجَبْتُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهَا</span>»<br />\r\n<br />\r\n(என் உயிர் எவன் கைவசம் உள்ளதோ அவன் மீது சத்தியமாக! இன்று அவர்கள் அல்லாஹ்வின் புனிதங்களை மதிக்கும் விதமாக எதைக் கேட்டாலும், அதனை நான் அவர்களுக்குத் தருவேன்.)<br />\r\n<br />\r\nதூதர் (ஸல்) அவர்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து குறைஷிகளின் சமாதான ஒப்பந்தத்தை ஏற்றுக்கொண்டபோது, கண்ணியமிக்க அல்லாஹ் அவர்களிடம் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">فَتَحْنَا</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">فَتْحاً</span> <span class=\"quran-arabic-font text-success\">مُّبِيناً</span> <span class=\"quran-arabic-font text-success\">لِّيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقَدَّمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَأَخَّرَ</span> <span class=\"quran-arabic-font text-success\">وَيُتِمَّ</span> <span class=\"quran-arabic-font text-success\">نِعْمَتَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உமக்கு ஒரு தெளிவான வெற்றியை வழங்கியுள்ளோம். உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காகவும், உம்மீது தனது அருட்கொடையை முழுமையாக்குவதற்காகவும்,) இவ்வுலகிலும் மறுமையிலும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَهْدِيَكَ</span> <span class=\"quran-arabic-font text-success\">صِرَطاً</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيماً</span><br />\r\n<br />\r\n(மேலும் உம்மை நேரான பாதையில் நடத்துவதற்காகவும்,) அவன் உமக்கு விதித்துள்ள மாண்புமிக்க சட்டங்கள் மற்றும் நேரான மார்க்கத்தின் மூலமாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَنصُرَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">نَصْراً</span> <span class=\"quran-arabic-font text-success\">عَزِيزاً</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் உமக்கு வலிமையான உதவியை வழங்குவதற்காகவும்.) நீங்கள் மாண்பும் கண்ணியமும் மிக்க அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிந்த காரணத்தால், அல்லாஹ் உமது அந்தஸ்தை உயர்த்தி, உமது எதிரிகளுக்கு எதிராக உமக்கு வெற்றியளிப்பான்.<br />\r\n<br />\r\nஒரு ஆதாரப்பூர்வமான ஹதீஸில் இவ்வாறு கூறப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">زَادَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَبْدًا</span> <span class=\"quran-arabic-font text-success\">بِعَفْوٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">عِزًّا</span>. <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَوَاضَعَ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">للهِ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">رَفَعَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>»<br />\r\n<br />\r\n(மன்னிப்பதன் மூலம் ஓர் அடியானுக்கு அல்லாஹ் கண்ணியத்தையே அதிகரிக்கிறான். எவர் அல்லாஹ்வுக்காகப் பணிவை மேற்கொள்கிறாரோ, அவரை உயர்வும் மேன்மையும் மிக்க அல்லாஹ் உயர்த்தி விடுகிறான்.)<br />\r\n<br />\r\nஉமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"உம் விஷயத்தில் அல்லாஹ்வுக்கு மாறு செய்த ஒருவரைத் தண்டிப்பதற்கு, அவர் விஷயத்தில் நீர் மாண்பும் கண்ணியமும் மிக்க அல்லாஹ்வுக்குக் கீழ்ப்படிவதை விடச் சிறந்த வழி வேறொன்றுமில்லை.\"<br />\r\n<br />","text":"இது மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nஸூரத்துல் ஃபத்ஹின் சிறப்புகள்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் முகஃப்பல் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்கா வெற்றியின் போது தமது பெண் ஒட்டகத்தின் மீது பயணித்தவாறு ஸூரத்துல் ஃபத்ஹை ஓதினார்கள். அவர்கள் அதனை ராகத்துடனும் இனிய குரலிலும் ஓதினார்கள். முஆவியா (ரழி) (ஒரு துணை அறிவிப்பாளர்) மேலும் கூறினார்கள்: \"மக்கள் என்னைச் சூழ்ந்து கொள்வார்கள் என்ற அச்சம் மட்டும் எனக்கு இல்லையென்றால், நான் நிச்சயமாக அவர் ஓதியதைப் போன்றே ஓதிக் காட்ட முயற்சி செய்திருப்பேன்.\" புகாரி மற்றும் முஸ்லிம் ஆகிய இருவருமே இந்த ஹதீஸை ஷுஃபா (ரஹ்) வழியாகப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஸூரத்துல் ஃபத்ஹ் அருளப்பட்டதற்கான காரணம்\n\r\n\n\r\nஇந்தக் கண்ணியமிக்க ஸூரா, ஹிஜ்ரி ஆறாம் ஆண்டு துல்கஃதா மாதத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஹுதைபிய்யா பகுதியிலிருந்து திரும்பிய பிறகு வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது. அவர்கள் நாடிய உம்ராவை நிறைவேற்ற மஸ்ஜிதுல் ஹராமை அடையவிடாமல் இணைவைப்பாளர்கள் அவர்களைத் தடுத்த தருணம் அது. அப்போது அவர்கள் நபியவர்களை (ஸல்) மக்காவிற்குள் நுழைய விடாமல் தடுத்தாலும், பின்னர் சமாதானப் பேச்சுவார்த்தைக்கு முன்வந்தனர். அதன்படி, தூதர் (ஸல்) அவர்கள் இந்த ஆண்டு திரும்பிச் சென்றுவிட்டு, அடுத்த ஆண்டு உம்ராவிற்காக வர வேண்டும் என்று ஒரு சமாதான உடன்படிக்கை செய்யப்பட்டது. தூதர் (ஸல்) அவர்கள் இதற்குச் சம்மதித்தார்கள். இருப்பினும், உமர் பின் அல்-கத்தாப் (ரழி) உள்ளிட்ட சில ஸஹாபாக்கள் இந்த நிபந்தனைகளை விரும்பவில்லை. அல்லாஹ் நாடினால், இந்த ஸூராவிற்கான விளக்கத்தில் இதனை விரிவாகக் காண்போம். நபி (ஸல்) அவர்கள் தடுத்து நிறுத்தப்பட்ட இடத்திலேயே தமது பலிப்பிராணிகளை அறுத்துவிட்டு மதீனாவிற்குத் திரும்பியபோது, அவர்களுக்கும் இணைவைப்பாளர்களுக்கும் இடையே நடந்தவை குறித்து மாண்பும் கண்ணியமும் மிக்க அல்லாஹ் இந்த ஸூராவை வஹீயாக (இறைச்செய்தியாக) அருளினான். ஹுதைபிய்யா சமாதான உடன்படிக்கையினால் ஏற்படவிருந்த நன்மைகள் மற்றும் அதன் நற்பலன்களைக் கருத்தில் கொண்டு, அல்லாஹ் அதனை ஒரு தெளிவான வெற்றி என்று அறிவித்தான். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களும் மற்ற ஸஹாபாக்களும் கூறினார்கள்: \"நீங்கள் மக்கா வெற்றியையே 'அல்-ஃபத்ஹ்' (வெற்றி) என்று கருதுகிறீர்கள், ஆனால் எங்களைப் பொறுத்தவரை ஹுதைபிய்யா உடன்படிக்கையே 'அல்-ஃபத்ஹ்' ஆகும்.\" ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் ஹுதைபிய்யா நாளையே வெற்றியாகக் கருதினோம்!\" புகாரி அவர்கள் பதிவு செய்துள்ளார்கள்: அல்-பரா பின் ஆஸிப் (ரழி) அவர்கள் கூறினார்கள்: \"நீங்கள் மக்கா வெற்றியையே 'அல்-ஃபத்ஹ்' என்று கருதுகிறீர்கள், அது நிச்சயமாக ஒரு வெற்றிதான். எனினும், நாங்கள் ஹுதைபிய்யா நாளில் மேற்கொள்ளப்பட்ட 'பைஅத்துர் ரிழ்வானையே' (அர்-ரிழ்வான் உடன்படிக்கை) 'அல்-ஃபத்ஹ்' என்று கருதுகிறோம். அப்போது நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் ஆயிரத்து நானூறு பேர் இருந்தோம். ஹுதைபிய்யாவில் ஒரு கிணறு இருந்தது, அதன் நீரை ஒரு சொட்டு கூட மிச்சமில்லாமல் நாங்கள் முழுமையாகப் பயன்படுத்தியிருந்தோம். இந்தச் செய்தி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு எட்டியதும், அவர்கள் எங்களிடம் வந்து கிணற்றின் விளிம்பில் அமர்ந்தார்கள். பின்னர் ஒரு வாலியில் தண்ணீர் கொண்டுவரச் சொல்லி, அதைக் கொண்டு உளூ செய்தார்கள். பிறகு வாய் கொப்பளித்து, அல்லாஹ்விடம் பிரார்த்தனை செய்துவிட்டு அந்தத் தண்ணீரை மீண்டும் கிணற்றுக்குள் ஊற்றினார்கள். சிறிது நேரத்திலேயே, அந்தக் கிணறு எங்களுக்கும் எங்கள் கால்நடைகளுக்கும் தேவையான அளவு நீரைத் தாராளமாக வழங்கியது.\"\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் ஒரு பயணத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்தோம். நான் அவர்களிடம் ஒரு விஷயத்தைப் பற்றி மூன்று முறை கேட்டேன், ஆனால் அவர்கள் எனக்குப் பதிலளிக்கவில்லை. எனவே நான் எனக்குள், 'கத்தாபின் மகனே! உன்னை உன் தாய் இழக்கட்டும்! அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் ஒரே கேள்வியை மூன்று முறை திரும்பத் திரும்பக் கேட்டுப் பிடிவாதம் செய்தாய்; ஆனால் ஒவ்வொரு முறையும் அவர்கள் உனக்குப் பதிலளிக்கவில்லை' என்று கூறிக் கொண்டேன். எனவே, என்னைக் குறித்து குர்ஆனின் ஏதேனும் பகுதி வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டு விடுமோ என்ற அச்சத்தில், எனது ஒட்டகத்தில் ஏறி முன்னே சென்றேன். திடீரென, 'உமரே!' என்று ஒரு அறிவிப்பாளர் அழைக்கும் சத்தம் கேட்டது. என்னைப் பற்றி குர்ஆன் வசனம் அருளப்பட்டுவிட்டதோ என்று அஞ்சியவாறே நான் தூதர் (ஸல்) அவர்களிடம் சென்றேன். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«نَزَلَ عَلَيَّ الْبَارِحَةَ سُورَةٌ هِيَ أَحَبُّ إِلَيَّ مِنَ الدُّنْيَا وَمَا فِيهَا:\n\r\n\n\r\nإِنَّا فَتَحْنَا لَكَ فَتْحاً مُّبِيناً لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ»\n\r\n\n\r\n(நேற்றிரவு எனக்கு ஒரு ஸூரா வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது. அது இந்த உலகத்தையும் அதிலுள்ள அனைத்தையும் விட எனக்கு மிகவும் பிரியமானது: (நிச்சயமாக நாம் உமக்கு ஒரு தெளிவான வெற்றியை வழங்கியுள்ளோம். உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக.)) புகாரி, திர்மிதி மற்றும் நஸாயீ ஆகிய அறிஞர்கள் இந்த ஹதீஸை மாலிக் (ரஹ்) அவர்களின் வழியாகப் பல்வேறு அறிவிப்பாளர் தொடர்களில் பதிவு செய்துள்ளனர். அலி பின் அல்-மதீனி அவர்கள் கூறும்போது, \"இது மதீனாவின் அறிஞர்களைக் கொண்ட ஒரு சிறந்த அறிவிப்பாளர் தொடராகும்\" என்றார்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள்: \"நபி (ஸல்) அவர்கள் ஹுதைபிய்யாவிலிருந்து திரும்பிக் கொண்டிருந்தபோது இந்த வசனம் அவர்களுக்கு வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது:\n\r\n\n\r\nلِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ\n\r\n\n\r\n(உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக,)\n\r\n\n\r\nநபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَقَدْ أُنْزِلَتْ عَلَيَّ اللَّيْلَةَ آيَةٌ أَحَبُّ إِلَيَّ مِمَّا عَلَى الْأَرْض»\n\r\n\n\r\n(இன்றிரவு எனக்கு ஒரு வசனம் வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது, அது இப்பூமி சுமந்துள்ள அனைத்தையும் விட எனக்கு மிகவும் பிரியமானது.) நபி (ஸல்) அவர்கள் அந்த வசனத்தை அவர்களுக்கு ஓதிக் காட்டினார்கள். அப்போது அவர்கள், 'அல்லாஹ்வின் தூதரே! உங்களுக்கு நல்வாழ்த்துகள்! மாண்பும் கண்ணியமும் மிக்க அல்லாஹ் உங்களுக்கு என்ன செய்வான் என்பதைத் தெளிவுபடுத்திவிட்டான். அப்படியென்றால் எங்களுக்கு அவன் என்ன செய்வான்?' என்று கேட்டார்கள். அப்போது நபி (ஸல்) அவர்களுக்கு இந்த வசனங்கள் வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டன:\n\r\n\n\r\nلِّيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ\n\r\n\n\r\n(நம்பிக்கை கொண்ட ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச் சோலைகளுக்குள் அவன் நுழையச் செய்வதற்காக...),\n\r\n\n\r\nفَوْزاً عَظِيماً\n\r\n\n\r\n(...இதுவே மகத்தான வெற்றியாகும்.)\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: முகீரா பின் ஷுஃபா (ரழி) அவர்கள் கூறினார்கள்: \"நபி (ஸல்) அவர்கள் தமது இரு பாதங்களும் வீங்கும் அளவிற்குத் தொழுவார்கள்.\" அவர்களிடம், 'அல்லாஹ் உங்கள் முந்தைய மற்றும் பிந்தைய பாவங்கள் அனைத்தையும் மன்னித்துவிட்டானே (பிறகு ஏன் இவ்வளவு சிரமப்பட வேண்டும்)?' என்று கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَفَلَا أَكُونُ عَبْدًا شَكُورًا؟»\n\r\n\n\r\n(நான் நன்றிமிக்க அடியானாக இருக்க வேண்டாமா?) புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும், அபூதாவூத் தவிர மற்ற சுனன் நூல்களிலும் இந்த ஹதீஸ் இடம்பெற்றுள்ளது.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nإِنَّا فَتَحْنَا لَكَ فَتْحاً مُّبِيناً\n\r\n\n\r\n(நிச்சயமாக நாம் உமக்கு ஒரு தெளிவான வெற்றியை வழங்கியுள்ளோம்) என்பதன் பொருள் மிகத்தெளிவான மற்றும் வெளிப்படையான வெற்றியாகும். இந்த வசனம் ஹுதைபிய்யா உடன்படிக்கையைப் பற்றியதாகும். இதன் விளைவாக மக்கள் பெரும் கூட்டமாக இஸ்லாத்தில் இணைந்தனர்; ஒருவரையொருவர் வெளிப்படையாகச் சந்திக்கும் வாய்ப்பு உருவானது எனப் பல நன்மைகள் விளைந்தன. அக்காலகட்டத்தில் முஃமின்கள் (நம்பிக்கையாளர்கள்) இணைவைப்பவர்களிடம் மார்க்கத்தைப் போதித்தனர், இதனால் பயனுள்ள அறிவும் ஈமானும் எங்கும் பரவியது.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nلِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ\n\r\n\n\r\n(உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக,) என்பது தூதர் (ஸல்) அவர்களுக்கு மட்டுமே உரிய சிறப்புகளில் ஒன்றாகும். இந்தச் சிறப்பில் வேறு எவருக்கும் பங்கில்லை. தூதர் (ஸல்) அவர்களைத் தவிர வேறு எவருக்கும் நற்செயல்கள் செய்த காரணத்திற்காக முந்தைய மற்றும் பிந்தைய பாவங்கள் அனைத்தும் மன்னிக்கப்பட்டதாக எந்தவொரு ஆதாரப்பூர்வமான ஹதீஸும் இல்லை. இது நிச்சயமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு வழங்கப்பட்ட பெரும் கண்ணியமாகும். அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிவதிலும், நேர்மையிலும், வாய்மையிலும் முந்தைய தலைமுறையினர் எவராலும் எட்ட முடியாத, இனிவரும் தலைமுறையினர் யாராலும் எட்ட முடியாத ஒரு உச்சத்தை அவர்கள் எட்டினார்கள். முஹம்மது (ஸல்) அவர்கள் இவ்வுலகிலும் மறுமையிலும் ஒரு முழுமையான மனிதராகவும், ஒட்டுமொத்த மனிதகுலத்தின் தலைவராகவும் திகழ்கிறார்கள். அவர்கள் அல்லாஹ்வின் படைப்புகளிலேயே அவனுக்கு மிகவும் கீழ்ப்படிபவராகவும், அவனது ஏவல் விலக்கல்களை அதிகம் மதிப்பவராகவும் இருந்ததால், தங்களது பெண் ஒட்டகம் மண்டியிட்டு நகர மறுத்தபோது கூறினார்கள்:\n\r\n\n\r\n«حَبَسَها حَابِسُ الْفِيل»\n\r\n\n\r\n(யானையைத் தடுத்தவனே இதையும் தடுத்துள்ளான்.)\n\r\n\n\r\nபின்னர் நபி (ஸல்) அவர்கள் அறிவித்தார்கள்:\n\r\n\n\r\n«وَالَّذِي نَفْسِي بِيَدِهِ لَا يَسْأَلُونِّي الْيَوْمَ شَيْئًا يُعَظِّمُونَ بِهِ حُرُمَاتِ اللهِ إِلَّا أَجَبْتُهُمْ إِلَيْهَا»\n\r\n\n\r\n(என் உயிர் எவன் கைவசம் உள்ளதோ அவன் மீது சத்தியமாக! இன்று அவர்கள் அல்லாஹ்வின் புனிதங்களை மதிக்கும் விதமாக எதைக் கேட்டாலும், அதனை நான் அவர்களுக்குத் தருவேன்.)\n\r\n\n\r\nதூதர் (ஸல்) அவர்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து குறைஷிகளின் சமாதான ஒப்பந்தத்தை ஏற்றுக்கொண்டபோது, கண்ணியமிக்க அல்லாஹ் அவர்களிடம் கூறினான்:\n\r\n\n\r\nإِنَّا فَتَحْنَا لَكَ فَتْحاً مُّبِيناً لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ\n\r\n\n\r\n(நிச்சயமாக நாம் உமக்கு ஒரு தெளிவான வெற்றியை வழங்கியுள்ளோம். உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காகவும், உம்மீது தனது அருட்கொடையை முழுமையாக்குவதற்காகவும்,) இவ்வுலகிலும் மறுமையிலும்.\n\r\n\n\r\nوَيَهْدِيَكَ صِرَطاً مُّسْتَقِيماً\n\r\n\n\r\n(மேலும் உம்மை நேரான பாதையில் நடத்துவதற்காகவும்,) அவன் உமக்கு விதித்துள்ள மாண்புமிக்க சட்டங்கள் மற்றும் நேரான மார்க்கத்தின் மூலமாக.\n\r\n\n\r\nوَيَنصُرَكَ اللَّهُ نَصْراً عَزِيزاً\n\r\n\n\r\n(மேலும் அல்லாஹ் உமக்கு வலிமையான உதவியை வழங்குவதற்காகவும்.) நீங்கள் மாண்பும் கண்ணியமும் மிக்க அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிந்த காரணத்தால், அல்லாஹ் உமது அந்தஸ்தை உயர்த்தி, உமது எதிரிகளுக்கு எதிராக உமக்கு வெற்றியளிப்பான்.\n\r\n\n\r\nஒரு ஆதாரப்பூர்வமான ஹதீஸில் இவ்வாறு கூறப்பட்டுள்ளது:\n\r\n\n\r\n«وَمَا زَادَ اللهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا. وَمَا تَوَاضَعَ أَحَدٌ للهِ عَزَّ وَجَلَّ إِلَّا رَفَعَهُ اللهُ تَعَالَى»\n\r\n\n\r\n(மன்னிப்பதன் மூலம் ஓர் அடியானுக்கு அல்லாஹ் கண்ணியத்தையே அதிகரிக்கிறான். எவர் அல்லாஹ்வுக்காகப் பணிவை மேற்கொள்கிறாரோ, அவரை உயர்வும் மேன்மையும் மிக்க அல்லாஹ் உயர்த்தி விடுகிறான்.)\n\r\n\n\r\nஉமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"உம் விஷயத்தில் அல்லாஹ்வுக்கு மாறு செய்த ஒருவரைத் தண்டிப்பதற்கு, அவர் விஷயத்தில் நீர் மாண்பும் கண்ணியமும் மிக்க அல்லாஹ்வுக்குக் கீழ்ப்படிவதை விடச் சிறந்த வழி வேறொன்றுமில்லை.\""},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=7\" class=\"link\">48:7</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:7 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=7\" class=\"link\">48:7</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:7 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=7\" class=\"link\">48:7</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:7 ஐ பார்க்கவும்"},"7":{"html":"<strong>முஃமின்களின் இதயங்களில் அல்லாஹ் ஸகீனாவை இறக்கினான்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">السَّكِينَةَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">لِيَزْدَادُواْ</span> <span class=\"quran-arabic-font text-success\">إِيمَاناً</span> <span class=\"quran-arabic-font text-success\">مَّعَ</span> <span class=\"quran-arabic-font text-success\">إِيمَـنِهِمْ﴿</span><br />\r\n<br />\r\n(அவன்தான் ஸகீனாவை இறக்கினான்), அதாவது அமைதி. கத்தாதா (ரழி) அவர்கள் இதற்கு விளக்கமளிக்கையில், \"முஃமின்களின் இதயங்களில் ஏற்பட்ட அருளாகும்\" என்று கூறினார்கள். அதாவது ஹுதைபிய்யா நாளில் ஸஹாபாக்களின் (ரழி) உள்ளங்களில் ஏற்பட்ட அமைதியைக் குறிக்கிறது. அந்த ஸஹாபாக்கள் (ரழி) அல்லாஹ் மற்றும் அவனது தூதரின் (ஸல்) அழைப்பை ஏற்று, அல்லாஹ் மற்றும் அவனது தூதரின் (ஸல்) முடிவுகளுக்குக் கீழ்ப்படிந்தார்கள். அவர்களுடைய உள்ளங்கள் இதனை ஏற்றுக்கொண்டு நிம்மதியடைந்தபோது, அல்லாஹ் அவர்கள் ஏற்கனவே கொண்டிருந்த ஈமானுடன் மேலும் ஈமானை அதிகப்படுத்தினான். உள்ளங்களில் ஈமான் கூடும் மற்றும் குறையும் என்பதற்கு ஆதாரமாக இமாம் அல்-புகாரியும் பிற இமாம்களும் இந்த வசனத்தையே முன்வைக்கின்றனர். அல்லாஹ் நாடியிருந்தால், நிராகரிப்பாளர்களுக்குத் தோல்வியைத் தந்திருப்பான் என்று அடுத்துக் கூறுகிறான்; <span class=\"quran-arabic-font text-success\">﴾وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">جُنُودُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضِ﴿</span><br />\r\n<br />\r\n(வானங்கள் மற்றும் பூமியின் படைகள் அல்லாஹ்வுக்கே உரியன). அவன் ஒரேயொரு வானவரை அவர்களிடம் அனுப்ப நாடியிருந்தாலும், அந்த வானவர் அவர்கள் கொண்டிருந்த அனைத்தையும் அழித்திருப்பார். எனினும், உயர்ந்தோனாகிய அல்லாஹ், முஃமின்கள் மூலமாக ஜிஹாத் மற்றும் போர் நிறுவப்பட வேண்டும் என்று நாடினான். இதில் அவனுக்குப் பெரும் ஞானமும், தெளிவான காரணங்களும், சந்தேகத்திற்கு இடமற்ற சான்றுகளும் உள்ளன. இதனால்தான் மகத்துவமிக்க அல்லாஹ் அடுத்துக் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيماً</span> <span class=\"quran-arabic-font text-success\">حَكِيماً﴿</span><br />\r\n<br />\r\n(அல்லாஹ் யாவற்றையும் அறிந்தவனாகவும், ஞானமிக்கவனாகவும் இருக்கிறான்.)<br />\r\n<br />\r\nஉயர்ந்தோனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾لِّيُدْخِلَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الأَنْهَـرُ</span> <span class=\"quran-arabic-font text-success\">خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(முஃமின்களான ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடும் சுவனச் சோலைகளில் அவர்கள் என்றும் தங்கியிருக்கும் நிலையில் நுழைவிப்பதற்காக,) அனஸ் (ரழி) அவர்கள் அறிவித்த ஒரு ஹதீஸில், ஸஹாபாக்கள் (ரழி), \"அல்லாஹ்வின் தூதரே (ஸல்)! உங்களுக்கு நல்வாழ்த்துகள்! இந்த நற்செய்தி உங்களுக்குரியது, எங்களுக்கு என்ன நற்செய்தி இருக்கிறது?\" என்று கேட்டபோது, உயர்ந்தோனாகிய அல்லாஹ் இந்த வசனத்தை இறக்கினான் என்று குறிப்பிட்டுள்ளோம், <span class=\"quran-arabic-font text-success\">﴾لِّيُدْخِلَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الأَنْهَـرُ</span> <span class=\"quran-arabic-font text-success\">خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(முஃமின்களான ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடும் சுவனச் சோலைகளில் அவர்கள் என்றும் தங்கியிருக்கும் நிலையில் நுழைவிப்பதற்காக,) அதாவது அவர்கள் சொர்க்கத்தில் நிரந்தரமாகத் தங்கியிருப்பார்கள், <span class=\"quran-arabic-font text-success\">﴾وَيُكَفِّرَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَـتِهِمْ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்களின் பாவங்களை அவர்களை விட்டும் போக்கிவிடுவதற்காக;) அவர்களுடைய தவறுகளுக்காக அல்லாஹ் அவர்களைத் தண்டிக்க மாட்டான். மாறாக, அவன் அவர்களை மன்னித்து, பிழைகளைப் பொறுத்து, குற்றங்களை மறைத்து, அவர்களுக்கு அருள் புரிந்து, அவர்களின் நற்செயல்களை அங்கீகரிப்பான், <span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَوْزاً</span> <span class=\"quran-arabic-font text-success\">عَظِيماً﴿</span><br />\r\n<br />\r\n(அல்லாஹ்விடம் இது மகத்தான வெற்றியாகும்.) உயர்ந்தோனாகிய அல்லாஹ் இது போன்றதொரு வசனத்தில் கூறினான், <span class=\"quran-arabic-font text-success\">﴾فَمَن</span> <span class=\"quran-arabic-font text-success\">زُحْزِحَ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَأُدْخِلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">فَازَ﴿</span><br />\r\n<br />\r\n(யார் நரக நெருப்பிலிருந்து அப்புறப்படுத்தப்பட்டு, சுவனத்தில் நுழைவிக்கப்படுகிறாரோ அவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார்.) (<a href=\"qurandisp.php?sura=3&ayah=185\" class=\"link\">3:185</a>)<br />\r\n<br />\r\nஅல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾وَيُعَذِّبَ</span> <span class=\"quran-arabic-font text-success\">الْمُنَـفِقِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُنَـفِقَـتِ</span> <span class=\"quran-arabic-font text-success\">وَالْمُشْرِكِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُشْرِكَـتِ</span> <span class=\"quran-arabic-font text-success\">الظَّانِّينَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">ظَنَّ</span> <span class=\"quran-arabic-font text-success\">السَّوْءِ﴿</span><br />\r\n<br />\r\n(மேலும் நயவஞ்சகர்களான ஆண்களையும் பெண்களையும், இணைவைப்பாளர்களான ஆண்களையும் பெண்களையும், அல்லாஹ்வைப் பற்றித் தீய எண்ணம் கொள்பவர்களையும் அவன் தண்டிப்பதற்காக), அவர்கள் அல்லாஹ்வின் முடிவுகளில் உள்ள ஞானத்தைச் சந்தேகிப்பவர்கள்; மேலும் தூதரும் (ஸல்) அவரது தோழர்களும் (ரழி) கொல்லப்பட்டு, அடியோடு அழிக்கப்பட்டு விடுவார்கள் என்று எண்ணியவர்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">دَآئِرَةُ</span> <span class=\"quran-arabic-font text-success\">السَّوْءِ</span> <span class=\"quran-arabic-font text-success\">وَغَضِبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَعَنَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்களுக்குக் கேடான சூழலே அமையும். மேலும் அல்லாஹ்வின் கோபம் அவர்கள் மீது உண்டானது, அவன் அவர்களைச் சபித்தும் விட்டான்) அவன் தனது அருளிலிருந்து அவர்களை அப்புறப்படுத்திவிட்டான், <span class=\"quran-arabic-font text-success\">﴾وَأَعَدَّ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">وَسَآءَتْ</span> <span class=\"quran-arabic-font text-success\">مَصِيراً﴿</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்காக நரகத்தைச் சித்தம் செய்துள்ளான் - அது மீளுமிடங்களில் மிகவும் கெட்டது.)<br />\r\n<br />\r\nஉயர்ந்தோனும் கண்ணியமிக்கவனுமான அல்லாஹ், இஸ்லாத்தின் எதிரிகள், நிராகரிப்பாளர்கள் மற்றும் நயவஞ்சகர்களிடம் பழிவாங்கும் தனது ஆற்றலை உறுதிப்படுத்தினான், <span class=\"quran-arabic-font text-success\">﴾وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">جُنُودُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَزِيزاً</span> <span class=\"quran-arabic-font text-success\">حَكِيماً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(வானங்கள் மற்றும் பூமியின் படைகள் அல்லாஹ்வுக்கே உரியன. மேலும் அல்லாஹ் வல்லமை மிக்கவனாகவும், ஞானமிக்கவனாகவும் இருக்கிறான்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"முஃமின்களின் இதயங்களில் அல்லாஹ் ஸகீனாவை இறக்கினான்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான், ﴾هُوَ الَّذِى أَنزَلَ السَّكِينَةَ فِى قُلُوبِ الْمُؤْمِنِينَ لِيَزْدَادُواْ إِيمَاناً مَّعَ إِيمَـنِهِمْ﴿\n\r\n\n\r\n(அவன்தான் ஸகீனாவை இறக்கினான்), அதாவது அமைதி. கத்தாதா (ரழி) அவர்கள் இதற்கு விளக்கமளிக்கையில், \"முஃமின்களின் இதயங்களில் ஏற்பட்ட அருளாகும்\" என்று கூறினார்கள். அதாவது ஹுதைபிய்யா நாளில் ஸஹாபாக்களின் (ரழி) உள்ளங்களில் ஏற்பட்ட அமைதியைக் குறிக்கிறது. அந்த ஸஹாபாக்கள் (ரழி) அல்லாஹ் மற்றும் அவனது தூதரின் (ஸல்) அழைப்பை ஏற்று, அல்லாஹ் மற்றும் அவனது தூதரின் (ஸல்) முடிவுகளுக்குக் கீழ்ப்படிந்தார்கள். அவர்களுடைய உள்ளங்கள் இதனை ஏற்றுக்கொண்டு நிம்மதியடைந்தபோது, அல்லாஹ் அவர்கள் ஏற்கனவே கொண்டிருந்த ஈமானுடன் மேலும் ஈமானை அதிகப்படுத்தினான். உள்ளங்களில் ஈமான் கூடும் மற்றும் குறையும் என்பதற்கு ஆதாரமாக இமாம் அல்-புகாரியும் பிற இமாம்களும் இந்த வசனத்தையே முன்வைக்கின்றனர். அல்லாஹ் நாடியிருந்தால், நிராகரிப்பாளர்களுக்குத் தோல்வியைத் தந்திருப்பான் என்று அடுத்துக் கூறுகிறான்; ﴾وَلِلَّهِ جُنُودُ السَّمَـوَتِ وَالأَرْضِ﴿\n\r\n\n\r\n(வானங்கள் மற்றும் பூமியின் படைகள் அல்லாஹ்வுக்கே உரியன). அவன் ஒரேயொரு வானவரை அவர்களிடம் அனுப்ப நாடியிருந்தாலும், அந்த வானவர் அவர்கள் கொண்டிருந்த அனைத்தையும் அழித்திருப்பார். எனினும், உயர்ந்தோனாகிய அல்லாஹ், முஃமின்கள் மூலமாக ஜிஹாத் மற்றும் போர் நிறுவப்பட வேண்டும் என்று நாடினான். இதில் அவனுக்குப் பெரும் ஞானமும், தெளிவான காரணங்களும், சந்தேகத்திற்கு இடமற்ற சான்றுகளும் உள்ளன. இதனால்தான் மகத்துவமிக்க அல்லாஹ் அடுத்துக் கூறுகிறான், ﴾وَكَانَ اللَّهُ عَلِيماً حَكِيماً﴿\n\r\n\n\r\n(அல்லாஹ் யாவற்றையும் அறிந்தவனாகவும், ஞானமிக்கவனாகவும் இருக்கிறான்.)\n\r\n\n\r\nஉயர்ந்தோனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான், ﴾لِّيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَـتِ جَنَّـتٍ تَجْرِى مِن تَحْتِهَا الأَنْهَـرُ خَـلِدِينَ فِيهَا﴿\n\r\n\n\r\n(முஃமின்களான ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடும் சுவனச் சோலைகளில் அவர்கள் என்றும் தங்கியிருக்கும் நிலையில் நுழைவிப்பதற்காக,) அனஸ் (ரழி) அவர்கள் அறிவித்த ஒரு ஹதீஸில், ஸஹாபாக்கள் (ரழி), \"அல்லாஹ்வின் தூதரே (ஸல்)! உங்களுக்கு நல்வாழ்த்துகள்! இந்த நற்செய்தி உங்களுக்குரியது, எங்களுக்கு என்ன நற்செய்தி இருக்கிறது?\" என்று கேட்டபோது, உயர்ந்தோனாகிய அல்லாஹ் இந்த வசனத்தை இறக்கினான் என்று குறிப்பிட்டுள்ளோம், ﴾لِّيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَـتِ جَنَّـتٍ تَجْرِى مِن تَحْتِهَا الأَنْهَـرُ خَـلِدِينَ فِيهَا﴿\n\r\n\n\r\n(முஃமின்களான ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடும் சுவனச் சோலைகளில் அவர்கள் என்றும் தங்கியிருக்கும் நிலையில் நுழைவிப்பதற்காக,) அதாவது அவர்கள் சொர்க்கத்தில் நிரந்தரமாகத் தங்கியிருப்பார்கள், ﴾وَيُكَفِّرَ عَنْهُمْ سَيِّئَـتِهِمْ﴿\n\r\n\n\r\n(மேலும் அவர்களின் பாவங்களை அவர்களை விட்டும் போக்கிவிடுவதற்காக;) அவர்களுடைய தவறுகளுக்காக அல்லாஹ் அவர்களைத் தண்டிக்க மாட்டான். மாறாக, அவன் அவர்களை மன்னித்து, பிழைகளைப் பொறுத்து, குற்றங்களை மறைத்து, அவர்களுக்கு அருள் புரிந்து, அவர்களின் நற்செயல்களை அங்கீகரிப்பான், ﴾وَكَانَ ذَلِكَ عِندَ اللَّهِ فَوْزاً عَظِيماً﴿\n\r\n\n\r\n(அல்லாஹ்விடம் இது மகத்தான வெற்றியாகும்.) உயர்ந்தோனாகிய அல்லாஹ் இது போன்றதொரு வசனத்தில் கூறினான், ﴾فَمَن زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ﴿\n\r\n\n\r\n(யார் நரக நெருப்பிலிருந்து அப்புறப்படுத்தப்பட்டு, சுவனத்தில் நுழைவிக்கப்படுகிறாரோ அவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார்.) (3:185)\n\r\n\n\r\nஅல்லாஹ் கூறினான், ﴾وَيُعَذِّبَ الْمُنَـفِقِينَ وَالْمُنَـفِقَـتِ وَالْمُشْرِكِينَ وَالْمُشْرِكَـتِ الظَّانِّينَ بِاللَّهِ ظَنَّ السَّوْءِ﴿\n\r\n\n\r\n(மேலும் நயவஞ்சகர்களான ஆண்களையும் பெண்களையும், இணைவைப்பாளர்களான ஆண்களையும் பெண்களையும், அல்லாஹ்வைப் பற்றித் தீய எண்ணம் கொள்பவர்களையும் அவன் தண்டிப்பதற்காக), அவர்கள் அல்லாஹ்வின் முடிவுகளில் உள்ள ஞானத்தைச் சந்தேகிப்பவர்கள்; மேலும் தூதரும் (ஸல்) அவரது தோழர்களும் (ரழி) கொல்லப்பட்டு, அடியோடு அழிக்கப்பட்டு விடுவார்கள் என்று எண்ணியவர்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான், ﴾عَلَيْهِمْ دَآئِرَةُ السَّوْءِ وَغَضِبَ اللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ﴿\n\r\n\n\r\n(அவர்களுக்குக் கேடான சூழலே அமையும். மேலும் அல்லாஹ்வின் கோபம் அவர்கள் மீது உண்டானது, அவன் அவர்களைச் சபித்தும் விட்டான்) அவன் தனது அருளிலிருந்து அவர்களை அப்புறப்படுத்திவிட்டான், ﴾وَأَعَدَّ لَهُمْ جَهَنَّمَ وَسَآءَتْ مَصِيراً﴿\n\r\n\n\r\n(மேலும் அவர்களுக்காக நரகத்தைச் சித்தம் செய்துள்ளான் - அது மீளுமிடங்களில் மிகவும் கெட்டது.)\n\r\n\n\r\nஉயர்ந்தோனும் கண்ணியமிக்கவனுமான அல்லாஹ், இஸ்லாத்தின் எதிரிகள், நிராகரிப்பாளர்கள் மற்றும் நயவஞ்சகர்களிடம் பழிவாங்கும் தனது ஆற்றலை உறுதிப்படுத்தினான், ﴾وَلِلَّهِ جُنُودُ السَّمَـوَتِ وَالأَرْضِ وَكَانَ اللَّهُ عَزِيزاً حَكِيماً ﴿\n\r\n\n\r\n(வானங்கள் மற்றும் பூமியின் படைகள் அல்லாஹ்வுக்கே உரியன. மேலும் அல்லாஹ் வல்லமை மிக்கவனாகவும், ஞானமிக்கவனாகவும் இருக்கிறான்.)"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=10\" class=\"link\">48:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:10 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=10\" class=\"link\">48:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பண்புகள்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَاكَ</span> <span class=\"quran-arabic-font text-success\">شَاهِداً</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் உம்மை ஒரு சாட்சியாகவும்,) படைப்பினங்களுக்கு<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمُبَشِّراً</span><br />\r\n<br />\r\n(நற்செய்தி கூறுபவராகவும்,) இறைநம்பிக்கையாளர்களுக்கும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَذِيرًا</span><br />\r\n<br />\r\n(மற்றும் எச்சரிக்கை செய்பவராகவும்) நிராகரிப்பாளர்களுக்கும் (அனுப்பியுள்ளோம்). இந்த வசனங்களுக்கான விளக்கத்தை நாம் ஸூரத்துல் அஹ்ஸாபின் தஃப்சீரில் விளக்கியுள்ளோம். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتُؤْمِنُوا</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">وَتُعَزِّرُوهُ</span><br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்வையும் அவனது தூதரையும் ஈமான் கொள்வதற்காகவும், நீங்கள் அவரை கண்ணியப்படுத்துவதற்காகவும்,) ‘துஅஸ்ஸிரூஹு’ என்றால் அவரை நீங்கள் கண்ணியப்படுத்த வேண்டும் என்று இப்னு அப்பாஸ் (ரழி) மற்றும் பலர் கூறியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتُوَقِّرُوهُ</span><br />\r\n<br />\r\n(மேலும் அவரை நீங்கள் மதிக்கவும் கௌரவிக்கவும்,) ‘துவக்கிரூஹு’ என்றால் மரியாதை, கண்ணியம் மற்றும் உயர் மதிப்பைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتُسَبِّحُوهُ</span><br />\r\n<br />\r\n(மேலும் அவனது துதிபாடவும்,) அதாவது அல்லாஹ்வின் புகழைத் துதி செய்யவும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بُكْرَةً</span> <span class=\"quran-arabic-font text-success\">وَأَصِيلاً</span><br />\r\n<br />\r\n(காலையிலும் மாலையிலும்).<br />\r\n<br />\r\n<strong>அர்-ரிழ்வான் உடன்படிக்கை (பைஅத்துர் ரிழ்வான்)</strong><br />\r\n<br />\r\nஉயர்ந்தோனும் கண்ணியமிக்கவனுமான அல்லாஹ் தனது தூதரை கௌரவித்து, புகழ்ந்து கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُبَايِعُونَكَ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يُبَايِعُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(நிச்சயமாக, உங்களிடம் உடன்படிக்கை செய்பவர்கள், அவர்கள் அல்லாஹ்விடமே உடன்படிக்கை செய்கிறார்கள்.) உயர்ந்தோனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">يُطِعِ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَطَاعَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(யார் தூதருக்குக் கீழ்ப்படிகிறாரோ, அவர் நிச்சயமாக அல்லாஹ்வுக்குக் கீழ்ப்படிந்துவிட்டார்.) (<a href=\"qurandisp.php?sura=4&ayah=80\" class=\"link\">4:80</a>). அல்லாஹ் தொடர்ந்து கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَدُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் கை அவர்களின் கைகளுக்கு மேல் இருக்கிறது.) அதாவது, அவன் அவர்களுடன் இருக்கிறான், அவர்களின் கூற்றுகளைச் செவிமடுக்கிறான், அவர்களின் நிலையை நேரில் காண்கிறான்; அவர்களின் உள்ளத்தையும் வெளிப்படையான நிலையையும் அவன் முழுமையாக அறிவான். எனவே, உயர்ந்தோனாகிய அல்லாஹ் உண்மையில் தனது தூதர் (ஸல்) அவர்கள் மூலமாகவே அவர்களிடமிருந்து அந்த உடன்படிக்கையைப் பெற்றான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">اشْتَرَى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">يُقَاتِلُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَيَقْتُلُونَ</span> <span class=\"quran-arabic-font text-success\">وَيُقْتَلُونَ</span> <span class=\"quran-arabic-font text-success\">وَعْدًا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">حَقًّا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">التَّوْرَاةِ</span> <span class=\"quran-arabic-font text-success\">وَالإِنجِيلِ</span> <span class=\"quran-arabic-font text-success\">وَالْقُرْآنِ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَوْفَى</span> <span class=\"quran-arabic-font text-success\">بِعَهْدِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَبْشِرُواْ</span> <span class=\"quran-arabic-font text-success\">بِبَيْعِكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">بَايَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْفَوْزُ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمُ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் இறைநம்பிக்கையாளர்களிடமிருந்து அவர்களின் உயிர்களையும் அவர்களின் உடைமைகளையும் சொர்க்கத்திற்குப் பகரமாக விலைக்கு வாங்கிக் கொண்டான். அவர்கள் அல்லாஹ்வின் பாதையில் போரிடுவார்கள்; அப்போது அவர்கள் கொல்வார்கள், கொல்லப்படுவார்கள். இது தவ்ராத், இன்ஜீல் மற்றும் குர்ஆன் ஆகியவற்றில் அல்லாஹ் உறுதிப்படுத்திய உண்மை வாக்குறுதியாகும். அல்லாஹ்வை விடத் தனது வாக்குறுதியை நிறைவேற்றுவதில் சிறந்தவர் யார்? எனவே, நீங்கள் செய்த இந்த ஒப்பந்தத்திற்காக மகிழ்ச்சி அடையுங்கள். இதுவே மகத்தான வெற்றியாகும்.) (<a href=\"qurandisp.php?sura=9&ayah=111\" class=\"link\">9:111</a>). அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَوْفَى</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَاهَدَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">فَسَيُؤْتِيهِ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span> <span class=\"quran-arabic-font text-success\">عَظِيماً</span><br />\r\n<br />\r\n(...மேலும் எவர் அல்லாஹ்விடம் செய்த உடன்படிக்கையை நிறைவேற்றுகிறாரோ, அவருக்கு அவன் மகத்தான கூலியை வழங்குவான்.) அதாவது தாராளமான வெகுமதி. இங்கு குறிப்பிடப்பட்டுள்ள உடன்படிக்கை, அல்-ஹுதைபிய்யா பகுதியில் இருந்த ‘ஸமுரா’ எனும் ஒரு முள் மரத்தின் கீழ் எடுக்கப்பட்ட ‘பைஅத்துர் ரிழ்வான்’ ஆகும். அந்த நேரத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்த ஸஹாபாக்களின் எண்ணிக்கை 1,300, 1,400 அல்லது 1,500 ஆகக் கூறப்படுகிறது. இருப்பினும், 1,400 என்பதே மிகவும் சரியான கருத்தாகும்.<br />\r\n<br />\r\n<strong>அல்-ஹுதைபிய்யா உடன்படிக்கை பற்றிய ஹதீஸ்கள்</strong><br />\r\n<br />\r\nஅல்-புகாரியில் ஜாபிர் இப்னு அப்துல்லாஹ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது: \"ஹுதைபிய்யா நாளில் நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம்.\" இமாம் முஸ்லிமும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார். புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் ஜாபிர் (ரழி) அவர்கள் இவ்வாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது: \"அந்த நேரத்தில் நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தனது கையைத் தண்ணீரில் வைத்தார்கள், அவர்களின் விரல்களுக்கு இடையில் இருந்து தண்ணீர் ஊற்றெடுத்தது. அனைவரும் தாகம் தீரும் வரை குடித்தனர்.\" இது இந்த நிகழ்வின் சுருக்கமான வடிவம். மற்றொரு அறிவிப்பில் கூறப்படுவதாவது: அல்-ஹுதைபிய்யா நாளில் ஸஹாபாக்கள் தாகத்தால் தவித்தபோது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தனது அம்புறாத்தூணியிலிருந்து ஓர் அம்பை எடுத்து அவர்களிடம் கொடுத்தார்கள். அவர்கள் அந்த அம்பை எடுத்து அல்-ஹுதைபிய்யாவின் வறண்ட கிணற்றுக்குள் வைத்ததும், அதிலிருந்து தண்ணீர் பீறிட்டு வந்தது. அனைவரும் தாகம் தீரும் வரை அருந்தினர். அன்று எத்தனை பேர் இருந்தீர்கள் என்று ஜாபிரிடம் கேட்கப்பட்டபோது, \"நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம். நாங்கள் ஒரு லட்சம் பேராக இருந்திருந்தாலும், அந்தத் தண்ணீர் போதுமானதாக இருந்திருக்கும்\" என்று கூறினார்கள். புகாரி மற்றும் முஸ்லிமில் உள்ள மற்றொரு அறிவிப்பில் ஜாபிர் (ரழி) அவர்கள் தாங்கள் ஆயிரத்து ஐநூறு பேராக இருந்ததாகக் கூறியுள்ளார்கள். இமாம் புகாரி பதிவு செய்துள்ள மற்றோர் அறிவிப்பில், ஸயீத் இப்னுல் முஸய்யப் அவர்களிடம் கத்தாதா (ரழி), \"பைஅத்துர் ரிழ்வானின் போது எத்தனை பேர் இருந்தார்கள்?\" என்று கேட்டபோது, அவர் \"ஆயிரத்து ஐநூறு பேர்\" என்று பதிலளித்தார். அதற்கு கத்தாதா, \"ஜாபிர் இப்னு அப்துல்லாஹ் (ரழி) அவர்கள் ஆயிரத்து நானூறு பேர் என்று கூறுகிறாரே?\" என்று கேட்டதற்கு, ஸயீத் \"அவர் மறந்துவிட்டார்; அவரே என்னிடம் ஆயிரத்து ஐநூறு பேர் என்றுதான் கூறினார்\" என்றார். இது குறித்து இமாம் அல்-பைஹகீ கூறுகையில், \"ஜாபிர் (ரழி) அவர்கள் முதலில் ஆயிரத்து ஐநூறு பேர் என்று கூறிவந்தார், பின்னர் சரியான எண்ணிக்கையை நினைவுகூர்ந்து ஆயிரத்து நானூறு பேர் என்று கூறினார்\" என்று விளக்குகிறார்.<br />\r\n<br />\r\n<strong>அர்-ரிழ்வான் உடன்படிக்கை நடத்தப்பட்டதற்கான காரணம்</strong><br />\r\n<br />\r\nமுஹம்மது இப்னு இஸ்ஹாக் இப்னு யஸார் அவர்கள் தனது ஸீரா நூலில் கூறுகிறார்கள்: குரைஷித் தலைவர்களிடம் நபி (ஸல்) அவர்களின் (உம்ரா செய்யும்) நோக்கத்தைத் தெரிவிப்பதற்காக உமர் இப்னுல் கத்தாப் (ரழி) அவர்களை மக்காவிற்கு அனுப்ப அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அழைத்தார்கள். அதற்கு உமர் (ரழி) அவர்கள், \"அல்லாஹ்வின் தூதரே! குரைஷிகளால் எனது உயிருக்கு ஆபத்து ஏற்படும் என்று நான் அஞ்சுகிறேன். மக்காவில் என்னைப் பாதுகாப்பதற்கு பனூ அதீ இப்னு கஅப் கோத்திரத்தைச் சேர்ந்த எவரும் இப்போது இல்லை. மேலும், குரைஷிகளுக்கு என் மீதான பகையும் எனது கண்டிப்பும் நன்கு தெரியும். இருப்பினும், மக்காவில் என்னை விடவும் செல்வாக்கு மிக்க ஒருவரை நான் உங்களுக்கு அடையாளம் காட்டுகிறேன், அவர் உத்மான் இப்னு அஃப்பான் (ரழி). நாம் அவரை அபூ சுஃப்யான் மற்றும் குரைஷித் தலைவர்களிடம் அனுப்பி, நாம் அவர்களுடன் போரிட வரவில்லை, மாறாக இந்த இறையாலயத்தை (கஃபாவை) தரிசிக்கவும் அதன் புனிதத்தைப் போற்றவுமே வந்துள்ளோம் என்ற செய்தியைத் தெரிவிக்கலாம்\" என்று கூறினார்கள். அதன்படி உத்மான் (ரழி) மக்காவிற்குள் புறப்பட்டார். மக்காவிற்குள் நுழையும்போது அல்லது அதற்குச் சற்று முன்னதாக அவர் அபான் இப்னு ஸயீத் இப்னுல் ஆஸ் என்பவரைச் சந்தித்தார். அபான் அவர்கள் உத்மான் (ரழி) அவர்களுக்குத் தனது பாதுகாப்பை வழங்கி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் செய்தியை மக்காவிற்குள் கொண்டு செல்ல உதவினார். உத்மான் (ரழி) அவர்கள் அபூ சுஃப்யான் மற்றும் குரைஷித் தலைவர்களைச் சந்தித்து நபி (ஸல்) அவர்கள் கூறி அனுப்பிய செய்தியைத் தெரிவித்தார். உத்மான் (ரழி) செய்தியைச் சொல்லி முடித்ததும், குரைஷிகள் அவரிடம் \"நீங்கள் விரும்பினால் இந்த ஆலயத்தை (கஃபாவை) தவாஃப் செய்து கொள்ளலாம்\" என்று கூறினார்கள். அதற்கு உத்மான் (ரழி), \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தவாஃப் செய்வதற்கு முன்னால் நான் தவாஃப் செய்ய மாட்டேன்\" என்று கூறிவிட்டார். இதனால் குரைஷிகள் உத்மான் (ரழி) அவர்களை மக்காவிலேயே தடுத்து வைத்தனர். இதற்கிடையில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கும் முஸ்லிம்களுக்கும் உத்மான் (ரழி) அவர்கள் கொல்லப்பட்டுவிட்டதாகச் செய்தி வந்தது. இப்னு இஸ்ஹாக் கூறுகிறார்: அப்துல்லாஹ் இப்னு அபூபக்கர் எனக்குத் தெரிவித்த செய்தியின்படி, உத்மான் (ரழி) கொல்லப்பட்ட செய்தி வந்ததும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نَبْرَحُ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">نُنَاجِزَ</span> <span class=\"quran-arabic-font text-success\">الْقَوْم</span>»<br />\r\n<br />\r\n(இந்த மக்களுடன் போரிட்டுத் தீர்வு காணும் வரை நாம் இங்கிருந்து நகர மாட்டோம்.) இப்னு இஸ்ஹாக் மேலும் கூறுகிறார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் முஸ்லிம்களை விசுவாசப் பிரமாணம் (பைஅத்) செய்ய அழைத்தார்கள். இவ்வாறுதான் அந்த மரத்தின் அடியில் ‘பைஅத்துர் ரிழ்வான்’ நடைபெற்றது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரணிப்பதற்காகத் தான் மக்களிடம் உடன்படிக்கை பெற்றதாகப் பின்னர் மக்கள் பேசிக்கொண்டனர். ஆனால் ஜாபிர் இப்னு அப்துல்லாஹ் (ரழி) கூறுகையில், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரணிப்பதற்காக எங்களிடம் உடன்படிக்கை கேட்கவில்லை, மாறாகப் போர்க்களத்திலிருந்து நாங்கள் புறங்காட்டி ஓட மாட்டோம் என்பதற்காகவே உடன்படிக்கை வாங்கினார்கள்\" என்று விளக்கினார். முஸ்லிம்கள் அனைவரும் உடன்படிக்கை செய்தார்கள்; பனூ ஸலமா கோத்திரத்தைச் சேர்ந்த அல்-ஜத் இப்னு கைஸைத் தவிர வேறு யாரும் பின்வாங்கவில்லை. \"அவர் தனது ஒட்டகத்தின் மறைவில் பதுங்கிக் கொண்டு, மக்கள் தன்னைப் பார்க்காதவாறு ஒளிந்து கொண்டிருந்ததை நான் இப்போதும் நேரில் பார்ப்பது போல் இருக்கிறது\" என்று ஜாபிர் (ரழி) கூறுவார்கள். சிறிது நேரத்திலேயே உத்மான் (ரழி) கொல்லப்பட்ட செய்தி பொய்யானது என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குத் தெரியவந்தது.<br />\r\n<br />\r\nநாஃபி அவர்கள் கூறியதாக இமாம் புகாரி பதிவு செய்துள்ளதாவது: \"உமர் (ரழி) அவர்களுக்கு முன்பே அப்துல்லாஹ் இப்னு உமர் (ரழி) இஸ்லாத்தை ஏற்றுக்கொண்டதாக மக்கள் கூறினர், ஆனால் இது உண்மையில்லை. ஹுதைபிய்யா நாளில், உமர் (ரழி) அவர்கள் அன்சாரிகளிடம் இருந்த தனது குதிரையை எடுத்து வருவதற்காகத் தனது மகன் அப்துல்லாஹ்வை அனுப்பினார்கள். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரத்தின் கீழ் முஸ்லிம்களிடம் உடன்படிக்கை வாங்கிக் கொண்டிருந்தார்கள். இது உமர் (ரழி) அவர்களுக்குத் தெரியாது. அப்துல்லாஹ் (ரழி) தனது உடன்படிக்கையை முடித்துவிட்டு, குதிரையை எடுத்துக்கொண்டு போருக்குத் தயாராகக் கவசம் அணிந்திருந்த தனது தந்தை உமர் (ரழி) அவர்களிடம் வந்தார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரத்தின் கீழ் உடன்படிக்கை பெற்றுக் கொண்டிருப்பதை அப்துல்லாஹ் தெரிவித்தார். உடனே உமர் (ரழி) அவர்களும் சென்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்தார்கள். இதனால்தான் சிலர் அப்துல்லாஹ் இப்னு உமர் (ரழி) அவர்கள் தனது தந்தைக்கு முன்பே இஸ்லாத்தைத் தழுவியதாகத் தவறாகக் கருதினர்.\" இமாம் புகாரி மற்றோர் அறிவிப்பைப் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்த மக்கள் மரங்களின் நிழல்களில் தங்கியிருந்தபோது, திடீரென மக்கள் நபியைச் சுற்றி ஒன்று கூடினர். அப்போது உமர் (ரழி), \"அப்துல்லாஹ்வே! மக்கள் ஏன் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைச் சுற்றி கூடுகிறார்கள் என்று பார்த்து வா\" என்றார். அப்துல்லாஹ் (ரழி) அங்கு சென்று மக்கள் உடன்படிக்கை செய்வதைக் கண்டு, தானும் உடன்படிக்கை செய்துவிட்டுத் தனது தந்தையிடம் வந்து கூறினார். பின்னர் உமர் (ரழி) அவர்களும் சென்று உடன்படிக்கை செய்தார்கள். இமாம் முஸ்லிம் பதிவு செய்துள்ள ஹதீஸில் ஜாபிர் (ரழி) கூறுகிறார்: \"ஹுதைபிய்யா நாளில் நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம். உமர் (ரழி) அவர்கள் நபியின் கையைப் பிடித்துக் கொண்டிருக்க, அந்த ஸமுரா மரத்தின் கீழ் நாங்கள் உடன்படிக்கை செய்தோம். போரிலிருந்து ஓட மாட்டோம் என்றுதான் உடன்படிக்கை செய்தோமே தவிர, மரணிப்பதற்காக அல்ல.\" மஃகில் இப்னு யஸார் (ரழி) கூறுகிறார்: \"நபியவர்கள் உடன்படிக்கை வாங்கிக் கொண்டிருந்தபோது, நான் மரத்தின் ஒரு கிளையை அவர்களின் தலைக்கு மேல் படாதவாறு பிடித்துக் கொண்டிருந்தேன். நாங்கள் 1,400 பேர் இருந்தோம். நாங்கள் போரிலிருந்து புறங்காட்டி ஓட மாட்டோம் என்றே உடன்படிக்கை செய்தோம்.\" எனினும், ஸலமா இப்னுல் அக்வா (ரழி) அவர்கள் \"நான் மரணிப்பதற்காகவே உடன்படிக்கை செய்தேன்\" என்று கூறியதாக இமாம் புகாரி பதிவு செய்துள்ளார். யஸீத் அவரிடம், \"அபு மஸ்லமாவே! அன்று நீங்கள் எதற்காக உடன்படிக்கை செய்தீர்கள்?\" என்று கேட்டபோது, ஸலமா \"மரணத்திற்காக!\" என்று பதிலளித்தார். மற்றொரு அறிவிப்பில் ஸலமா (ரழி) கூறுகிறார்: \"நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்தபின் ஓரமாக நின்றேன். அப்போது நபி (ஸல்) அவர்கள், 'ஸலமாவே! நீ ஏன் உடன்படிக்கை செய்யவில்லை?' என்று கேட்டார்கள். நான் 'ஏற்கனவே செய்துவிட்டேன்' என்றேன். அவர்கள் 'மீண்டும் வந்து செய்' என்றார்கள். நானும் சென்று மீண்டும் உடன்படிக்கை செய்தேன்.\" அவரிடம் \"எதற்காக?\" என்று கேட்டபோது, \"மரணத்திற்காக\" என்றார்.<br />\r\n<br />\r\nஇமாம் அல்-பைஹகீ பதிவு செய்துள்ள ஸலமா இப்னுல் அக்வா (ரழி) அவர்களின் விரிவான அறிவிப்பில்: \"நாங்கள் 1,400 பேராக ஹுதைபிய்யா சென்றோம். அங்குள்ள ஒரு கிணற்றில் மிகக் குறைந்த அளவே தண்ணீர் இருந்தது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அதன் விளிம்பில் அமர்ந்து பிரார்த்தனை செய்து உமிழ்ந்தார்கள். அதன் பின் தண்ணீர் ஊற்றெடுத்தது. நாங்கள் அனைவரும் அருந்திவிட்டு விலங்குகளுக்கும் புகட்டினோம். பின்னர் நபி (ஸல்) அவர்கள் உடன்படிக்கைக்கு அழைத்தபோது, நான் முதல் ஆளாகச் சென்று செய்தேன். பாதி மக்கள் முடித்தபின், நபி (ஸல்) அவர்கள் மீண்டும் என்னை அழைத்து 'உடன்படிக்கை செய்' என்றார்கள். நான் ஏற்கனவே செய்துவிட்டதாகக் கூறியும், 'மீண்டும் செய்' என்றார்கள். நான் கவசம் அணியாமல் இருந்ததைக் கண்டு அவர்கள் எனக்கு ஒரு கவசத்தை வழங்கினார்கள். இறுதியாக மீண்டும் என்னை அழைத்து 'உடன்படிக்கை செய்' என்றார்கள். நான் மூன்றாவது முறையாகவும் உடன்படிக்கை செய்தேன். அப்போது நபி (ஸல்) அவர்கள், 'ஸலமாவே, உனக்கு நான் கொடுத்த கவசம் எங்கே?' என்று கேட்டார்கள். நான் அதை கேடயம் இல்லாத ஒரு நண்பருக்குக் கொடுத்துவிட்டதாகக் கூறினேன். நபி (ஸல்) அவர்கள் சிரித்துக் கொண்டே, 'நீ முற்கால மனிதர் ஒருவரைப் போல் இருக்கிறாய்; அவர் இறைவனிடம், என்னை விட எனக்குப் பிரியமான ஒரு நபரை எனக்குக் கொடு என்று வேண்டினாராம்' என்று கூறினார்கள். பின்னர் மக்காவினர் சமாதான உடன்படிக்கைக்கு வந்தனர். நான் தல்ஹா இப்னு உபைதுல்லாஹ் (ரழி) அவர்களின் குதிரையைப் பராமரிக்கும் வேலை செய்து வந்தேன். சமாதானம் ஏற்பட்ட பின், மக்கள் தாராளமாகப் பழகத் தொடங்கினர். அப்போது மக்காவைச் சேர்ந்த நால்வர் நபி (ஸல்) அவர்களைப் பற்றி இழிவாகப் பேசியதைக் கேட்டு, நான் விலகிச் சென்று வேறு மரத்தின் நிழலில் அமர்ந்தேன். திடீரென 'இப்னு ஸுனைம் கொல்லப்பட்டுவிட்டார்' என்ற சத்தம் கேட்டதும், நான் என் வாளை எடுத்துக் கொண்டு அந்த நால்வரையும் பிடிக்கச் சென்றேன். அவர்கள் தூங்கிக் கொண்டிருந்தபோது அவர்களின் ஆயுதங்களைக் கைப்பற்றி, 'முஹம்மது (ஸல்) அவர்களின் முகத்தைக் கண்ணியப்படுத்தியவன் மீது ஆணையாக, யாராவது தலையை உயர்த்தினால் வெட்டிவிடுவேன்' என்று எச்சரித்து அவர்களை அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கொண்டு வந்தேன். எனது மாமா ஆமிரும் ஒருவரைப் பிடித்து வந்தார். கைதிகளின் எண்ணிக்கை எழுபதாக உயர்ந்தது. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள், 'அவர்களை விட்டுவிடுங்கள்; வரம்பு மீறலைத் தொடங்கிய பாவம் அவர்களையே சாரட்டும்' என்று கூறி அவர்களை மன்னித்துவிட்டார்கள். இது குறித்தே அல்லாஹ் பின்வரும் வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَفَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُم</span> <span class=\"quran-arabic-font text-success\">بِبَطْنِ</span> <span class=\"quran-arabic-font text-success\">مَكَّةَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَظْفَرَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span><br />\r\n<br />\r\n(அவன்தான் மக்காவின் மையப்பகுதியில், நீங்கள் அவர்களை வென்ற பிறகு, அவர்களின் கைகளை உங்களிடமிருந்தும், உங்கள் கைகளை அவர்களிடமிருந்தும் தடுத்தவன்.) (<a href=\"qurandisp.php?sura=48&ayah=24\" class=\"link\">48:24</a>).\"<br />\r\n<br />\r\nஇமாம் புகாரி மற்றும் முஸ்லிமில் ஸயீத் இப்னுல் முஸய்யப் அவர்கள் கூறியதாக உள்ளதாவது: \"எனது தந்தை மரத்தின் கீழ் உடன்படிக்கை செய்தவர்களில் ஒருவர். அவர் கூறினார்: 'அடுத்த வருடம் நாங்கள் சென்றபோது, அந்த மரத்தை எங்களால் கண்டுபிடிக்க முடியவில்லை. அந்த மரம் எங்கே இருக்கிறது என்று உங்களுக்குத் தெரிந்தால், நீங்கள் எங்களை விட அதிக அறிவுள்ளவர்கள்!'\". ஜாபிர் (ரழி) கூறுகிறார்: \"நபி (ஸல்) அவர்கள் உடன்படிக்கைக்கு அழைத்தபோது, அல்-ஜத் இப்னு கைஸ் என்ற நயவஞ்சகன் தனது ஒட்டகத்தின் பின்னால் ஒளிந்து கொண்டிருந்தான்.\" மற்றொரு அறிவிப்பில் ஜாபிர் (ரழி) கூறுகிறார்: \"அன்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களிடம் 'இன்று நீங்கள் பூமியில் உள்ளவர்களிலேயே சிறந்தவர்கள்' என்று கூறினார்கள். எனக்குப் பார்வை இருந்திருந்தால் அந்த மரத்தை உங்களுக்குக் காட்டியிருப்பேன்.\" இமாம் அஹ்மத் பதிவு செய்துள்ள ஹதீஸில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَدْخُلُ</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">مِمَّنْ</span> <span class=\"quran-arabic-font text-success\">بَايَعَ</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">الشَّجَرَة</span>»<br />\r\n<br />\r\n(அந்த மரத்தின் கீழ் உடன்படிக்கை செய்தவர்களில் எவரும் நரக நெருப்பில் நுழைய மாட்டார்கள்.) மேலும் ஜாபிர் (ரழி) அறிவிக்கிறார்கள்: \"யார் அல்-முரார் மலைப்பாதையில் ஏறுகிறாரோ, அவரது பாவங்கள் பனூ இஸ்ரவேலர்களின் பாவங்கள் மன்னிக்கப்பட்டது போல் மன்னிக்கப்படும் என்று நபி (ஸல்) அவர்கள் கூறினார்கள். அன்சாரிகள் முதலில் ஏறினர். நபி (ஸல்) அவர்கள் கூறினார்கள்: 'அந்தச் சிவப்பு ஒட்டகக்காரனைத் தவிர உங்கள் அனைவருக்கும் மன்னிப்பு உண்டு.' நாங்கள் அந்த மனிதனிடம் (அல்-ஜத் இப்னு கைஸ்) வந்து நபி (ஸல்) அவர்களிடம் மன்னிப்புக் கோருமாறு சொன்னோம். அதற்கு அவன் 'அல்லாஹ்விடம் மன்னிப்புக் கேட்பதை விட எனது தொலைந்து போன ஒட்டகத்தைக் கண்டுபிடிப்பதே எனக்குப் பெரியது' என்று கூறிவிட்டான்.\"<br />\r\n<br />\r\nஇமாம் முஸ்லிம் பதிவு செய்துள்ள மற்றோர் அறிவிப்பில்: \"அல்லாஹ் நாடினால், அந்த மரத்தின் கீழ் உடன்படிக்கை செய்த ஸஹாபாக்களில் எவரும் நரகில் நுழைய மாட்டார்கள்\" என்று நபி (ஸல்) அவர்கள் ஹஃப்ஸா (ரழி) அவர்களிடம் கூறினார்கள். அதற்கு ஹஃப்ஸா (ரழி), \"உங்களில் எவரும் அதைக் (நரகத்தைக்) கடக்காமல் இருக்க மாட்டார்கள்\" (<a href=\"qurandisp.php?sura=19&ayah=71\" class=\"link\">19:71</a>) என்ற வசனத்தை ஓதிக் காட்டினார். அதற்கு நபி (ஸல்) அவர்கள், அதன் அடுத்த வசனமான \"பின்னர் தக்வா உடையவர்களை நாம் காப்பாற்றுவோம், அநியாயக்காரர்களை அதில் மண்டியிட்டவர்களாக விட்டுவிடுவோம்\" (<a href=\"qurandisp.php?sura=19&ayah=72\" class=\"link\">19:72</a>) என்ற வசனத்தை ஓதினார்கள். மேலும் ஹாதிப் இப்னு அபீ பல்தஆ (ரழி) அவர்களின் அடிமை ஒருவர் ஹாதிப் நரகத்திற்குச் செல்வார் என்று கூறியபோது, நபி (ஸல்) அவர்கள், \"நீ பொய் சொல்கிறாய்; அவர் பத்ரிலும் ஹுதைபிய்யாவிலும் கலந்துகொண்டவர், அவர் நரகில் நுழைய மாட்டார்\" என்று பதிலளித்தார்கள். இதனால்தான் அல்லாஹ் இந்தத் தோழர்களைப் புகழ்ந்து பேசுகிறான்.<br />\r\n<br />","text":"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பண்புகள்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான்:\n\r\n\n\r\nإِنَّا أَرْسَلْنَاكَ شَاهِداً\n\r\n\n\r\n(நிச்சயமாக, நாம் உம்மை ஒரு சாட்சியாகவும்,) படைப்பினங்களுக்கு\n\r\n\n\r\nوَمُبَشِّراً\n\r\n\n\r\n(நற்செய்தி கூறுபவராகவும்,) இறைநம்பிக்கையாளர்களுக்கும்\n\r\n\n\r\nوَنَذِيرًا\n\r\n\n\r\n(மற்றும் எச்சரிக்கை செய்பவராகவும்) நிராகரிப்பாளர்களுக்கும் (அனுப்பியுள்ளோம்). இந்த வசனங்களுக்கான விளக்கத்தை நாம் ஸூரத்துல் அஹ்ஸாபின் தஃப்சீரில் விளக்கியுள்ளோம். அல்லாஹ் கூறினான்:\n\r\n\n\r\nلِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وَتُعَزِّرُوهُ\n\r\n\n\r\n(நீங்கள் அல்லாஹ்வையும் அவனது தூதரையும் ஈமான் கொள்வதற்காகவும், நீங்கள் அவரை கண்ணியப்படுத்துவதற்காகவும்,) ‘துஅஸ்ஸிரூஹு’ என்றால் அவரை நீங்கள் கண்ணியப்படுத்த வேண்டும் என்று இப்னு அப்பாஸ் (ரழி) மற்றும் பலர் கூறியுள்ளனர்.\n\r\n\n\r\nوَتُوَقِّرُوهُ\n\r\n\n\r\n(மேலும் அவரை நீங்கள் மதிக்கவும் கௌரவிக்கவும்,) ‘துவக்கிரூஹு’ என்றால் மரியாதை, கண்ணியம் மற்றும் உயர் மதிப்பைக் குறிக்கும்.\n\r\n\n\r\nوَتُسَبِّحُوهُ\n\r\n\n\r\n(மேலும் அவனது துதிபாடவும்,) அதாவது அல்லாஹ்வின் புகழைத் துதி செய்யவும்,\n\r\n\n\r\nبُكْرَةً وَأَصِيلاً\n\r\n\n\r\n(காலையிலும் மாலையிலும்).\n\r\n\n\r\nஅர்-ரிழ்வான் உடன்படிக்கை (பைஅத்துர் ரிழ்வான்)\n\r\n\n\r\nஉயர்ந்தோனும் கண்ணியமிக்கவனுமான அல்லாஹ் தனது தூதரை கௌரவித்து, புகழ்ந்து கூறுகிறான்:\n\r\n\n\r\nإِنَّ الَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ اللَّهَ\n\r\n\n\r\n(நிச்சயமாக, உங்களிடம் உடன்படிக்கை செய்பவர்கள், அவர்கள் அல்லாஹ்விடமே உடன்படிக்கை செய்கிறார்கள்.) உயர்ந்தோனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:\n\r\n\n\r\nمَّنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ\n\r\n\n\r\n(யார் தூதருக்குக் கீழ்ப்படிகிறாரோ, அவர் நிச்சயமாக அல்லாஹ்வுக்குக் கீழ்ப்படிந்துவிட்டார்.) (4:80). அல்லாஹ் தொடர்ந்து கூறினான்:\n\r\n\n\r\nيَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ\n\r\n\n\r\n(அல்லாஹ்வின் கை அவர்களின் கைகளுக்கு மேல் இருக்கிறது.) அதாவது, அவன் அவர்களுடன் இருக்கிறான், அவர்களின் கூற்றுகளைச் செவிமடுக்கிறான், அவர்களின் நிலையை நேரில் காண்கிறான்; அவர்களின் உள்ளத்தையும் வெளிப்படையான நிலையையும் அவன் முழுமையாக அறிவான். எனவே, உயர்ந்தோனாகிய அல்லாஹ் உண்மையில் தனது தூதர் (ஸல்) அவர்கள் மூலமாகவே அவர்களிடமிருந்து அந்த உடன்படிக்கையைப் பெற்றான்.\n\r\n\n\r\nإِنَّ اللَّهَ اشْتَرَى مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ يُقَاتِلُونَ فِى سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاةِ وَالإِنجِيلِ وَالْقُرْآنِ وَمَنْ أَوْفَى بِعَهْدِهِ مِنَ اللَّهِ فَاسْتَبْشِرُواْ بِبَيْعِكُمُ الَّذِى بَايَعْتُمْ بِهِ وَذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் இறைநம்பிக்கையாளர்களிடமிருந்து அவர்களின் உயிர்களையும் அவர்களின் உடைமைகளையும் சொர்க்கத்திற்குப் பகரமாக விலைக்கு வாங்கிக் கொண்டான். அவர்கள் அல்லாஹ்வின் பாதையில் போரிடுவார்கள்; அப்போது அவர்கள் கொல்வார்கள், கொல்லப்படுவார்கள். இது தவ்ராத், இன்ஜீல் மற்றும் குர்ஆன் ஆகியவற்றில் அல்லாஹ் உறுதிப்படுத்திய உண்மை வாக்குறுதியாகும். அல்லாஹ்வை விடத் தனது வாக்குறுதியை நிறைவேற்றுவதில் சிறந்தவர் யார்? எனவே, நீங்கள் செய்த இந்த ஒப்பந்தத்திற்காக மகிழ்ச்சி அடையுங்கள். இதுவே மகத்தான வெற்றியாகும்.) (9:111). அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَنْ أَوْفَى بِمَا عَاهَدَ عَلَيْهُ اللَّهَ فَسَيُؤْتِيهِ أَجْراً عَظِيماً\n\r\n\n\r\n(...மேலும் எவர் அல்லாஹ்விடம் செய்த உடன்படிக்கையை நிறைவேற்றுகிறாரோ, அவருக்கு அவன் மகத்தான கூலியை வழங்குவான்.) அதாவது தாராளமான வெகுமதி. இங்கு குறிப்பிடப்பட்டுள்ள உடன்படிக்கை, அல்-ஹுதைபிய்யா பகுதியில் இருந்த ‘ஸமுரா’ எனும் ஒரு முள் மரத்தின் கீழ் எடுக்கப்பட்ட ‘பைஅத்துர் ரிழ்வான்’ ஆகும். அந்த நேரத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்த ஸஹாபாக்களின் எண்ணிக்கை 1,300, 1,400 அல்லது 1,500 ஆகக் கூறப்படுகிறது. இருப்பினும், 1,400 என்பதே மிகவும் சரியான கருத்தாகும்.\n\r\n\n\r\nஅல்-ஹுதைபிய்யா உடன்படிக்கை பற்றிய ஹதீஸ்கள்\n\r\n\n\r\nஅல்-புகாரியில் ஜாபிர் இப்னு அப்துல்லாஹ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது: \"ஹுதைபிய்யா நாளில் நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம்.\" இமாம் முஸ்லிமும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார். புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் ஜாபிர் (ரழி) அவர்கள் இவ்வாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது: \"அந்த நேரத்தில் நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தனது கையைத் தண்ணீரில் வைத்தார்கள், அவர்களின் விரல்களுக்கு இடையில் இருந்து தண்ணீர் ஊற்றெடுத்தது. அனைவரும் தாகம் தீரும் வரை குடித்தனர்.\" இது இந்த நிகழ்வின் சுருக்கமான வடிவம். மற்றொரு அறிவிப்பில் கூறப்படுவதாவது: அல்-ஹுதைபிய்யா நாளில் ஸஹாபாக்கள் தாகத்தால் தவித்தபோது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தனது அம்புறாத்தூணியிலிருந்து ஓர் அம்பை எடுத்து அவர்களிடம் கொடுத்தார்கள். அவர்கள் அந்த அம்பை எடுத்து அல்-ஹுதைபிய்யாவின் வறண்ட கிணற்றுக்குள் வைத்ததும், அதிலிருந்து தண்ணீர் பீறிட்டு வந்தது. அனைவரும் தாகம் தீரும் வரை அருந்தினர். அன்று எத்தனை பேர் இருந்தீர்கள் என்று ஜாபிரிடம் கேட்கப்பட்டபோது, \"நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம். நாங்கள் ஒரு லட்சம் பேராக இருந்திருந்தாலும், அந்தத் தண்ணீர் போதுமானதாக இருந்திருக்கும்\" என்று கூறினார்கள். புகாரி மற்றும் முஸ்லிமில் உள்ள மற்றொரு அறிவிப்பில் ஜாபிர் (ரழி) அவர்கள் தாங்கள் ஆயிரத்து ஐநூறு பேராக இருந்ததாகக் கூறியுள்ளார்கள். இமாம் புகாரி பதிவு செய்துள்ள மற்றோர் அறிவிப்பில், ஸயீத் இப்னுல் முஸய்யப் அவர்களிடம் கத்தாதா (ரழி), \"பைஅத்துர் ரிழ்வானின் போது எத்தனை பேர் இருந்தார்கள்?\" என்று கேட்டபோது, அவர் \"ஆயிரத்து ஐநூறு பேர்\" என்று பதிலளித்தார். அதற்கு கத்தாதா, \"ஜாபிர் இப்னு அப்துல்லாஹ் (ரழி) அவர்கள் ஆயிரத்து நானூறு பேர் என்று கூறுகிறாரே?\" என்று கேட்டதற்கு, ஸயீத் \"அவர் மறந்துவிட்டார்; அவரே என்னிடம் ஆயிரத்து ஐநூறு பேர் என்றுதான் கூறினார்\" என்றார். இது குறித்து இமாம் அல்-பைஹகீ கூறுகையில், \"ஜாபிர் (ரழி) அவர்கள் முதலில் ஆயிரத்து ஐநூறு பேர் என்று கூறிவந்தார், பின்னர் சரியான எண்ணிக்கையை நினைவுகூர்ந்து ஆயிரத்து நானூறு பேர் என்று கூறினார்\" என்று விளக்குகிறார்.\n\r\n\n\r\nஅர்-ரிழ்வான் உடன்படிக்கை நடத்தப்பட்டதற்கான காரணம்\n\r\n\n\r\nமுஹம்மது இப்னு இஸ்ஹாக் இப்னு யஸார் அவர்கள் தனது ஸீரா நூலில் கூறுகிறார்கள்: குரைஷித் தலைவர்களிடம் நபி (ஸல்) அவர்களின் (உம்ரா செய்யும்) நோக்கத்தைத் தெரிவிப்பதற்காக உமர் இப்னுல் கத்தாப் (ரழி) அவர்களை மக்காவிற்கு அனுப்ப அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அழைத்தார்கள். அதற்கு உமர் (ரழி) அவர்கள், \"அல்லாஹ்வின் தூதரே! குரைஷிகளால் எனது உயிருக்கு ஆபத்து ஏற்படும் என்று நான் அஞ்சுகிறேன். மக்காவில் என்னைப் பாதுகாப்பதற்கு பனூ அதீ இப்னு கஅப் கோத்திரத்தைச் சேர்ந்த எவரும் இப்போது இல்லை. மேலும், குரைஷிகளுக்கு என் மீதான பகையும் எனது கண்டிப்பும் நன்கு தெரியும். இருப்பினும், மக்காவில் என்னை விடவும் செல்வாக்கு மிக்க ஒருவரை நான் உங்களுக்கு அடையாளம் காட்டுகிறேன், அவர் உத்மான் இப்னு அஃப்பான் (ரழி). நாம் அவரை அபூ சுஃப்யான் மற்றும் குரைஷித் தலைவர்களிடம் அனுப்பி, நாம் அவர்களுடன் போரிட வரவில்லை, மாறாக இந்த இறையாலயத்தை (கஃபாவை) தரிசிக்கவும் அதன் புனிதத்தைப் போற்றவுமே வந்துள்ளோம் என்ற செய்தியைத் தெரிவிக்கலாம்\" என்று கூறினார்கள். அதன்படி உத்மான் (ரழி) மக்காவிற்குள் புறப்பட்டார். மக்காவிற்குள் நுழையும்போது அல்லது அதற்குச் சற்று முன்னதாக அவர் அபான் இப்னு ஸயீத் இப்னுல் ஆஸ் என்பவரைச் சந்தித்தார். அபான் அவர்கள் உத்மான் (ரழி) அவர்களுக்குத் தனது பாதுகாப்பை வழங்கி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் செய்தியை மக்காவிற்குள் கொண்டு செல்ல உதவினார். உத்மான் (ரழி) அவர்கள் அபூ சுஃப்யான் மற்றும் குரைஷித் தலைவர்களைச் சந்தித்து நபி (ஸல்) அவர்கள் கூறி அனுப்பிய செய்தியைத் தெரிவித்தார். உத்மான் (ரழி) செய்தியைச் சொல்லி முடித்ததும், குரைஷிகள் அவரிடம் \"நீங்கள் விரும்பினால் இந்த ஆலயத்தை (கஃபாவை) தவாஃப் செய்து கொள்ளலாம்\" என்று கூறினார்கள். அதற்கு உத்மான் (ரழி), \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தவாஃப் செய்வதற்கு முன்னால் நான் தவாஃப் செய்ய மாட்டேன்\" என்று கூறிவிட்டார். இதனால் குரைஷிகள் உத்மான் (ரழி) அவர்களை மக்காவிலேயே தடுத்து வைத்தனர். இதற்கிடையில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கும் முஸ்லிம்களுக்கும் உத்மான் (ரழி) அவர்கள் கொல்லப்பட்டுவிட்டதாகச் செய்தி வந்தது. இப்னு இஸ்ஹாக் கூறுகிறார்: அப்துல்லாஹ் இப்னு அபூபக்கர் எனக்குத் தெரிவித்த செய்தியின்படி, உத்மான் (ரழி) கொல்லப்பட்ட செய்தி வந்ததும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا نَبْرَحُ حَتَّى نُنَاجِزَ الْقَوْم»\n\r\n\n\r\n(இந்த மக்களுடன் போரிட்டுத் தீர்வு காணும் வரை நாம் இங்கிருந்து நகர மாட்டோம்.) இப்னு இஸ்ஹாக் மேலும் கூறுகிறார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் முஸ்லிம்களை விசுவாசப் பிரமாணம் (பைஅத்) செய்ய அழைத்தார்கள். இவ்வாறுதான் அந்த மரத்தின் அடியில் ‘பைஅத்துர் ரிழ்வான்’ நடைபெற்றது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரணிப்பதற்காகத் தான் மக்களிடம் உடன்படிக்கை பெற்றதாகப் பின்னர் மக்கள் பேசிக்கொண்டனர். ஆனால் ஜாபிர் இப்னு அப்துல்லாஹ் (ரழி) கூறுகையில், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரணிப்பதற்காக எங்களிடம் உடன்படிக்கை கேட்கவில்லை, மாறாகப் போர்க்களத்திலிருந்து நாங்கள் புறங்காட்டி ஓட மாட்டோம் என்பதற்காகவே உடன்படிக்கை வாங்கினார்கள்\" என்று விளக்கினார். முஸ்லிம்கள் அனைவரும் உடன்படிக்கை செய்தார்கள்; பனூ ஸலமா கோத்திரத்தைச் சேர்ந்த அல்-ஜத் இப்னு கைஸைத் தவிர வேறு யாரும் பின்வாங்கவில்லை. \"அவர் தனது ஒட்டகத்தின் மறைவில் பதுங்கிக் கொண்டு, மக்கள் தன்னைப் பார்க்காதவாறு ஒளிந்து கொண்டிருந்ததை நான் இப்போதும் நேரில் பார்ப்பது போல் இருக்கிறது\" என்று ஜாபிர் (ரழி) கூறுவார்கள். சிறிது நேரத்திலேயே உத்மான் (ரழி) கொல்லப்பட்ட செய்தி பொய்யானது என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குத் தெரியவந்தது.\n\r\n\n\r\nநாஃபி அவர்கள் கூறியதாக இமாம் புகாரி பதிவு செய்துள்ளதாவது: \"உமர் (ரழி) அவர்களுக்கு முன்பே அப்துல்லாஹ் இப்னு உமர் (ரழி) இஸ்லாத்தை ஏற்றுக்கொண்டதாக மக்கள் கூறினர், ஆனால் இது உண்மையில்லை. ஹுதைபிய்யா நாளில், உமர் (ரழி) அவர்கள் அன்சாரிகளிடம் இருந்த தனது குதிரையை எடுத்து வருவதற்காகத் தனது மகன் அப்துல்லாஹ்வை அனுப்பினார்கள். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரத்தின் கீழ் முஸ்லிம்களிடம் உடன்படிக்கை வாங்கிக் கொண்டிருந்தார்கள். இது உமர் (ரழி) அவர்களுக்குத் தெரியாது. அப்துல்லாஹ் (ரழி) தனது உடன்படிக்கையை முடித்துவிட்டு, குதிரையை எடுத்துக்கொண்டு போருக்குத் தயாராகக் கவசம் அணிந்திருந்த தனது தந்தை உமர் (ரழி) அவர்களிடம் வந்தார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரத்தின் கீழ் உடன்படிக்கை பெற்றுக் கொண்டிருப்பதை அப்துல்லாஹ் தெரிவித்தார். உடனே உமர் (ரழி) அவர்களும் சென்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்தார்கள். இதனால்தான் சிலர் அப்துல்லாஹ் இப்னு உமர் (ரழி) அவர்கள் தனது தந்தைக்கு முன்பே இஸ்லாத்தைத் தழுவியதாகத் தவறாகக் கருதினர்.\" இமாம் புகாரி மற்றோர் அறிவிப்பைப் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்த மக்கள் மரங்களின் நிழல்களில் தங்கியிருந்தபோது, திடீரென மக்கள் நபியைச் சுற்றி ஒன்று கூடினர். அப்போது உமர் (ரழி), \"அப்துல்லாஹ்வே! மக்கள் ஏன் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைச் சுற்றி கூடுகிறார்கள் என்று பார்த்து வா\" என்றார். அப்துல்லாஹ் (ரழி) அங்கு சென்று மக்கள் உடன்படிக்கை செய்வதைக் கண்டு, தானும் உடன்படிக்கை செய்துவிட்டுத் தனது தந்தையிடம் வந்து கூறினார். பின்னர் உமர் (ரழி) அவர்களும் சென்று உடன்படிக்கை செய்தார்கள். இமாம் முஸ்லிம் பதிவு செய்துள்ள ஹதீஸில் ஜாபிர் (ரழி) கூறுகிறார்: \"ஹுதைபிய்யா நாளில் நாங்கள் ஆயிரத்து நானூறு பேராக இருந்தோம். உமர் (ரழி) அவர்கள் நபியின் கையைப் பிடித்துக் கொண்டிருக்க, அந்த ஸமுரா மரத்தின் கீழ் நாங்கள் உடன்படிக்கை செய்தோம். போரிலிருந்து ஓட மாட்டோம் என்றுதான் உடன்படிக்கை செய்தோமே தவிர, மரணிப்பதற்காக அல்ல.\" மஃகில் இப்னு யஸார் (ரழி) கூறுகிறார்: \"நபியவர்கள் உடன்படிக்கை வாங்கிக் கொண்டிருந்தபோது, நான் மரத்தின் ஒரு கிளையை அவர்களின் தலைக்கு மேல் படாதவாறு பிடித்துக் கொண்டிருந்தேன். நாங்கள் 1,400 பேர் இருந்தோம். நாங்கள் போரிலிருந்து புறங்காட்டி ஓட மாட்டோம் என்றே உடன்படிக்கை செய்தோம்.\" எனினும், ஸலமா இப்னுல் அக்வா (ரழி) அவர்கள் \"நான் மரணிப்பதற்காகவே உடன்படிக்கை செய்தேன்\" என்று கூறியதாக இமாம் புகாரி பதிவு செய்துள்ளார். யஸீத் அவரிடம், \"அபு மஸ்லமாவே! அன்று நீங்கள் எதற்காக உடன்படிக்கை செய்தீர்கள்?\" என்று கேட்டபோது, ஸலமா \"மரணத்திற்காக!\" என்று பதிலளித்தார். மற்றொரு அறிவிப்பில் ஸலமா (ரழி) கூறுகிறார்: \"நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்தபின் ஓரமாக நின்றேன். அப்போது நபி (ஸல்) அவர்கள், 'ஸலமாவே! நீ ஏன் உடன்படிக்கை செய்யவில்லை?' என்று கேட்டார்கள். நான் 'ஏற்கனவே செய்துவிட்டேன்' என்றேன். அவர்கள் 'மீண்டும் வந்து செய்' என்றார்கள். நானும் சென்று மீண்டும் உடன்படிக்கை செய்தேன்.\" அவரிடம் \"எதற்காக?\" என்று கேட்டபோது, \"மரணத்திற்காக\" என்றார்.\n\r\n\n\r\nஇமாம் அல்-பைஹகீ பதிவு செய்துள்ள ஸலமா இப்னுல் அக்வா (ரழி) அவர்களின் விரிவான அறிவிப்பில்: \"நாங்கள் 1,400 பேராக ஹுதைபிய்யா சென்றோம். அங்குள்ள ஒரு கிணற்றில் மிகக் குறைந்த அளவே தண்ணீர் இருந்தது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அதன் விளிம்பில் அமர்ந்து பிரார்த்தனை செய்து உமிழ்ந்தார்கள். அதன் பின் தண்ணீர் ஊற்றெடுத்தது. நாங்கள் அனைவரும் அருந்திவிட்டு விலங்குகளுக்கும் புகட்டினோம். பின்னர் நபி (ஸல்) அவர்கள் உடன்படிக்கைக்கு அழைத்தபோது, நான் முதல் ஆளாகச் சென்று செய்தேன். பாதி மக்கள் முடித்தபின், நபி (ஸல்) அவர்கள் மீண்டும் என்னை அழைத்து 'உடன்படிக்கை செய்' என்றார்கள். நான் ஏற்கனவே செய்துவிட்டதாகக் கூறியும், 'மீண்டும் செய்' என்றார்கள். நான் கவசம் அணியாமல் இருந்ததைக் கண்டு அவர்கள் எனக்கு ஒரு கவசத்தை வழங்கினார்கள். இறுதியாக மீண்டும் என்னை அழைத்து 'உடன்படிக்கை செய்' என்றார்கள். நான் மூன்றாவது முறையாகவும் உடன்படிக்கை செய்தேன். அப்போது நபி (ஸல்) அவர்கள், 'ஸலமாவே, உனக்கு நான் கொடுத்த கவசம் எங்கே?' என்று கேட்டார்கள். நான் அதை கேடயம் இல்லாத ஒரு நண்பருக்குக் கொடுத்துவிட்டதாகக் கூறினேன். நபி (ஸல்) அவர்கள் சிரித்துக் கொண்டே, 'நீ முற்கால மனிதர் ஒருவரைப் போல் இருக்கிறாய்; அவர் இறைவனிடம், என்னை விட எனக்குப் பிரியமான ஒரு நபரை எனக்குக் கொடு என்று வேண்டினாராம்' என்று கூறினார்கள். பின்னர் மக்காவினர் சமாதான உடன்படிக்கைக்கு வந்தனர். நான் தல்ஹா இப்னு உபைதுல்லாஹ் (ரழி) அவர்களின் குதிரையைப் பராமரிக்கும் வேலை செய்து வந்தேன். சமாதானம் ஏற்பட்ட பின், மக்கள் தாராளமாகப் பழகத் தொடங்கினர். அப்போது மக்காவைச் சேர்ந்த நால்வர் நபி (ஸல்) அவர்களைப் பற்றி இழிவாகப் பேசியதைக் கேட்டு, நான் விலகிச் சென்று வேறு மரத்தின் நிழலில் அமர்ந்தேன். திடீரென 'இப்னு ஸுனைம் கொல்லப்பட்டுவிட்டார்' என்ற சத்தம் கேட்டதும், நான் என் வாளை எடுத்துக் கொண்டு அந்த நால்வரையும் பிடிக்கச் சென்றேன். அவர்கள் தூங்கிக் கொண்டிருந்தபோது அவர்களின் ஆயுதங்களைக் கைப்பற்றி, 'முஹம்மது (ஸல்) அவர்களின் முகத்தைக் கண்ணியப்படுத்தியவன் மீது ஆணையாக, யாராவது தலையை உயர்த்தினால் வெட்டிவிடுவேன்' என்று எச்சரித்து அவர்களை அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கொண்டு வந்தேன். எனது மாமா ஆமிரும் ஒருவரைப் பிடித்து வந்தார். கைதிகளின் எண்ணிக்கை எழுபதாக உயர்ந்தது. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள், 'அவர்களை விட்டுவிடுங்கள்; வரம்பு மீறலைத் தொடங்கிய பாவம் அவர்களையே சாரட்டும்' என்று கூறி அவர்களை மன்னித்துவிட்டார்கள். இது குறித்தே அல்லாஹ் பின்வரும் வசனத்தை இறக்கினான்:\n\r\n\n\r\nوَهُوَ الَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِن بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ\n\r\n\n\r\n(அவன்தான் மக்காவின் மையப்பகுதியில், நீங்கள் அவர்களை வென்ற பிறகு, அவர்களின் கைகளை உங்களிடமிருந்தும், உங்கள் கைகளை அவர்களிடமிருந்தும் தடுத்தவன்.) (48:24).\"\n\r\n\n\r\nஇமாம் புகாரி மற்றும் முஸ்லிமில் ஸயீத் இப்னுல் முஸய்யப் அவர்கள் கூறியதாக உள்ளதாவது: \"எனது தந்தை மரத்தின் கீழ் உடன்படிக்கை செய்தவர்களில் ஒருவர். அவர் கூறினார்: 'அடுத்த வருடம் நாங்கள் சென்றபோது, அந்த மரத்தை எங்களால் கண்டுபிடிக்க முடியவில்லை. அந்த மரம் எங்கே இருக்கிறது என்று உங்களுக்குத் தெரிந்தால், நீங்கள் எங்களை விட அதிக அறிவுள்ளவர்கள்!'\". ஜாபிர் (ரழி) கூறுகிறார்: \"நபி (ஸல்) அவர்கள் உடன்படிக்கைக்கு அழைத்தபோது, அல்-ஜத் இப்னு கைஸ் என்ற நயவஞ்சகன் தனது ஒட்டகத்தின் பின்னால் ஒளிந்து கொண்டிருந்தான்.\" மற்றொரு அறிவிப்பில் ஜாபிர் (ரழி) கூறுகிறார்: \"அன்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களிடம் 'இன்று நீங்கள் பூமியில் உள்ளவர்களிலேயே சிறந்தவர்கள்' என்று கூறினார்கள். எனக்குப் பார்வை இருந்திருந்தால் அந்த மரத்தை உங்களுக்குக் காட்டியிருப்பேன்.\" இமாம் அஹ்மத் பதிவு செய்துள்ள ஹதீஸில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا يَدْخُلُ النَّارَ أَحَدٌ مِمَّنْ بَايَعَ تَحْتَ الشَّجَرَة»\n\r\n\n\r\n(அந்த மரத்தின் கீழ் உடன்படிக்கை செய்தவர்களில் எவரும் நரக நெருப்பில் நுழைய மாட்டார்கள்.) மேலும் ஜாபிர் (ரழி) அறிவிக்கிறார்கள்: \"யார் அல்-முரார் மலைப்பாதையில் ஏறுகிறாரோ, அவரது பாவங்கள் பனூ இஸ்ரவேலர்களின் பாவங்கள் மன்னிக்கப்பட்டது போல் மன்னிக்கப்படும் என்று நபி (ஸல்) அவர்கள் கூறினார்கள். அன்சாரிகள் முதலில் ஏறினர். நபி (ஸல்) அவர்கள் கூறினார்கள்: 'அந்தச் சிவப்பு ஒட்டகக்காரனைத் தவிர உங்கள் அனைவருக்கும் மன்னிப்பு உண்டு.' நாங்கள் அந்த மனிதனிடம் (அல்-ஜத் இப்னு கைஸ்) வந்து நபி (ஸல்) அவர்களிடம் மன்னிப்புக் கோருமாறு சொன்னோம். அதற்கு அவன் 'அல்லாஹ்விடம் மன்னிப்புக் கேட்பதை விட எனது தொலைந்து போன ஒட்டகத்தைக் கண்டுபிடிப்பதே எனக்குப் பெரியது' என்று கூறிவிட்டான்.\"\n\r\n\n\r\nஇமாம் முஸ்லிம் பதிவு செய்துள்ள மற்றோர் அறிவிப்பில்: \"அல்லாஹ் நாடினால், அந்த மரத்தின் கீழ் உடன்படிக்கை செய்த ஸஹாபாக்களில் எவரும் நரகில் நுழைய மாட்டார்கள்\" என்று நபி (ஸல்) அவர்கள் ஹஃப்ஸா (ரழி) அவர்களிடம் கூறினார்கள். அதற்கு ஹஃப்ஸா (ரழி), \"உங்களில் எவரும் அதைக் (நரகத்தைக்) கடக்காமல் இருக்க மாட்டார்கள்\" (19:71) என்ற வசனத்தை ஓதிக் காட்டினார். அதற்கு நபி (ஸல்) அவர்கள், அதன் அடுத்த வசனமான \"பின்னர் தக்வா உடையவர்களை நாம் காப்பாற்றுவோம், அநியாயக்காரர்களை அதில் மண்டியிட்டவர்களாக விட்டுவிடுவோம்\" (19:72) என்ற வசனத்தை ஓதினார்கள். மேலும் ஹாதிப் இப்னு அபீ பல்தஆ (ரழி) அவர்களின் அடிமை ஒருவர் ஹாதிப் நரகத்திற்குச் செல்வார் என்று கூறியபோது, நபி (ஸல்) அவர்கள், \"நீ பொய் சொல்கிறாய்; அவர் பத்ரிலும் ஹுதைபிய்யாவிலும் கலந்துகொண்டவர், அவர் நரகில் நுழைய மாட்டார்\" என்று பதிலளித்தார்கள். இதனால்தான் அல்லாஹ் இந்தத் தோழர்களைப் புகழ்ந்து பேசுகிறான்."},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=14\" class=\"link\">48:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=14\" class=\"link\">48:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=14\" class=\"link\">48:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>அல்-ஹுதைபிய்யாவில் பங்கேற்காமல் பின்தங்கியவர்கள் கூறிய பொய்யான காரணங்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் (ஹுதைபிய்யாவிற்குப்) புறப்படாமல், தங்கள் வீடுகளிலும் செல்வங்களிலும் தங்கியிருக்க விரும்பிய கிராமப்புற அரபிகள் (அஃராபிகள்), தாம் பின்தங்கியதற்காகக் கூறப்போகும் சாக்குப்போக்குகளைப் பற்றி அல்லாஹ் தன் தூதருக்கு அறிவிக்கிறான். தங்களின் வீடுகளையும் செல்வங்களையும் பராமரிப்பதில் தாங்கள் மும்முரமாக இருந்ததாகப் பின்தங்கியதற்குக் காரணம் கூறினார்கள்! மேலும், தங்களை மன்னிக்குமாறு அல்லாஹ்விடம் பிரார்த்திக்கும்படி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அவர்கள் கேட்டுக் கொண்டனர். இது, நபியின் மீதோ அல்லது அவரது பிரார்த்தனையின் மீதோ அவர்களுக்கு இருந்த நம்பிக்கையினால் அல்ல; மாறாக, வெளிப்பகட்டிற்காகவும் நடிப்பதற்காகவுமே இவ்வாறு செய்தார்கள். இதனால்தான் கண்ணியமிக்க அல்லாஹ் அவர்களைப் பற்றிக் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">بِأَلْسِنَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">بِكُمْ</span> <span class=\"quran-arabic-font text-success\">ضَرّاً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">بِكُمْ</span> <span class=\"quran-arabic-font text-success\">نَفْعاً</span><br />\r\n<br />\r\n(தங்கள் உள்ளங்களில் இல்லாதவற்றைத் தங்கள் நாவுகளால் அவர்கள் கூறுகிறார்கள். (நபியே!) நீர் கூறுவீராக: \"அல்லாஹ் உங்களுக்கு ஏதேனும் தீங்கை நாடினாலோ அல்லது உங்களுக்கு ஏதேனும் நன்மையை நாடினாலோ, அவனிடமிருந்து எதனையும் உங்களுக்காகத் தடுத்து நிறுத்தக் கூடியவர் யார்?\") உங்கள் விஷயத்தில் அல்லாஹ் எதை முடிவு செய்தாலும் அதை எவராலும் தடுக்க முடியாது என்று அல்லாஹ் கூறுகிறான்; எல்லாப் புகழும் கண்ணியமும் அவனுக்கே உரியது. நீங்கள் எங்களிடம் நடிப்பைத் தேர்ந்தெடுத்து நயவஞ்சகமாக நடந்துகொண்டாலும், உங்கள் இரகசியங்களையும் உங்கள் உள்ளங்கள் மறைப்பதையும் அல்லாஹ் நன்கு அறிந்தவன். இதனால்தான் கண்ணியமிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">خَبِيراً</span><br />\r\n<br />\r\n(மாறாக, நீங்கள் செய்வதை அல்லாஹ் நன்கு அறிந்தவனாக இருக்கிறான்.) பிறகு அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">ظَنَنْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">لَّن</span> <span class=\"quran-arabic-font text-success\">يَنقَلِبَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولُ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِيهِمْ</span> <span class=\"quran-arabic-font text-success\">أَبَداً</span> <span class=\"quran-arabic-font text-success\">وَظُيِّنَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِكُمْ</span><br />\r\n<br />\r\n(மாறாக, இத்தூதரும் முஃமின்களும் தங்கள் குடும்பத்தாரிடம் ஒருபோதும் திரும்பி வரமாட்டார்கள் என்று நீங்கள் எண்ணிக் கொண்டீர்கள்; மேலும், இது உங்கள் உள்ளங்களில் அழகாக்கப்பட்டு விட்டது.) “நீங்கள் பின்தங்கியது ஏதோ மன்னிக்கத்தக்க ஒரு காரணத்தினாலோ அல்லது ஒரு சாதாரணப் பாவமோ அல்ல. மாறாக, உங்கள் நயவஞ்சகத்தினாலும், முஸ்லிம்கள் அனைவரும் முற்றிலும் அழிக்கப்பட்டுவிடுவார்கள், அவர்களின் வாழ்வு முடிந்துவிடும், அவர்களில் எவருமே மீண்டும் உயிருடன் திரும்ப மாட்டார்கள் என்று நீங்கள் தவறாகக் கருதியதாலுமே நீங்கள் பின்தங்கினீர்கள்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَظَنَنتُمْ</span> <span class=\"quran-arabic-font text-success\">ظَنَّ</span> <span class=\"quran-arabic-font text-success\">السَّوْءِ</span> <span class=\"quran-arabic-font text-success\">وَكُنتُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">بُوراً</span><br />\r\n<br />\r\n(மேலும் நீங்கள் ஒரு தீய எண்ணத்தை எண்ணினீர்கள்; அதன் காரணமாக நீங்கள் அழிந்துபோகும் சமூகமாகி விட்டீர்கள்.) அப்துல்லாஹ் இப்னு அப்பாஸ் (ரழி), முஜாஹித் மற்றும் பலரின் கூற்றுப்படி, 'பூர்' (Bur) என்பது அழிவை நோக்கிச் செல்பவர்கள் என்று பொருள்படும். கத்தாதா அவர்கள் இதற்கு 'சீரழிந்தவர்கள்' என்று விளக்கமளித்தார். மேலும் சிலர், இது ஓமன் பகுதி அரபு வட்டார வழக்கில் உள்ள ஒரு சொல் என்று கூறினர். கண்ணியமிக்க அல்லாஹ் பிறகு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِن</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّآ</span> <span class=\"quran-arabic-font text-success\">أَعْتَدْنَا</span> <span class=\"quran-arabic-font text-success\">لِلْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">سَعِيراً</span><br />\r\n<br />\r\n(மேலும், எவர் அல்லாஹ்வின் மீதும் அவனது தூதர் மீதும் நம்பிக்கை கொள்ளவில்லையோ, நிச்சயமாக நாம் காஃபிர்களுக்குக் கொழுந்து விட்டெரியும் நரக நெருப்பையே சித்தப்படுத்தி வைத்துள்ளோம்.) எவர் தனது செயல்களைப் புறத்தூய்மையுடனும் அகத்தூய்மையுடனும் அல்லாஹ்விற்காக மட்டும் அர்ப்பணிக்கவில்லையோ, அவருக்குக் கொழுந்துவிட்டெரியும் நரக நெருப்பைக் கொண்டு அல்லாஹ் தண்டனை வழங்குவான் என்று இங்கே குறிப்பிடுகிறான். தான் ஈமானைப் பின்பற்றுவதாக மற்றவர்களுக்குக் காட்டிக்கொண்டாலும், அது அவனது உண்மையான கொள்கைக்கு முரணாக இருந்தால் அவன் தண்டிக்கப்படுவான். பின்னர், வானங்கள் மற்றும் பூமியில் உள்ளவை மீது முழுக் கட்டுப்பாடு கொண்ட ஒரே அதிகாரம், அரசன் மற்றும் உரிமையாளன் அல்லாஹ்வே என்று அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">يَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَيُعَذِّبُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً</span><br />\r\n<br />\r\n((வானங்கள் மற்றும் பூமியின் ஆட்சி அல்லாஹ்வுக்கே உரியது.) தான் நாடியவரை அவன் மன்னிக்கிறான், தான் நாடியவரைத் தண்டிக்கிறான். மேலும் அல்லாஹ் மிகவும் மன்னிப்பவனாகவும், மகா கருணையுடையவனாகவும் இருக்கிறான்.) பாவமன்னிப்புக் கோரி அவனிடம் திரும்பி வந்து, தாழ்மையுடன் அவனுக்குப் பணிந்தவர்களிடம் அவன் கருணையுள்ளவனாக இருக்கிறான்.<br />\r\n<br />","text":"அல்-ஹுதைபிய்யாவில் பங்கேற்காமல் பின்தங்கியவர்கள் கூறிய பொய்யான காரணங்கள்\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் (ஹுதைபிய்யாவிற்குப்) புறப்படாமல், தங்கள் வீடுகளிலும் செல்வங்களிலும் தங்கியிருக்க விரும்பிய கிராமப்புற அரபிகள் (அஃராபிகள்), தாம் பின்தங்கியதற்காகக் கூறப்போகும் சாக்குப்போக்குகளைப் பற்றி அல்லாஹ் தன் தூதருக்கு அறிவிக்கிறான். தங்களின் வீடுகளையும் செல்வங்களையும் பராமரிப்பதில் தாங்கள் மும்முரமாக இருந்ததாகப் பின்தங்கியதற்குக் காரணம் கூறினார்கள்! மேலும், தங்களை மன்னிக்குமாறு அல்லாஹ்விடம் பிரார்த்திக்கும்படி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அவர்கள் கேட்டுக் கொண்டனர். இது, நபியின் மீதோ அல்லது அவரது பிரார்த்தனையின் மீதோ அவர்களுக்கு இருந்த நம்பிக்கையினால் அல்ல; மாறாக, வெளிப்பகட்டிற்காகவும் நடிப்பதற்காகவுமே இவ்வாறு செய்தார்கள். இதனால்தான் கண்ணியமிக்க அல்லாஹ் அவர்களைப் பற்றிக் கூறினான்:\n\r\n\n\r\nيَقُولُونَ بِأَلْسِنَتِهِمْ مَّا لَيْسَ فِى قُلُوبِهِمْ قُلْ فَمَن يَمْلِكُ لَكُمْ مِّنَ اللَّهِ شَيْئاً إِنْ أَرَادَ بِكُمْ ضَرّاً أَوْ أَرَادَ بِكُمْ نَفْعاً\n\r\n\n\r\n(தங்கள் உள்ளங்களில் இல்லாதவற்றைத் தங்கள் நாவுகளால் அவர்கள் கூறுகிறார்கள். (நபியே!) நீர் கூறுவீராக: \"அல்லாஹ் உங்களுக்கு ஏதேனும் தீங்கை நாடினாலோ அல்லது உங்களுக்கு ஏதேனும் நன்மையை நாடினாலோ, அவனிடமிருந்து எதனையும் உங்களுக்காகத் தடுத்து நிறுத்தக் கூடியவர் யார்?\") உங்கள் விஷயத்தில் அல்லாஹ் எதை முடிவு செய்தாலும் அதை எவராலும் தடுக்க முடியாது என்று அல்லாஹ் கூறுகிறான்; எல்லாப் புகழும் கண்ணியமும் அவனுக்கே உரியது. நீங்கள் எங்களிடம் நடிப்பைத் தேர்ந்தெடுத்து நயவஞ்சகமாக நடந்துகொண்டாலும், உங்கள் இரகசியங்களையும் உங்கள் உள்ளங்கள் மறைப்பதையும் அல்லாஹ் நன்கு அறிந்தவன். இதனால்தான் கண்ணியமிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nبَلْ كَانَ اللَّهُ بِمَا تَعْمَلُونَ خَبِيراً\n\r\n\n\r\n(மாறாக, நீங்கள் செய்வதை அல்லாஹ் நன்கு அறிந்தவனாக இருக்கிறான்.) பிறகு அல்லாஹ் கூறினான்:\n\r\n\n\r\nبَلْ ظَنَنْتُمْ أَن لَّن يَنقَلِبَ الرَّسُولُ وَالْمُؤْمِنُونَ إِلَى أَهْلِيهِمْ أَبَداً وَظُيِّنَ ذَلِكَ فِى قُلُوبِكُمْ\n\r\n\n\r\n(மாறாக, இத்தூதரும் முஃமின்களும் தங்கள் குடும்பத்தாரிடம் ஒருபோதும் திரும்பி வரமாட்டார்கள் என்று நீங்கள் எண்ணிக் கொண்டீர்கள்; மேலும், இது உங்கள் உள்ளங்களில் அழகாக்கப்பட்டு விட்டது.) “நீங்கள் பின்தங்கியது ஏதோ மன்னிக்கத்தக்க ஒரு காரணத்தினாலோ அல்லது ஒரு சாதாரணப் பாவமோ அல்ல. மாறாக, உங்கள் நயவஞ்சகத்தினாலும், முஸ்லிம்கள் அனைவரும் முற்றிலும் அழிக்கப்பட்டுவிடுவார்கள், அவர்களின் வாழ்வு முடிந்துவிடும், அவர்களில் எவருமே மீண்டும் உயிருடன் திரும்ப மாட்டார்கள் என்று நீங்கள் தவறாகக் கருதியதாலுமே நீங்கள் பின்தங்கினீர்கள்.”\n\r\n\n\r\nوَظَنَنتُمْ ظَنَّ السَّوْءِ وَكُنتُمْ قَوْماً بُوراً\n\r\n\n\r\n(மேலும் நீங்கள் ஒரு தீய எண்ணத்தை எண்ணினீர்கள்; அதன் காரணமாக நீங்கள் அழிந்துபோகும் சமூகமாகி விட்டீர்கள்.) அப்துல்லாஹ் இப்னு அப்பாஸ் (ரழி), முஜாஹித் மற்றும் பலரின் கூற்றுப்படி, 'பூர்' (Bur) என்பது அழிவை நோக்கிச் செல்பவர்கள் என்று பொருள்படும். கத்தாதா அவர்கள் இதற்கு 'சீரழிந்தவர்கள்' என்று விளக்கமளித்தார். மேலும் சிலர், இது ஓமன் பகுதி அரபு வட்டார வழக்கில் உள்ள ஒரு சொல் என்று கூறினர். கண்ணியமிக்க அல்லாஹ் பிறகு கூறினான்:\n\r\n\n\r\nوَمَن لَّمْ يُؤْمِن بِاللَّهِ وَرَسُولِهِ فَإِنَّآ أَعْتَدْنَا لِلْكَافِرِينَ سَعِيراً\n\r\n\n\r\n(மேலும், எவர் அல்லாஹ்வின் மீதும் அவனது தூதர் மீதும் நம்பிக்கை கொள்ளவில்லையோ, நிச்சயமாக நாம் காஃபிர்களுக்குக் கொழுந்து விட்டெரியும் நரக நெருப்பையே சித்தப்படுத்தி வைத்துள்ளோம்.) எவர் தனது செயல்களைப் புறத்தூய்மையுடனும் அகத்தூய்மையுடனும் அல்லாஹ்விற்காக மட்டும் அர்ப்பணிக்கவில்லையோ, அவருக்குக் கொழுந்துவிட்டெரியும் நரக நெருப்பைக் கொண்டு அல்லாஹ் தண்டனை வழங்குவான் என்று இங்கே குறிப்பிடுகிறான். தான் ஈமானைப் பின்பற்றுவதாக மற்றவர்களுக்குக் காட்டிக்கொண்டாலும், அது அவனது உண்மையான கொள்கைக்கு முரணாக இருந்தால் அவன் தண்டிக்கப்படுவான். பின்னர், வானங்கள் மற்றும் பூமியில் உள்ளவை மீது முழுக் கட்டுப்பாடு கொண்ட ஒரே அதிகாரம், அரசன் மற்றும் உரிமையாளன் அல்லாஹ்வே என்று அவன் கூறுகிறான்:\n\r\n\n\r\nوَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَكَانَ اللَّهُ غَفُوراً رَّحِيماً\n\r\n\n\r\n((வானங்கள் மற்றும் பூமியின் ஆட்சி அல்லாஹ்வுக்கே உரியது.) தான் நாடியவரை அவன் மன்னிக்கிறான், தான் நாடியவரைத் தண்டிக்கிறான். மேலும் அல்லாஹ் மிகவும் மன்னிப்பவனாகவும், மகா கருணையுடையவனாகவும் இருக்கிறான்.) பாவமன்னிப்புக் கோரி அவனிடம் திரும்பி வந்து, தாழ்மையுடன் அவனுக்குப் பணிந்தவர்களிடம் அவன் கருணையுள்ளவனாக இருக்கிறான்."},"15":{"html":"அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">الْمُخَلَّفُونَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">انْطَلَقْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَغَانِمَ</span> <span class=\"quran-arabic-font text-success\">لِتَأْخُذُوهَا</span> <span class=\"quran-arabic-font text-success\">ذَرُونَا</span> <span class=\"quran-arabic-font text-success\">نَتَّبِعْكُمْ﴿</span><br />\r\n(நீங்கள் போர்ச் செல்வங்களை எடுப்பதற்காகச் செல்லும்போது, பின்தங்கியவர்கள் கூறுவார்கள்: \"நாங்களும் உங்களைப் பின்தொடர்ந்து வர எங்களை விடுங்கள்.\")<br />\r\nஹுதைபிய்யா ஆண்டில் பின்தங்கி விட்டவர்களைப் பற்றி அல்லாஹ் தன் தூதருக்கு (ஸல்) அறிவிக்கிறான். கைபர் போருக்கு நீங்கள் செல்லும்போது, அங்கு கனீமத்துகள் கிடைக்கும் என்பது உறுதியானதும், அவர்களும் உங்களுடன் வரக் கேட்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يُرِيدُونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُبَدِّلُواْ</span> <span class=\"quran-arabic-font text-success\">كَلَامَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n(அவர்கள் அல்லாஹ்வின் வார்த்தைகளை மாற்ற விரும்புகிறார்கள்), இது முஜாஹித், கத்தாதா, ஜுவைபிர் ஆகியோரிடமிருந்து அறிவிக்கப்பட்ட விளக்கத்தின்படியும், இப்னு ஜரீர் அவர்கள் தேர்வு செய்த கருத்தின்படியும், ஹுதைபிய்யாவில் இருந்தவர்களுக்கு (ஸஹாபாக்களுக்கு (ரழி)) கைபர் போரின் கனீமத்துகள் அவர்களுக்கு மட்டுமே உரியது என்று அல்லாஹ் அளித்த வாக்குறுதியைக் குறிக்கிறது.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾قُل</span> <span class=\"quran-arabic-font text-success\">لَّن</span> <span class=\"quran-arabic-font text-success\">تَتَّبِعُونَا</span> <span class=\"quran-arabic-font text-success\">كَذَلِكُمْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ﴿</span><br />\r\n(கூறுங்கள்: \"நீங்கள் எங்களைப் பின்தொடர வேண்டாம்; இவ்வாறே அல்லாஹ் இதற்கு முன்பே கூறிவிட்டான்.\") நீங்கள் அவர்களுடன் சேர அனுமதி கேட்பதற்கு முன்பே, ஹுதைபிய்யாவில் கலந்து கொண்டவர்களுக்கு அல்லாஹ் வாக்குறுதி அளித்ததையே இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَسَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">تَحْسُدُونَنَا﴿</span><br />\r\n(பின்னர் அவர்கள் கூறுவார்கள்: \"இல்லை, நீங்கள் எங்கள் மீது பொறாமைப்படுகிறீர்கள்.\") அதாவது, 'போரில் கிடைத்த கனீமத் (போர்ப்பொருட்களை) நாங்கள் உங்களுடன் பகிர்ந்து கொள்வதை நீங்கள் விரும்பவில்லை' என்று அவர்கள் கூறுகிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَفْقَهُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً﴿</span><br />\r\n(இல்லை, மாறாக, அவர்கள் மிகக் குறைவாகவே புரிந்துகொள்கிறார்கள்.) ஏனெனில், உண்மை நிலை அவர்கள் கூறுவது போன்றல்ல. அவர்கள் (உலக விவகாரங்களைத் தவிர) எதனையும் விளங்கிக் கொள்வதில்லை.<br />\r\n<br />","text":"அல்லாஹ் கூறுகிறான்:\n\r\n﴾سَيَقُولُ الْمُخَلَّفُونَ إِذَا انْطَلَقْتُمْ إِلَى مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ﴿\n\r\n(நீங்கள் போர்ச் செல்வங்களை எடுப்பதற்காகச் செல்லும்போது, பின்தங்கியவர்கள் கூறுவார்கள்: \"நாங்களும் உங்களைப் பின்தொடர்ந்து வர எங்களை விடுங்கள்.\")\n\r\nஹுதைபிய்யா ஆண்டில் பின்தங்கி விட்டவர்களைப் பற்றி அல்லாஹ் தன் தூதருக்கு (ஸல்) அறிவிக்கிறான். கைபர் போருக்கு நீங்கள் செல்லும்போது, அங்கு கனீமத்துகள் கிடைக்கும் என்பது உறுதியானதும், அவர்களும் உங்களுடன் வரக் கேட்பார்கள்.\n\r\n\n\r\n﴾يُرِيدُونَ أَن يُبَدِّلُواْ كَلَامَ اللَّهِ﴿\n\r\n(அவர்கள் அல்லாஹ்வின் வார்த்தைகளை மாற்ற விரும்புகிறார்கள்), இது முஜாஹித், கத்தாதா, ஜுவைபிர் ஆகியோரிடமிருந்து அறிவிக்கப்பட்ட விளக்கத்தின்படியும், இப்னு ஜரீர் அவர்கள் தேர்வு செய்த கருத்தின்படியும், ஹுதைபிய்யாவில் இருந்தவர்களுக்கு (ஸஹாபாக்களுக்கு (ரழி)) கைபர் போரின் கனீமத்துகள் அவர்களுக்கு மட்டுமே உரியது என்று அல்லாஹ் அளித்த வாக்குறுதியைக் குறிக்கிறது.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான், ﴾قُل لَّن تَتَّبِعُونَا كَذَلِكُمْ قَالَ اللَّهُ مِن قَبْلُ﴿\n\r\n(கூறுங்கள்: \"நீங்கள் எங்களைப் பின்தொடர வேண்டாம்; இவ்வாறே அல்லாஹ் இதற்கு முன்பே கூறிவிட்டான்.\") நீங்கள் அவர்களுடன் சேர அனுமதி கேட்பதற்கு முன்பே, ஹுதைபிய்யாவில் கலந்து கொண்டவர்களுக்கு அல்லாஹ் வாக்குறுதி அளித்ததையே இது குறிக்கிறது.\n\r\n\n\r\n﴾فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا﴿\n\r\n(பின்னர் அவர்கள் கூறுவார்கள்: \"இல்லை, நீங்கள் எங்கள் மீது பொறாமைப்படுகிறீர்கள்.\") அதாவது, 'போரில் கிடைத்த கனீமத் (போர்ப்பொருட்களை) நாங்கள் உங்களுடன் பகிர்ந்து கொள்வதை நீங்கள் விரும்பவில்லை' என்று அவர்கள் கூறுகிறார்கள்.\n\r\n\n\r\n﴾بَلْ كَانُواْ لاَ يَفْقَهُونَ إِلاَّ قَلِيلاً﴿\n\r\n(இல்லை, மாறாக, அவர்கள் மிகக் குறைவாகவே புரிந்துகொள்கிறார்கள்.) ஏனெனில், உண்மை நிலை அவர்கள் கூறுவது போன்றல்ல. அவர்கள் (உலக விவகாரங்களைத் தவிர) எதனையும் விளங்கிக் கொள்வதில்லை."},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=17\" class=\"link\">48:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:17 ஐ பார்க்கவும்"},"17":{"html":"<strong>ஜிஹாத் நிகழ்வுகள் பல இருக்கும் என்றும், ஜிஹாத் முஃமின்களின் தகுதிகளை வேறுபடுத்தி, நயவஞ்சகர்களை அம்பலப்படுத்தும் என்றும் அல்லாஹ் செய்தியளிக்கிறான்</strong><br />\r\n<br />\r\nஇங்கு குறிப்பிடப்பட்டுள்ள மக்கள் யார் என்பதில் தஃப்ஸீர் அறிஞர்களிடையே கருத்து வேறுபாடுகள் உள்ளன. அவர்கள் போரிடுவதற்காக அழைக்கப்படவிருக்கும் போர்க்கலையில் அனுபவம் வாய்ந்த மக்களாவர். இதில் பல கருத்துகள் உள்ளன: முதலாவதாக, அவர்கள் 'ஹவாஸின்' கோத்திரத்தினர். இதனை அபூ பிஷ்ரிடமிருந்து ஷுஅபா அறிவிக்க, அவர் ஸயீத் பின் ஜுபைர் (ரழி) அல்லது இக்ரிமா (ரழி) அல்லது அவர்கள் இருவரிடமிருந்தும் அறிவிக்கிறார். ஹுஷைம் இந்த விளக்கத்தை அபூ பிஷ்ரிடமிருந்து அறிவிக்க, அவர் ஸயீத் பின் ஜுபைர் (ரழி) மற்றும் இக்ரிமா (ரழி) ஆகிய இருவரிடமிருந்தும் அறிவிக்கிறார். கதாதா (ரழி) அவர்களிடமிருந்து வரும் ஒரு அறிவிப்பிலும் இதே கருத்து கூறப்பட்டுள்ளது. இரண்டாவது கருத்து, அவர்கள் 'தகீஃப்' கோத்திரத்தினர் என்பதாகும்; இது அத்-தஹ்ஹாக் என்பவரின் கூற்று. மூன்றாவது கருத்து, அவர்கள் 'பனூ ஹனீஃபா' என்பதாகும்; முஹம்மது பின் இஸ்ஹாக் அறிவித்தபடி, இது ஜுவைபிர் மற்றும் அஸ்-ஸுஹ்ரி ஆகியோரின் கூற்று. இது போன்றே ஸயீத் பின் ஜுபைர் (ரழி) மற்றும் இக்ரிமா (ரழி) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. நான்காவது கருத்து, அவர்கள் பாரசீகர்கள் என்பதாகும்; அலி பின் அபீ தல்ஹா வழியாக அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) இக்கருத்தைத் தெரிவித்துள்ளார். அதாஃ, முஜாஹித் மற்றும் இக்ரிமா (ரழி) ஆகியோரும் இதையே கூறுகின்றனர். கஅப் அல்-அஹ்பார் (ரழி) அவர்கள் ரோமானியர்கள் என்று கூறினார். அதே சமயம் இப்னு அபீ லைலா, அதாஃ, அல்-ஹஸன் மற்றும் கதாதா (ரழி) - இவரிடமிருந்து வரும் மற்றொரு அறிவிப்பின்படி - அவர்கள் பாரசீகர்கள் மற்றும் ரோமானியர்கள் என்று கூறியுள்ளனர். முஜாஹித் (ரழி) அவர்கள், அவர்கள் 'முஷ்ரிக்குகள்' (இணைவைப்பாளர்கள்) என்றும் கூறினார். மற்றொரு அறிவிப்பில் முஜாஹித் (ரழி), \"அவர்கள் பெரும் போர்களில் ஈடுபடக்கூடிய வலிமை மிக்கவர்கள்\" என்று பொதுவாகக் கூறினார், குறிப்பிட்ட எந்த ஒரு இனத்தையும் அவர் குறிப்பிடவில்லை. இப்னு ஜுரைஜ் மற்றும் இப்னு ஜரீர் (ரஹ்) ஆகியோர் இந்த கடைசி விளக்கத்தையே சிறந்ததாகக் கருதுகின்றனர். அல்லாஹ்வின் கூற்றான,<span class=\"quran-arabic-font text-success\">﴾تُقَاتِلُونَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يُسْلِمُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் அவர்களுடன் போரிடுவீர்கள் அல்லது அவர்கள் அடிபணிவார்கள்) என்பதன் பொருள்: அவர்கள் மீது நீங்கள் வெற்றி கொள்ளும் வரை அல்லது அவர்கள் சரணடையும் வரை தொடர்ந்து ஜிஹாத் செய்ய நீங்கள் அழைக்கப்படுவீர்கள் என்பதாகும். அல்லது, போரின்றி அவர்கள் முழு மனதுடன் உங்கள் மார்க்கத்தை ஏற்றுக்கொள்வார்கள் என்பதைக் குறிக்கிறது. மேன்மையும் மாண்பும் மிக்க அல்லாஹ் அடுத்துக் கூறினான்,<span class=\"quran-arabic-font text-success\">﴾فَإِن</span> <span class=\"quran-arabic-font text-success\">تُطِيعُوا﴿</span><br />\r\n<br />\r\n(நீங்கள் கீழ்ப்படிந்தால்), அதாவது 'ஜிஹாதிற்கான அழைப்பை ஏற்று, அதற்காகத் தயாராகி உங்கள் கடமையை நிறைவேற்றினால்', <span class=\"quran-arabic-font text-success\">﴾يُؤْتِكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span> <span class=\"quran-arabic-font text-success\">حَسَناً</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تَتَوَلَّوْا</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">تَوَلَّيْتُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களுக்கு ஒரு சிறந்த கூலியை வழங்குவான்; ஆனால் இதற்கு முன்னால் நீங்கள் புறக்கணித்தது போல் மீண்டும் புறக்கணித்தால்), அதாவது 'ஜிஹாதிற்கு அழைக்கப்பட்டபோது அல்-ஹுதைபிய்யா நாளில் நீங்கள் பின்தங்கியது போலச் செயல்பட்டால்', <span class=\"quran-arabic-font text-success\">﴾يُعَذِّبْكُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">أَلِيماً﴿</span><br />\r\n<br />\r\n(அவன் உங்களை நோவினை தரும் வேதனையால் தண்டிப்பான்.)<br />\r\n<br />\r\n<strong>ஜிஹாதில் கலந்து கொள்ளாமல் இருக்க அனுமதிக்கப்பட்ட காரணங்கள்</strong><br />\r\n<br />\r\nஜிஹாதில் கலந்து கொள்ளாமல் இருக்க அனுமதிக்கப்படும் சட்டபூர்வமான காரணங்களை அல்லாஹ் பின்னர் குறிப்பிடுகிறான். <span class=\"quran-arabic-font text-success\">﴾لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَى</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَعْرَجِ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمَرِيضِ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ﴿</span> (குருடர் மீதும் குற்றமில்லை; நொண்டியின் மீதும் குற்றமில்லை; நோயாளியின் மீதும் குற்றமில்லை.) கண்பார்வையற்றோர், முடமானவர்கள் மற்றும் சில நாட்களில் குணமாகக்கூடிய நோயால் பாதிக்கப்பட்டவர்கள் இதில் அடங்குவர். ஒருவர் நோயுற்றிருக்கும்போது, அவர் குணமடையும் வரை போருக்குச் செல்லாமல் இருக்க அவருக்கு முறையான அனுமதி உண்டு. ஜிஹாதில் ஈடுபடுமாறும் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் (ஸல்) கீழ்ப்படியுமாறும் கட்டளையிட்டு, மேன்மையும் மாண்பும் மிக்க அல்லாஹ் கூறினான்,<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يُطِعِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولَهُ</span> <span class=\"quran-arabic-font text-success\">يُدْخِلْهُ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِي</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَتَوَلَّ﴿</span><br />\r\n<br />\r\n(எவர் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் (ஸல்) கீழ்ப்படிகிறாரோ, அவரைத் தாழ்வாரங்களில் ஆறுகள் ஓடும் சுவனச்சோலைகளில் அவன் புகுத்துவான்; எவர் புறக்கணிக்கிறாரோ,) அதாவது ஜிஹாதில் பங்கெடுக்காமல் தன் வாழ்வாதாரப் பணிகளில் மட்டும் மூழ்கிப் போகிறாரோ, <span class=\"quran-arabic-font text-success\">﴾يُعَذِّبْهُ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">أَلِيماً﴿</span><br />\r\n<br />\r\n(அவரை அவன் நோவினை தரும் வேதனையால் தண்டிப்பான்.) - இது இவ்வுலகில் இழிவையும் மறுமையில் நரக நெருப்பையும் குறிக்கும். மேன்மைமிக்க அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"ஜிஹாத் நிகழ்வுகள் பல இருக்கும் என்றும், ஜிஹாத் முஃமின்களின் தகுதிகளை வேறுபடுத்தி, நயவஞ்சகர்களை அம்பலப்படுத்தும் என்றும் அல்லாஹ் செய்தியளிக்கிறான்\n\r\n\n\r\nஇங்கு குறிப்பிடப்பட்டுள்ள மக்கள் யார் என்பதில் தஃப்ஸீர் அறிஞர்களிடையே கருத்து வேறுபாடுகள் உள்ளன. அவர்கள் போரிடுவதற்காக அழைக்கப்படவிருக்கும் போர்க்கலையில் அனுபவம் வாய்ந்த மக்களாவர். இதில் பல கருத்துகள் உள்ளன: முதலாவதாக, அவர்கள் 'ஹவாஸின்' கோத்திரத்தினர். இதனை அபூ பிஷ்ரிடமிருந்து ஷுஅபா அறிவிக்க, அவர் ஸயீத் பின் ஜுபைர் (ரழி) அல்லது இக்ரிமா (ரழி) அல்லது அவர்கள் இருவரிடமிருந்தும் அறிவிக்கிறார். ஹுஷைம் இந்த விளக்கத்தை அபூ பிஷ்ரிடமிருந்து அறிவிக்க, அவர் ஸயீத் பின் ஜுபைர் (ரழி) மற்றும் இக்ரிமா (ரழி) ஆகிய இருவரிடமிருந்தும் அறிவிக்கிறார். கதாதா (ரழி) அவர்களிடமிருந்து வரும் ஒரு அறிவிப்பிலும் இதே கருத்து கூறப்பட்டுள்ளது. இரண்டாவது கருத்து, அவர்கள் 'தகீஃப்' கோத்திரத்தினர் என்பதாகும்; இது அத்-தஹ்ஹாக் என்பவரின் கூற்று. மூன்றாவது கருத்து, அவர்கள் 'பனூ ஹனீஃபா' என்பதாகும்; முஹம்மது பின் இஸ்ஹாக் அறிவித்தபடி, இது ஜுவைபிர் மற்றும் அஸ்-ஸுஹ்ரி ஆகியோரின் கூற்று. இது போன்றே ஸயீத் பின் ஜுபைர் (ரழி) மற்றும் இக்ரிமா (ரழி) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. நான்காவது கருத்து, அவர்கள் பாரசீகர்கள் என்பதாகும்; அலி பின் அபீ தல்ஹா வழியாக அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) இக்கருத்தைத் தெரிவித்துள்ளார். அதாஃ, முஜாஹித் மற்றும் இக்ரிமா (ரழி) ஆகியோரும் இதையே கூறுகின்றனர். கஅப் அல்-அஹ்பார் (ரழி) அவர்கள் ரோமானியர்கள் என்று கூறினார். அதே சமயம் இப்னு அபீ லைலா, அதாஃ, அல்-ஹஸன் மற்றும் கதாதா (ரழி) - இவரிடமிருந்து வரும் மற்றொரு அறிவிப்பின்படி - அவர்கள் பாரசீகர்கள் மற்றும் ரோமானியர்கள் என்று கூறியுள்ளனர். முஜாஹித் (ரழி) அவர்கள், அவர்கள் 'முஷ்ரிக்குகள்' (இணைவைப்பாளர்கள்) என்றும் கூறினார். மற்றொரு அறிவிப்பில் முஜாஹித் (ரழி), \"அவர்கள் பெரும் போர்களில் ஈடுபடக்கூடிய வலிமை மிக்கவர்கள்\" என்று பொதுவாகக் கூறினார், குறிப்பிட்ட எந்த ஒரு இனத்தையும் அவர் குறிப்பிடவில்லை. இப்னு ஜுரைஜ் மற்றும் இப்னு ஜரீர் (ரஹ்) ஆகியோர் இந்த கடைசி விளக்கத்தையே சிறந்ததாகக் கருதுகின்றனர். அல்லாஹ்வின் கூற்றான,﴾تُقَاتِلُونَهُمْ أَوْ يُسْلِمُونَ﴿\n\r\n\n\r\n(நீங்கள் அவர்களுடன் போரிடுவீர்கள் அல்லது அவர்கள் அடிபணிவார்கள்) என்பதன் பொருள்: அவர்கள் மீது நீங்கள் வெற்றி கொள்ளும் வரை அல்லது அவர்கள் சரணடையும் வரை தொடர்ந்து ஜிஹாத் செய்ய நீங்கள் அழைக்கப்படுவீர்கள் என்பதாகும். அல்லது, போரின்றி அவர்கள் முழு மனதுடன் உங்கள் மார்க்கத்தை ஏற்றுக்கொள்வார்கள் என்பதைக் குறிக்கிறது. மேன்மையும் மாண்பும் மிக்க அல்லாஹ் அடுத்துக் கூறினான்,﴾فَإِن تُطِيعُوا﴿\n\r\n\n\r\n(நீங்கள் கீழ்ப்படிந்தால்), அதாவது 'ஜிஹாதிற்கான அழைப்பை ஏற்று, அதற்காகத் தயாராகி உங்கள் கடமையை நிறைவேற்றினால்', ﴾يُؤْتِكُمُ اللَّهُ أَجْراً حَسَناً وَإِن تَتَوَلَّوْا كَمَا تَوَلَّيْتُم مِّن قَبْلُ﴿\n\r\n\n\r\n(அல்லாஹ் உங்களுக்கு ஒரு சிறந்த கூலியை வழங்குவான்; ஆனால் இதற்கு முன்னால் நீங்கள் புறக்கணித்தது போல் மீண்டும் புறக்கணித்தால்), அதாவது 'ஜிஹாதிற்கு அழைக்கப்பட்டபோது அல்-ஹுதைபிய்யா நாளில் நீங்கள் பின்தங்கியது போலச் செயல்பட்டால்', ﴾يُعَذِّبْكُمْ عَذَاباً أَلِيماً﴿\n\r\n\n\r\n(அவன் உங்களை நோவினை தரும் வேதனையால் தண்டிப்பான்.)\n\r\n\n\r\nஜிஹாதில் கலந்து கொள்ளாமல் இருக்க அனுமதிக்கப்பட்ட காரணங்கள்\n\r\n\n\r\nஜிஹாதில் கலந்து கொள்ளாமல் இருக்க அனுமதிக்கப்படும் சட்டபூர்வமான காரணங்களை அல்லாஹ் பின்னர் குறிப்பிடுகிறான். ﴾لَّيْسَ عَلَى الْأَعْمَى حَرَجٌ وَلَا عَلَى الْأَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَرِيضِ حَرَجٌ﴿ (குருடர் மீதும் குற்றமில்லை; நொண்டியின் மீதும் குற்றமில்லை; நோயாளியின் மீதும் குற்றமில்லை.) கண்பார்வையற்றோர், முடமானவர்கள் மற்றும் சில நாட்களில் குணமாகக்கூடிய நோயால் பாதிக்கப்பட்டவர்கள் இதில் அடங்குவர். ஒருவர் நோயுற்றிருக்கும்போது, அவர் குணமடையும் வரை போருக்குச் செல்லாமல் இருக்க அவருக்கு முறையான அனுமதி உண்டு. ஜிஹாதில் ஈடுபடுமாறும் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் (ஸல்) கீழ்ப்படியுமாறும் கட்டளையிட்டு, மேன்மையும் மாண்பும் மிக்க அல்லாஹ் கூறினான்,﴾وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ وَمَن يَتَوَلَّ﴿\n\r\n\n\r\n(எவர் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் (ஸல்) கீழ்ப்படிகிறாரோ, அவரைத் தாழ்வாரங்களில் ஆறுகள் ஓடும் சுவனச்சோலைகளில் அவன் புகுத்துவான்; எவர் புறக்கணிக்கிறாரோ,) அதாவது ஜிஹாதில் பங்கெடுக்காமல் தன் வாழ்வாதாரப் பணிகளில் மட்டும் மூழ்கிப் போகிறாரோ, ﴾يُعَذِّبْهُ عَذَاباً أَلِيماً﴿\n\r\n\n\r\n(அவரை அவன் நோவினை தரும் வேதனையால் தண்டிப்பான்.) - இது இவ்வுலகில் இழிவையும் மறுமையில் நரக நெருப்பையும் குறிக்கும். மேன்மைமிக்க அல்லாஹ்வே மிக அறிந்தவன்."},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=19\" class=\"link\">48:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:19 ஐ பார்க்கவும்"},"19":{"html":"<strong>ரித்வான் உடன்படிக்கையில் பங்கேற்றவர்களுக்கு அல்லாஹ்வின் திருப்பொருத்தம் மற்றும் போர்ச் செல்வங்கள் குறித்த நற்செய்தி</strong><br />\r\n<br />\r\nமரத்தினடியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உறுதிப்பிரமாணம் (பைஅத்) செய்துகொண்ட முஃமின்களைக் கண்டு அல்லாஹ் திருப்தி அடைந்துவிட்டதாக அறிவிக்கிறான். இந்த முஃமின்களின் எண்ணிக்கை ஆயிரத்து நானூறு என்றும், அந்த மரம் ஹுதைபிய்யா பகுதியில் இருந்த 'ஸமுரா' வகை மரம் என்றும் நாம் குறிப்பிட்டுள்ளோம். புகாரி அவர்கள் தாரிக் இப்னு அப்துர்-ரஹ்மான் அவர்கள் வழியாக அறிவிப்பதாவது: அவர் கூறினார்கள், \"நான் ஹஜ்ஜுக்குச் சென்றபோது மக்கள் ஓரிடத்தில் தொழுதுகொண்டிருப்பதைக் கண்டு, 'இது என்ன மஸ்ஜித்?' என்று கேட்டேன். அதற்கு அவர்கள், 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அர்-ரித்வான் உடன்படிக்கை செய்துகொண்ட மரம் இருந்த இடம் இதுதான்' என்று கூறினார்கள். உடனே நான் இது குறித்து ஸயீத் இப்னுல் முஸய்யப் (ரழி) அவர்களிடம் கூறினேன். அதற்கு ஸயீத் (ரழி) அவர்கள், 'என் தந்தை அந்த மரத்தினடியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்தவர்களில் ஒருவராக இருந்தார். அவர் என்னிடம்: அடுத்த ஆண்டு நாங்கள் அங்கே சென்றபோது அதன் இடத்தை மறந்துவிட்டோம், அது எந்த மரம் என்பதில் எங்களுக்குள் உடன்பாடு ஏற்படவில்லை என்று கூறினார்' என்றார்கள். மேலும் ஸயீத் (ரழி) அவர்கள், 'முஹம்மது (ஸல்) அவர்களின் ஸஹாபாக்களுக்கே அந்த மரம் எங்கிருந்தது என்று தெரியவில்லை, ஆனால் உங்களுக்கு அது தெரிந்திருக்கிறது. அப்படியென்றால் அவர்களை விட உங்களுக்குத்தான் அதிக அறிவு இருக்கிறது போலும்!' என்று (வியப்புடன்) கூறினார்கள்.\" அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَلِمَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span><br />\r\n(அவர்களின் உள்ளங்களில் இருந்ததை அவன் அறிந்தான்,) அதாவது அவர்களின் உண்மைத்தன்மை, நம்பகத்தன்மை, கீழ்ப்படிதல் மற்றும் உறுதிப்பாடு ஆகியவற்றை அவன் அறிந்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنزَلَ</span> <span class=\"quran-arabic-font text-success\">السَّكِينَةَ</span><br />\r\n(மேலும் அவன் அஸ்-ஸகீனாவை இறக்கினான்,) அதாவது அமைதியையும் நிம்மதியையும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَثَابَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَتْحاً</span> <span class=\"quran-arabic-font text-success\">قَرِيباً</span><br />\r\n(அவர்கள் மீது இறக்கினான்; மேலும் அவர்களுக்கு ஒரு சமீபத்திய வெற்றியைப் பரிசாக அளித்தான்.) இது, ஸஹாபாக்களுக்கும் அவர்களின் நிராகரிக்கும் எதிரிகளுக்கும் இடையில் ஏற்பட்ட சமாதான உடன்படிக்கையின் காரணமாக, கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் ஸஹாபாக்களுக்கு வழங்கிய நன்மைகளைக் குறிக்கிறது. அதன் பிறகு, ஸஹாபாக்கள் ஏராளமான, பரவலான மற்றும் தொடர்ச்சியான நன்மைகளையும் சாதனைகளையும் பெற்றார்கள். இது கைபர் மற்றும் மக்காவின் வெற்றிக்கும், பின்னர் அதனைச் சுற்றியுள்ள பல்வேறு மாகாணங்கள் மற்றும் பகுதிகளின் வெற்றிக்கும் வழிவகுத்தது. மகத்துவமிக்க அல்லாஹ் கூறியது போலவே, அவர்கள் இம்மையிலும் மறுமையிலும் மகத்தான புகழையும், வெற்றிகளையும், உயர்ந்த கண்ணியமான அந்தஸ்தையும் பெற்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَغَانِمَ</span> <span class=\"quran-arabic-font text-success\">كَثِيرَةً</span> <span class=\"quran-arabic-font text-success\">يَأْخُذُونَهَا</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَزِيزاً</span> <span class=\"quran-arabic-font text-success\">حَكِيماً</span><br />\r\n(மேலும் அவர்கள் கைப்பற்றவுள்ள ஏராளமான போர்ச் செல்வங்களையும் (அவன் அளித்தான்). அல்லாஹ் யாவரையும் மிகைத்தவனாகவும், ஞானம் மிக்கவனாகவும் இருக்கிறான்.) அதாவது கைபர் (வெற்றியின் போது கிடைத்த) போர்ச் செல்வங்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"ரித்வான் உடன்படிக்கையில் பங்கேற்றவர்களுக்கு அல்லாஹ்வின் திருப்பொருத்தம் மற்றும் போர்ச் செல்வங்கள் குறித்த நற்செய்தி\n\r\n\n\r\nமரத்தினடியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உறுதிப்பிரமாணம் (பைஅத்) செய்துகொண்ட முஃமின்களைக் கண்டு அல்லாஹ் திருப்தி அடைந்துவிட்டதாக அறிவிக்கிறான். இந்த முஃமின்களின் எண்ணிக்கை ஆயிரத்து நானூறு என்றும், அந்த மரம் ஹுதைபிய்யா பகுதியில் இருந்த 'ஸமுரா' வகை மரம் என்றும் நாம் குறிப்பிட்டுள்ளோம். புகாரி அவர்கள் தாரிக் இப்னு அப்துர்-ரஹ்மான் அவர்கள் வழியாக அறிவிப்பதாவது: அவர் கூறினார்கள், \"நான் ஹஜ்ஜுக்குச் சென்றபோது மக்கள் ஓரிடத்தில் தொழுதுகொண்டிருப்பதைக் கண்டு, 'இது என்ன மஸ்ஜித்?' என்று கேட்டேன். அதற்கு அவர்கள், 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அர்-ரித்வான் உடன்படிக்கை செய்துகொண்ட மரம் இருந்த இடம் இதுதான்' என்று கூறினார்கள். உடனே நான் இது குறித்து ஸயீத் இப்னுல் முஸய்யப் (ரழி) அவர்களிடம் கூறினேன். அதற்கு ஸயீத் (ரழி) அவர்கள், 'என் தந்தை அந்த மரத்தினடியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் உடன்படிக்கை செய்தவர்களில் ஒருவராக இருந்தார். அவர் என்னிடம்: அடுத்த ஆண்டு நாங்கள் அங்கே சென்றபோது அதன் இடத்தை மறந்துவிட்டோம், அது எந்த மரம் என்பதில் எங்களுக்குள் உடன்பாடு ஏற்படவில்லை என்று கூறினார்' என்றார்கள். மேலும் ஸயீத் (ரழி) அவர்கள், 'முஹம்மது (ஸல்) அவர்களின் ஸஹாபாக்களுக்கே அந்த மரம் எங்கிருந்தது என்று தெரியவில்லை, ஆனால் உங்களுக்கு அது தெரிந்திருக்கிறது. அப்படியென்றால் அவர்களை விட உங்களுக்குத்தான் அதிக அறிவு இருக்கிறது போலும்!' என்று (வியப்புடன்) கூறினார்கள்.\" அல்லாஹ் கூறினான்,\n\r\n\n\r\nفَعَلِمَ مَا فِى قُلُوبِهِمْ\n\r\n(அவர்களின் உள்ளங்களில் இருந்ததை அவன் அறிந்தான்,) அதாவது அவர்களின் உண்மைத்தன்மை, நம்பகத்தன்மை, கீழ்ப்படிதல் மற்றும் உறுதிப்பாடு ஆகியவற்றை அவன் அறிந்தான்.\n\r\n\n\r\nفَأَنزَلَ السَّكِينَةَ\n\r\n(மேலும் அவன் அஸ்-ஸகீனாவை இறக்கினான்,) அதாவது அமைதியையும் நிம்மதியையும்,\n\r\n\n\r\nعَلَيْهِمْ وَأَثَابَهُمْ فَتْحاً قَرِيباً\n\r\n(அவர்கள் மீது இறக்கினான்; மேலும் அவர்களுக்கு ஒரு சமீபத்திய வெற்றியைப் பரிசாக அளித்தான்.) இது, ஸஹாபாக்களுக்கும் அவர்களின் நிராகரிக்கும் எதிரிகளுக்கும் இடையில் ஏற்பட்ட சமாதான உடன்படிக்கையின் காரணமாக, கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் ஸஹாபாக்களுக்கு வழங்கிய நன்மைகளைக் குறிக்கிறது. அதன் பிறகு, ஸஹாபாக்கள் ஏராளமான, பரவலான மற்றும் தொடர்ச்சியான நன்மைகளையும் சாதனைகளையும் பெற்றார்கள். இது கைபர் மற்றும் மக்காவின் வெற்றிக்கும், பின்னர் அதனைச் சுற்றியுள்ள பல்வேறு மாகாணங்கள் மற்றும் பகுதிகளின் வெற்றிக்கும் வழிவகுத்தது. மகத்துவமிக்க அல்லாஹ் கூறியது போலவே, அவர்கள் இம்மையிலும் மறுமையிலும் மகத்தான புகழையும், வெற்றிகளையும், உயர்ந்த கண்ணியமான அந்தஸ்தையும் பெற்றார்கள்.\n\r\n\n\r\nوَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا وَكَانَ اللَّهُ عَزِيزاً حَكِيماً\n\r\n(மேலும் அவர்கள் கைப்பற்றவுள்ள ஏராளமான போர்ச் செல்வங்களையும் (அவன் அளித்தான்). அல்லாஹ் யாவரையும் மிகைத்தவனாகவும், ஞானம் மிக்கவனாகவும் இருக்கிறான்.) அதாவது கைபர் (வெற்றியின் போது கிடைத்த) போர்ச் செல்வங்கள்."},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=24\" class=\"link\">48:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:24 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=24\" class=\"link\">48:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:24 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=24\" class=\"link\">48:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=24\" class=\"link\">48:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>ஏராளமான போர்ச் செல்வங்கள் பற்றிய நற்செய்தி</strong><br />\r\n<br />\r\nமுஜாஹித் அவர்கள் கூறினார்கள், அல்லாஹ்வின் இந்த வசனம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَدَكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَغَانِمَ</span> <span class=\"quran-arabic-font text-success\">كَثِيرَةً</span> <span class=\"quran-arabic-font text-success\">تَأْخُذُونَهَا</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களுக்கு ஏராளமான போர்ச் செல்வங்களை வாக்களித்துள்ளான், அவற்றை நீங்கள் கைப்பற்றுவீர்கள்), என்பது இதுவரையில் முஸ்லிம்கள் ஈட்டிய போர்ச் செல்வங்களைக் குறிக்கிறது. மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَجَّلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span><br />\r\n<br />\r\n(இதை அவன் உங்களுக்குத் துரிதப்படுத்தினான்), என்பது கைபர் வெற்றியைக் குறிக்கிறது. அல்-அவ்ஃபி அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَجَّلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span><br />\r\n<br />\r\n(இதை அவன் உங்களுக்குத் துரிதப்படுத்தினான்), என்பது \"ஹுதைபிய்யா உடன்படிக்கையைக்\" குறிக்கும். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَفَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِىَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">عَنْكُمْ</span><br />\r\n<br />\r\n(மேலும் மனிதர்களின் கைகளை உங்களை விட்டும் தடுத்தான்), அதாவது, 'உங்கள் எதிரிகள் உங்களுக்கு எதிராகத் திட்டமிட்டிருந்த போர் மற்றும் சண்டையினால் எந்தத் தீங்கும் உங்களை அணுகவில்லை. அதாவது கைபர் யூதர்கள் மற்றும் அவர்களைச் சார்ந்த பனூ கத்ஃபான் மற்றும் பனூ அஸத் கோத்திரத்தினர் ஆகியோரது கைகளைத் தடுத்தான். மேலும் நீங்கள் உங்கள் குடும்பங்கள் மற்றும் குழந்தைகளை விட்டுவிட்டு வந்த நிலையில், அவர்களுக்குத் தீங்கு விளைவிக்காதவாறு அவர்களின் கைகளையும் அல்லாஹ் தடுத்தான்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِتَكُونَ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span> <span class=\"quran-arabic-font text-success\">لِّلْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(இது விசுவாசிகளுக்கு ஓர் அடையாளமாக இருப்பதற்காக), இதன் மூலம் அவர்கள் படிப்பினை பெற்றுத் தெளிவடைவார்கள். நிச்சயமாக, கண்ணியமும் உயர்வும் மிக்க அல்லாஹ், விசுவாசிகள் எண்ணிக்கையில் குறைவாக இருந்தாலும், அனைத்து எதிரிகளுக்கும் எதிராக அவர்களுக்கு உதவி செய்து பாதுகாப்பான். இதன் மூலம், அனைத்துக் காரியங்களின் முடிவுகளையும் அல்லாஹ் நன்கறிந்தவன் என்பதையும், அவனது விசுவாசியான அடியார்களுக்கு அவன் எதைத் தேர்ந்தெடுக்கிறானோ அதுவே சிறந்த முடிவு என்பதையும் விசுவாசிகள் அறிந்துகொள்வார்கள்; அந்த முடிவுகள் வெளிப்படையாக அவர்களுக்குப் பிடிக்காததாகத் தோன்றினாலும் சரி.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَسَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَكْرَهُواْ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span><br />\r\n<br />\r\n(உங்களுக்கு நன்மையாக இருக்கும் ஒரு விஷயத்தை நீங்கள் வெறுக்கக்கூடும்) (<a href=\"qurandisp.php?sura=2&ayah=216\" class=\"link\">2:216</a>). அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَهْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">صِرَاطاً</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيماً</span><br />\r\n<br />\r\n(மேலும் அவன் உங்களை நேரான வழியில் நடத்துவதற்காக), நீங்கள் அவனது கட்டளைகளுக்குக் கீழ்ப்படிவதாலும், அவனது தூதர் (ஸல்) அவர்களின் வழியைப் பின்பற்றி அவனது உத்தரவுகளைக் கடைப்பிடிப்பதாலும்.<br />\r\n<br />\r\n<strong>மறுமை நாள் வரை தொடரும் முஸ்லிம்களின் வெற்றிகள் பற்றிய நற்செய்தி</strong><br />\r\n<br />\r\nகண்ணியமும் உயர்வும் மிக்க அல்லாஹ்வின் வசனம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأُخْرَى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَقْدِرُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَحَاطَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيراً</span><br />\r\n<br />\r\n(மேலும் இன்னும் சில வெற்றிகள் உண்டு, அவை இன்னும் உங்கள் வசத்தில் வரவில்லை; நிச்சயமாக அல்லாஹ் அவற்றைச் சூழ்ந்துள்ளான். மேலும் அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன்.) அதாவது, தற்போது உங்கள் கைக்கு எட்டாத இன்னும் பல போர்ச் செல்வங்களும் வெற்றிகளும் வரவிருக்கின்றன. இருப்பினும், அல்லாஹ் அவற்றை உங்களுக்குக் கிடைக்கச் செய்வான். நிச்சயமாக உங்கள் நன்மைக்காக இந்த வெற்றிகள் அனைத்தையும் அவன் சூழ்ந்திருக்கிறான். நிச்சயமாக, உயர்ந்தோன் அல்லாஹ், தக்வா (இறையச்சம்) உள்ள தனது அடியார்களுக்கு அவர்கள் கற்பனை செய்ய முடியாத வழிகளில் வாழ்வாதாரங்களை வழங்குகிறான். இங்கு குறிப்பிடப்பட்டுள்ள \"மற்ற போர்ச் செல்வங்கள்\" எவை என்பதில் தஃப்சீர் அறிஞர்கள் மத்தியில் கருத்து வேறுபாடுகள் உள்ளன. இப்னு அப்பாஸ் (ரழி) அவர்கள் இது கைபர் வெற்றியைக் குறிக்கிறது என்று கூறியதாக அல்-அவ்ஃபி அறிவிக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَجَّلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span><br />\r\n<br />\r\n(இதை அவன் உங்களுக்குத் துரிதப்படுத்தினான்) என்ற வசனத்தின் அடிப்படையில் இந்தக் கருத்து பொருத்தமானதே. ஏனெனில் (முந்தைய வசனத்தில் கூறப்பட்ட துரிதப்படுத்தப்பட்டது) என்பது ஹுதைபிய்யா உடன்படிக்கையைக் குறிக்கிறது. மேலும் 'இன்னும் சில வெற்றிகள்' என்பது கைபர் வெற்றியைக் குறிக்கும். இது அத்-தஹ்ஹாக், முஹம்மது பின் இஸ்ஹாக் மற்றும் அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் ஆகியோரின் கருத்தாகும். கத்தாதா அவர்கள், இந்த வசனம் மக்கா வெற்றியைக் குறிக்கிறது என்று கூறினார்கள். இப்னு ஜரீர் அவர்களும் இந்தக் கருத்தையே விரும்பினார்கள். இப்னு அபீ லைலா மற்றும் அல்-ஹஸன் அல்-பஸரி ஆகியோர், இது பாரசீகர்கள் மற்றும் ரோமானியர்களுக்கு எதிரான வெற்றிகளைக் குறிப்பதாகக் கூறினர். அதேசமயம் முஜாஹித் அவர்கள், இது மறுமை நாள் வரை கிடைக்கக்கூடிய ஒவ்வொரு வெற்றியையும், அனைத்துப் போர்ச் செல்வங்களையும் குறிக்கும் என்றார்கள். அபூ தாவூத் அத்-தயாளிஸி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களின் கூற்றைப் பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأُخْرَى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَقْدِرُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَحَاطَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span><br />\r\n<br />\r\n(மேலும் இன்னும் சில வெற்றிகள் உண்டு, அவை இன்னும் உங்கள் வசத்தில் வரவில்லை; நிச்சயமாக அல்லாஹ் அவற்றைச் சூழ்ந்துள்ளான்.) என்பதற்கு, \"அவை இன்று வரை தொடர்ந்து கொண்டிருக்கும் வெற்றிகளாகும்\" என்று விளக்கமளித்தார்கள்.<br />\r\n<br />\r\n<strong>மக்கா நிராகரிப்பாளர்கள் ஹுதைபிய்யாவில் போரிட்டிருந்தால், அவர்கள் தோல்வியடைந்து பின்வாங்கியிருப்பார்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">قَاتَلَكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">لَوَلَّوُا</span> <span class=\"quran-arabic-font text-success\">الْأَدْبَارَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَجِدُونَ</span> <span class=\"quran-arabic-font text-success\">وَلِيّاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نَصِيراً</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் உங்களுடன் போரிட்டிருந்தால், அவர்கள் நிச்சயமாகத் தங்கள் முதுகுகளைத் திருப்பிக் கொண்டு பின்வாங்கியிருப்பார்கள்; பிறகு அவர்கள் எந்தப் பாதுகாவலனையோ அல்லது உதவியாளனையோ கண்டிருக்க மாட்டார்கள்.) கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் தனது விசுவாசியான அடியார்களுக்கு நற்செய்தி கூறுகிறான்: இணைவைப்பாளர்கள் அவர்களுடன் போரிட்டிருந்தால், அல்லாஹ் தனது தூதருக்கும் (ஸல்) விசுவாசிகளுக்கும் வெற்றியளித்திருப்பான். அதன் பிறகு நிராகரிப்பாளர்களின் படை தோற்கடிக்கப்பட்டு, போர்க்களத்தை விட்டு ஓடியிருக்கும். அவர்கள் எவ்வித உதவியாளரையோ ஆதரவாளரையோ கண்டிருக்க மாட்டார்கள்; ஏனெனில் அவர்கள் அல்லாஹ்வுடனும் அவனது தூதருடனும் (ஸல்) அவனது நம்பிக்கைக்குரிய கூட்டத்தாருடனும் போரிட்டார்கள். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُنَّةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">وَلَن</span> <span class=\"quran-arabic-font text-success\">تَجِدَ</span> <span class=\"quran-arabic-font text-success\">لِسُنَّةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تَبْدِيلاً</span><br />\r\n<br />\r\n(இதுவே இதற்கு முன்னரும் கடந்து சென்றவர்களிடம் அல்லாஹ் கையாண்ட நடைமுறையாகும். அல்லாஹ்வின் நடைமுறையில் நீங்கள் எந்த மாற்றத்தையும் காணமாட்டீர்கள்.) அதாவது, இதுவே அல்லாஹ் தனது படைப்புகளிடம் கையாளும் வழியாகும். ஈமானுக்கும் (நம்பிக்கைக்கும்) குஃப்ருக்கும் (நிராகரிப்புக்கும்) இடையில் எந்தவொரு தீர்மானமிக்க சூழல் ஏற்படும்போதும், அல்லாஹ் ஈமானுக்கே வெற்றி அளிக்கிறான்; சத்தியத்தை மேலோங்கச் செய்து அசத்தியத்தை அழிக்கிறான். உதாரணமாக, பத்ருப் போரின் போது அல்லாஹ் தனது விசுவாசிகளுக்கு உதவி புரிந்தான்; முஸ்லிம்கள் எண்ணிக்கையில் குறைவாகவும் ஆயுத பலம் குறைவாகவும் இருந்தபோதிலும், எண்ணிக்கையிலும் ஆயுதங்களிலும் மிஞ்சி நின்ற தனது இணைவைப்பு எதிரிகளை அவர்கள் வீழ்த்தினார்கள். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَفَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُم</span> <span class=\"quran-arabic-font text-success\">بِبَطْنِ</span> <span class=\"quran-arabic-font text-success\">مَكَّةَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَظْفَرَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">بَصِيراً</span><br />\r\n<br />\r\n(மக்காவின் பள்ளத்தாக்கில் அவர்கள் மீது உங்களுக்கு வெற்றியளித்த பிறகு, அவன்தான் அவர்களின் கைகளை உங்களை விட்டும், உங்கள் கைகளை அவர்களை விட்டும் தடுத்தான். மேலும் அல்லாஹ் நீங்கள் செய்பவற்றையெல்லாம் பார்ப்பவனாக இருக்கிறான்.) அல்லாஹ் தனது விசுவாசிகளுக்குச் செய்த அருளை இங்கு நினைவூட்டுகிறான். இணைவைப்பாளர்களிடமிருந்து முஸ்லிம்களுக்கு எந்தத் தீங்கும் நேராதபடி அவன்தான் அவர்களின் கைகளைத் தடுத்தான். மஸ்ஜிதுல் ஹராமுக்கு அருகில் விசுவாசிகள் இணைவைப்பாளர்களுடன் போரிடாதவாறு அவர்களது கைகளையும் அல்லாஹ் தடுத்தான். மாறாக, இரு தரப்பினரையும் போரிலிருந்து காப்பாற்றி ஒரு சமாதான உடன்படிக்கையை ஏற்படுத்தினான்; அது விசுவாசிகளுக்குச் சிறந்த பலன்களைத் தந்ததுடன், இம்மையிலும் மறுமையிலும் அவர்களுக்கு நல்ல முடிவைத் தேடித்தந்தது. ஸலமா பின் அல்-அக்வா (ரழி) அவர்கள் அறிவித்த ஒரு ஹதீஸை நாம் குறிப்பிட்டோம்; அதில் சுமார் எழுபது இணைவைப்புக் கைதிகளை முஸ்லிம்கள் பிடித்து வந்து, அவர்களைக் கட்டி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முன்பாக நிறுத்தினார்கள். அவர்கள் அவர்களைப் பார்த்துவிட்டு:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَرْسِلُوهُمْ</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَدْءُ</span> <span class=\"quran-arabic-font text-success\">الْفُجُورِ</span> <span class=\"quran-arabic-font text-success\">وَثِنَاهُ</span>»<br />\r\n<br />\r\n(அவர்களை விட்டுவிடுங்கள்; போர் அத்துமீறலைத் தொடங்கிய பாவச் சுமையும் அதன் தொடர்ச்சியும் அவர்களையே சாரட்டும்) என்று கூறினார்கள். அதன் பிறகுதான் கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் அந்தச் சம்பவம் தொடர்பாக இந்த வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَفَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُم</span><br />\r\n<br />\r\n(அவனே அவர்களின் கைகளை உங்களை விட்டும், உங்கள் கைகளை அவர்களை விட்டும் தடுத்தான்...) இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள், \"ஹுதைபிய்யா தினத்தன்று, மக்காவிலிருந்து எண்பது ஆயுதமேந்திய மனிதர்கள் ஃபஜ்ர் தொழுகையின் போது தன்ஈம் மலையிலிருந்து இறங்கி வந்து, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைப் பதுங்கியிருந்து தாக்க முயன்றனர். தூதர் (ஸல்) அவர்கள் அவர்களுக்கு எதிராகப் பிரார்த்தனை செய்தார்கள்; அவர்கள் அனைவரும் கைதிகளாகப் பிடிபட்டனர்.\" அஃப்பான் அவர்கள் கூடுதலாகக் கூறும்போது, \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களை மன்னித்து விடுவித்தார்கள். அதன் பிறகுதான் இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَفَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُم</span> <span class=\"quran-arabic-font text-success\">بِبَطْنِ</span> <span class=\"quran-arabic-font text-success\">مَكَّةَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَظْفَرَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span><br />\r\n<br />\r\n(அவனே மக்காவின் பள்ளத்தாக்கில் அவர்கள் மீது உங்களுக்கு வெற்றியளித்த பிறகு, அவன்தான் அவர்களின் கைகளை உங்களை விட்டும், உங்கள் கைகளை அவர்களை விட்டும் தடுத்தான்.)\" இமாம் முஸ்லிம், அபூ தாவூத், திர்மிதி மற்றும் நஸாயீ ஆகியோரும் தங்களது சுனன் நூல்களில் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />","text":"ஏராளமான போர்ச் செல்வங்கள் பற்றிய நற்செய்தி\n\r\n\n\r\nமுஜாஹித் அவர்கள் கூறினார்கள், அல்லாஹ்வின் இந்த வசனம்,\n\r\n\n\r\nوَعَدَكُمُ اللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا\n\r\n\n\r\n(அல்லாஹ் உங்களுக்கு ஏராளமான போர்ச் செல்வங்களை வாக்களித்துள்ளான், அவற்றை நீங்கள் கைப்பற்றுவீர்கள்), என்பது இதுவரையில் முஸ்லிம்கள் ஈட்டிய போர்ச் செல்வங்களைக் குறிக்கிறது. மேலும்,\n\r\n\n\r\nفَعَجَّلَ لَكُمْ هَـذِهِ\n\r\n\n\r\n(இதை அவன் உங்களுக்குத் துரிதப்படுத்தினான்), என்பது கைபர் வெற்றியைக் குறிக்கிறது. அல்-அவ்ஃபி அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nفَعَجَّلَ لَكُمْ هَـذِهِ\n\r\n\n\r\n(இதை அவன் உங்களுக்குத் துரிதப்படுத்தினான்), என்பது \"ஹுதைபிய்யா உடன்படிக்கையைக்\" குறிக்கும். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَكَفَّ أَيْدِىَ النَّاسِ عَنْكُمْ\n\r\n\n\r\n(மேலும் மனிதர்களின் கைகளை உங்களை விட்டும் தடுத்தான்), அதாவது, 'உங்கள் எதிரிகள் உங்களுக்கு எதிராகத் திட்டமிட்டிருந்த போர் மற்றும் சண்டையினால் எந்தத் தீங்கும் உங்களை அணுகவில்லை. அதாவது கைபர் யூதர்கள் மற்றும் அவர்களைச் சார்ந்த பனூ கத்ஃபான் மற்றும் பனூ அஸத் கோத்திரத்தினர் ஆகியோரது கைகளைத் தடுத்தான். மேலும் நீங்கள் உங்கள் குடும்பங்கள் மற்றும் குழந்தைகளை விட்டுவிட்டு வந்த நிலையில், அவர்களுக்குத் தீங்கு விளைவிக்காதவாறு அவர்களின் கைகளையும் அல்லாஹ் தடுத்தான்.'\n\r\n\n\r\nوَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ\n\r\n\n\r\n(இது விசுவாசிகளுக்கு ஓர் அடையாளமாக இருப்பதற்காக), இதன் மூலம் அவர்கள் படிப்பினை பெற்றுத் தெளிவடைவார்கள். நிச்சயமாக, கண்ணியமும் உயர்வும் மிக்க அல்லாஹ், விசுவாசிகள் எண்ணிக்கையில் குறைவாக இருந்தாலும், அனைத்து எதிரிகளுக்கும் எதிராக அவர்களுக்கு உதவி செய்து பாதுகாப்பான். இதன் மூலம், அனைத்துக் காரியங்களின் முடிவுகளையும் அல்லாஹ் நன்கறிந்தவன் என்பதையும், அவனது விசுவாசியான அடியார்களுக்கு அவன் எதைத் தேர்ந்தெடுக்கிறானோ அதுவே சிறந்த முடிவு என்பதையும் விசுவாசிகள் அறிந்துகொள்வார்கள்; அந்த முடிவுகள் வெளிப்படையாக அவர்களுக்குப் பிடிக்காததாகத் தோன்றினாலும் சரி.\n\r\n\n\r\nوَعَسَى أَن تَكْرَهُواْ شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ\n\r\n\n\r\n(உங்களுக்கு நன்மையாக இருக்கும் ஒரு விஷயத்தை நீங்கள் வெறுக்கக்கூடும்) (2:216). அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَيَهْدِيَكُمْ صِرَاطاً مُّسْتَقِيماً\n\r\n\n\r\n(மேலும் அவன் உங்களை நேரான வழியில் நடத்துவதற்காக), நீங்கள் அவனது கட்டளைகளுக்குக் கீழ்ப்படிவதாலும், அவனது தூதர் (ஸல்) அவர்களின் வழியைப் பின்பற்றி அவனது உத்தரவுகளைக் கடைப்பிடிப்பதாலும்.\n\r\n\n\r\nமறுமை நாள் வரை தொடரும் முஸ்லிம்களின் வெற்றிகள் பற்றிய நற்செய்தி\n\r\n\n\r\nகண்ணியமும் உயர்வும் மிக்க அல்லாஹ்வின் வசனம்,\n\r\n\n\r\nوَأُخْرَى لَمْ تَقْدِرُواْ عَلَيْهَا قَدْ أَحَاطَ اللَّهُ بِهَا وَكَانَ اللَّهُ عَلَى كُلِّ شَىْءٍ قَدِيراً\n\r\n\n\r\n(மேலும் இன்னும் சில வெற்றிகள் உண்டு, அவை இன்னும் உங்கள் வசத்தில் வரவில்லை; நிச்சயமாக அல்லாஹ் அவற்றைச் சூழ்ந்துள்ளான். மேலும் அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன்.) அதாவது, தற்போது உங்கள் கைக்கு எட்டாத இன்னும் பல போர்ச் செல்வங்களும் வெற்றிகளும் வரவிருக்கின்றன. இருப்பினும், அல்லாஹ் அவற்றை உங்களுக்குக் கிடைக்கச் செய்வான். நிச்சயமாக உங்கள் நன்மைக்காக இந்த வெற்றிகள் அனைத்தையும் அவன் சூழ்ந்திருக்கிறான். நிச்சயமாக, உயர்ந்தோன் அல்லாஹ், தக்வா (இறையச்சம்) உள்ள தனது அடியார்களுக்கு அவர்கள் கற்பனை செய்ய முடியாத வழிகளில் வாழ்வாதாரங்களை வழங்குகிறான். இங்கு குறிப்பிடப்பட்டுள்ள \"மற்ற போர்ச் செல்வங்கள்\" எவை என்பதில் தஃப்சீர் அறிஞர்கள் மத்தியில் கருத்து வேறுபாடுகள் உள்ளன. இப்னு அப்பாஸ் (ரழி) அவர்கள் இது கைபர் வெற்றியைக் குறிக்கிறது என்று கூறியதாக அல்-அவ்ஃபி அறிவிக்கிறார்கள்.\n\r\n\n\r\nفَعَجَّلَ لَكُمْ هَـذِهِ\n\r\n\n\r\n(இதை அவன் உங்களுக்குத் துரிதப்படுத்தினான்) என்ற வசனத்தின் அடிப்படையில் இந்தக் கருத்து பொருத்தமானதே. ஏனெனில் (முந்தைய வசனத்தில் கூறப்பட்ட துரிதப்படுத்தப்பட்டது) என்பது ஹுதைபிய்யா உடன்படிக்கையைக் குறிக்கிறது. மேலும் 'இன்னும் சில வெற்றிகள்' என்பது கைபர் வெற்றியைக் குறிக்கும். இது அத்-தஹ்ஹாக், முஹம்மது பின் இஸ்ஹாக் மற்றும் அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் ஆகியோரின் கருத்தாகும். கத்தாதா அவர்கள், இந்த வசனம் மக்கா வெற்றியைக் குறிக்கிறது என்று கூறினார்கள். இப்னு ஜரீர் அவர்களும் இந்தக் கருத்தையே விரும்பினார்கள். இப்னு அபீ லைலா மற்றும் அல்-ஹஸன் அல்-பஸரி ஆகியோர், இது பாரசீகர்கள் மற்றும் ரோமானியர்களுக்கு எதிரான வெற்றிகளைக் குறிப்பதாகக் கூறினர். அதேசமயம் முஜாஹித் அவர்கள், இது மறுமை நாள் வரை கிடைக்கக்கூடிய ஒவ்வொரு வெற்றியையும், அனைத்துப் போர்ச் செல்வங்களையும் குறிக்கும் என்றார்கள். அபூ தாவூத் அத்-தயாளிஸி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களின் கூற்றைப் பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\nوَأُخْرَى لَمْ تَقْدِرُواْ عَلَيْهَا قَدْ أَحَاطَ اللَّهُ بِهَا\n\r\n\n\r\n(மேலும் இன்னும் சில வெற்றிகள் உண்டு, அவை இன்னும் உங்கள் வசத்தில் வரவில்லை; நிச்சயமாக அல்லாஹ் அவற்றைச் சூழ்ந்துள்ளான்.) என்பதற்கு, \"அவை இன்று வரை தொடர்ந்து கொண்டிருக்கும் வெற்றிகளாகும்\" என்று விளக்கமளித்தார்கள்.\n\r\n\n\r\nமக்கா நிராகரிப்பாளர்கள் ஹுதைபிய்யாவில் போரிட்டிருந்தால், அவர்கள் தோல்வியடைந்து பின்வாங்கியிருப்பார்கள்\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nوَلَوْ قَاتَلَكُمُ الَّذِينَ كَفَرُوا لَوَلَّوُا الْأَدْبَارَ ثُمَّ لاَ يَجِدُونَ وَلِيّاً وَلاَ نَصِيراً\n\r\n\n\r\n(நிராகரிப்பாளர்கள் உங்களுடன் போரிட்டிருந்தால், அவர்கள் நிச்சயமாகத் தங்கள் முதுகுகளைத் திருப்பிக் கொண்டு பின்வாங்கியிருப்பார்கள்; பிறகு அவர்கள் எந்தப் பாதுகாவலனையோ அல்லது உதவியாளனையோ கண்டிருக்க மாட்டார்கள்.) கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் தனது விசுவாசியான அடியார்களுக்கு நற்செய்தி கூறுகிறான்: இணைவைப்பாளர்கள் அவர்களுடன் போரிட்டிருந்தால், அல்லாஹ் தனது தூதருக்கும் (ஸல்) விசுவாசிகளுக்கும் வெற்றியளித்திருப்பான். அதன் பிறகு நிராகரிப்பாளர்களின் படை தோற்கடிக்கப்பட்டு, போர்க்களத்தை விட்டு ஓடியிருக்கும். அவர்கள் எவ்வித உதவியாளரையோ ஆதரவாளரையோ கண்டிருக்க மாட்டார்கள்; ஏனெனில் அவர்கள் அல்லாஹ்வுடனும் அவனது தூதருடனும் (ஸல்) அவனது நம்பிக்கைக்குரிய கூட்டத்தாருடனும் போரிட்டார்கள். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nسُنَّةَ اللَّهِ الَّتِى قَدْ خَلَتْ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلاً\n\r\n\n\r\n(இதுவே இதற்கு முன்னரும் கடந்து சென்றவர்களிடம் அல்லாஹ் கையாண்ட நடைமுறையாகும். அல்லாஹ்வின் நடைமுறையில் நீங்கள் எந்த மாற்றத்தையும் காணமாட்டீர்கள்.) அதாவது, இதுவே அல்லாஹ் தனது படைப்புகளிடம் கையாளும் வழியாகும். ஈமானுக்கும் (நம்பிக்கைக்கும்) குஃப்ருக்கும் (நிராகரிப்புக்கும்) இடையில் எந்தவொரு தீர்மானமிக்க சூழல் ஏற்படும்போதும், அல்லாஹ் ஈமானுக்கே வெற்றி அளிக்கிறான்; சத்தியத்தை மேலோங்கச் செய்து அசத்தியத்தை அழிக்கிறான். உதாரணமாக, பத்ருப் போரின் போது அல்லாஹ் தனது விசுவாசிகளுக்கு உதவி புரிந்தான்; முஸ்லிம்கள் எண்ணிக்கையில் குறைவாகவும் ஆயுத பலம் குறைவாகவும் இருந்தபோதிலும், எண்ணிக்கையிலும் ஆயுதங்களிலும் மிஞ்சி நின்ற தனது இணைவைப்பு எதிரிகளை அவர்கள் வீழ்த்தினார்கள். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَهُوَ الَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِن بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيراً\n\r\n\n\r\n(மக்காவின் பள்ளத்தாக்கில் அவர்கள் மீது உங்களுக்கு வெற்றியளித்த பிறகு, அவன்தான் அவர்களின் கைகளை உங்களை விட்டும், உங்கள் கைகளை அவர்களை விட்டும் தடுத்தான். மேலும் அல்லாஹ் நீங்கள் செய்பவற்றையெல்லாம் பார்ப்பவனாக இருக்கிறான்.) அல்லாஹ் தனது விசுவாசிகளுக்குச் செய்த அருளை இங்கு நினைவூட்டுகிறான். இணைவைப்பாளர்களிடமிருந்து முஸ்லிம்களுக்கு எந்தத் தீங்கும் நேராதபடி அவன்தான் அவர்களின் கைகளைத் தடுத்தான். மஸ்ஜிதுல் ஹராமுக்கு அருகில் விசுவாசிகள் இணைவைப்பாளர்களுடன் போரிடாதவாறு அவர்களது கைகளையும் அல்லாஹ் தடுத்தான். மாறாக, இரு தரப்பினரையும் போரிலிருந்து காப்பாற்றி ஒரு சமாதான உடன்படிக்கையை ஏற்படுத்தினான்; அது விசுவாசிகளுக்குச் சிறந்த பலன்களைத் தந்ததுடன், இம்மையிலும் மறுமையிலும் அவர்களுக்கு நல்ல முடிவைத் தேடித்தந்தது. ஸலமா பின் அல்-அக்வா (ரழி) அவர்கள் அறிவித்த ஒரு ஹதீஸை நாம் குறிப்பிட்டோம்; அதில் சுமார் எழுபது இணைவைப்புக் கைதிகளை முஸ்லிம்கள் பிடித்து வந்து, அவர்களைக் கட்டி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முன்பாக நிறுத்தினார்கள். அவர்கள் அவர்களைப் பார்த்துவிட்டு:\n\r\n\n\r\n«أَرْسِلُوهُمْ يَكُنْ لَهُمْ بَدْءُ الْفُجُورِ وَثِنَاهُ»\n\r\n\n\r\n(அவர்களை விட்டுவிடுங்கள்; போர் அத்துமீறலைத் தொடங்கிய பாவச் சுமையும் அதன் தொடர்ச்சியும் அவர்களையே சாரட்டும்) என்று கூறினார்கள். அதன் பிறகுதான் கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் அந்தச் சம்பவம் தொடர்பாக இந்த வசனத்தை இறக்கினான்:\n\r\n\n\r\nوَهُوَ الَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم\n\r\n\n\r\n(அவனே அவர்களின் கைகளை உங்களை விட்டும், உங்கள் கைகளை அவர்களை விட்டும் தடுத்தான்...) இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள், \"ஹுதைபிய்யா தினத்தன்று, மக்காவிலிருந்து எண்பது ஆயுதமேந்திய மனிதர்கள் ஃபஜ்ர் தொழுகையின் போது தன்ஈம் மலையிலிருந்து இறங்கி வந்து, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைப் பதுங்கியிருந்து தாக்க முயன்றனர். தூதர் (ஸல்) அவர்கள் அவர்களுக்கு எதிராகப் பிரார்த்தனை செய்தார்கள்; அவர்கள் அனைவரும் கைதிகளாகப் பிடிபட்டனர்.\" அஃப்பான் அவர்கள் கூடுதலாகக் கூறும்போது, \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களை மன்னித்து விடுவித்தார்கள். அதன் பிறகுதான் இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\nوَهُوَ الَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِن بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ\n\r\n\n\r\n(அவனே மக்காவின் பள்ளத்தாக்கில் அவர்கள் மீது உங்களுக்கு வெற்றியளித்த பிறகு, அவன்தான் அவர்களின் கைகளை உங்களை விட்டும், உங்கள் கைகளை அவர்களை விட்டும் தடுத்தான்.)\" இமாம் முஸ்லிம், அபூ தாவூத், திர்மிதி மற்றும் நஸாயீ ஆகியோரும் தங்களது சுனன் நூல்களில் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்."},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=26\" class=\"link\">48:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:26 ஐ பார்க்கவும்"},"26":{"html":"<strong>ஹுதைபிய்யா உடன்படிக்கையிலிருந்து பெறப்பட்ட சில நன்மைகள்</strong><br />\r\n<br />\r\nஉயர்ந்தோனான அல்லாஹ் கூறுகிறான், குறைஷிகளைச் சேர்ந்த அரபு இணைவைப்பாளர்களும், அவனுடைய தூதருக்கு எதிராக அவர்களுக்கு உதவி செய்த அவர்களது கூட்டாளிகளும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span><br />\r\n<br />\r\n(நிராகரித்தவர்கள் அவர்களே), அவர்கள் நிச்சயமாக நிராகரிப்பாளர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصَدُّوكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدِ</span> <span class=\"quran-arabic-font text-success\">الْحَرَامِ</span><br />\r\n<br />\r\n(மேலும் மஸ்ஜிதுல் ஹராமிற்குச் செல்லவிடாமல் உங்களைத் தடுத்தார்கள்) 'நீங்கள் அதன் உரிமையாளர்களாகவும், அதற்குப் பொறுப்பேற்க தகுதியுடையவர்களாகவும் இருந்தபோதிலும்,'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْهَدْىَ</span> <span class=\"quran-arabic-font text-success\">مَعْكُوفاً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَبْلُغَ</span> <span class=\"quran-arabic-font text-success\">مَحِلَّهُ</span><br />\r\n<br />\r\n(மேலும், பலிப் பிராணிகளை அவை அறுக்கப்படும் இடத்தை அடையவிடாமல் தடுத்து நிறுத்தினார்கள்.) அத்துமீறல் மற்றும் பிடிவாதத்தின் காரணமாக, பலிப் பிராணிகள் அறுக்கப்படும் இடத்திற்குச் செல்வதை அவர்கள் தடுத்தார்கள். பலியிடுவதற்காகக் கொண்டு வரப்பட்ட எழுபது ஒட்டகங்கள் அங்கே இருந்தன; இது குறித்து இன்ஷா அல்லாஹ் (அல்லாஹ் நாடினால்) பின்னர் விளக்குவோம். உயர்ந்தவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">رِجَالٌ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">وَنِسَآءٌ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنَـتٌ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்ட ஆண்களும் பெண்களும் இல்லாதிருந்திருந்தால்) 'அதாவது மக்காவாசிகளிடையே தங்கள் ஈமானை (நம்பிக்கையை) மறைத்து வாழ்ந்து வந்தவர்கள். இணைவைப்பாளர்களிடமிருந்து தங்கள் உயிருக்கு ஆபத்து ஏற்படும் என அஞ்சி அவர்கள் மறைந்து வாழ்ந்தார்கள். இல்லையெனில், நாம் மக்காவாசிகள் மீது உங்களுக்கு ஆதிக்கத்தை வழங்கியிருப்போம்; நீங்கள் அவர்களை முழுமையாக அழித்திருப்பீர்கள். எனினும், அவர்களிடையே முஃமின்களான (நம்பிக்கையாளர்களான) சில ஆண்களும் பெண்களும் வாழ்ந்து கொண்டிருந்தார்கள். அவர்கள் முஃமின்கள் என்பது உங்களுக்குத் தெரிந்திருக்கவில்லை; ஒருவேளை நீங்கள் அவர்களை அறியாமல் கொல்ல நேரிட்டிருக்கலாம்.' அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُوهُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَطَئُوهُمْ</span> <span class=\"quran-arabic-font text-success\">فَتُصِيبَكمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّعَرَّةٌ</span><br />\r\n<br />\r\n(நீங்கள் அறியாத நிலையில், அவர்களை நீங்கள் மிதித்து (கொன்று), அதனால் உங்கள் மீது பாவம் ஏற்பட்டிருக்கும்) அதாவது ஒரு தீய மற்றும் தவறான செயல்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span> <span class=\"quran-arabic-font text-success\">لِّيُدْخِلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">رَحْمَتِهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span><br />\r\n<br />\r\n((உங்கள்) அறிவில்லாமல், அல்லாஹ் தான் நாடியவர்களைத் தன் அருளில் நுழைவிப்பதற்காக) மக்காவின் இணைவைப்பாளர்களுக்கான தண்டனையை அல்லாஹ் தாமதப்படுத்தினான். அவர்களிடையே வாழ்ந்த முஃமின்களைக் காப்பாற்றுவதற்காகவும், அந்த இணைவைப்பாளர்களில் பலர் இஸ்லாத்தை ஏற்றுக் கொள்வதற்காகவும் இவ்வாறு செய்தான். உயர்ந்தவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">تَزَيَّلُواْ</span><br />\r\n<br />\r\n(அவர்கள் பிரிந்திருந்தால்), அதாவது நிராகரிப்பாளர்களும் அவர்களிடையே வாழ்ந்த முஃமின்களும் தனித்தனியாகப் பிரிந்திருந்தால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَذَّبْنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">أَلِيماً</span><br />\r\n<br />\r\n(அவர்களில் நிராகரித்தவர்களை நிச்சயமாக நாம் நோவினை செய்யும் வேதனையால் தண்டித்திருப்போம்) 'நாம் நிராகரிப்பாளர்கள் மீது உங்களுக்கு வெற்றியை அளித்திருப்போம்; நீங்கள் அவர்களைக் கடுமையாகத் தாக்கியிருப்பீர்கள்.' உயர்ந்தவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمُ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيَّةَ</span> <span class=\"quran-arabic-font text-success\">حَمِيَّةَ</span> <span class=\"quran-arabic-font text-success\">الْجَـهِلِيَّةِ</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் தங்கள் இதயங்களில் அறியாமைக் காலத்துப் பெருமையையும் ஆணவத்தையும் கொண்டிருந்தபோது,) உடன்படிக்கை ஆவணத்தில் 'அளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்' என்றும், 'அல்லாஹ்வின் தூதர் முஹம்மது (ஸல்) அவர்களால் ஒப்புக்கொள்ளப்பட்ட நிபந்தனைகள் இவை' என்றும் எழுத அவர்கள் மறுத்தபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنزَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَكِينَتَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَأَلْزَمَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةَ</span> <span class=\"quran-arabic-font text-success\">التَّقْوَى</span><br />\r\n<br />\r\n(அப்போது அல்லாஹ் தன் தூதர் மீதும், முஃமின்கள் மீதும் தனது அமைதியையும் நிம்மதியையும் இறக்கினான். மேலும் அவர்களைத் 'தக்வா'வின் (இறை அச்சத்தின்) வாசகத்திலேயே நிலைத்திருக்கச் செய்தான்;) முஜாஹித் அவர்களின் கூற்றுப்படி, தக்வாவின் வாசகம் என்பது 'தூய்மையான உள்ளத்தைக்' குறிக்கிறது. அதா பின் அபீ ரபாஹ் அவர்கள் கூறுகையில், \"அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவர் வேறு யாருமில்லை, அவன் தனித்தவன், அவனுக்கு இணை யாரும் இல்லை. ஆட்சியதிகாரம் அவனுக்கே உரியது, புகழனைத்தும் அவனுக்கே. அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் கொண்டவன்\" என்பதாகும். யூனுஸ் பின் புகைர் அவர்கள் அஸ்-ஸுஹ்ரியிடமிருந்தும், அவர் உர்வாவிலிருந்தும், அவர் அல்-மிஸ்வரிடமிருந்தும் அறிவித்ததாக இப்னு இஸ்ஹாக் கூறுகிறார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَلْزَمَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةَ</span> <span class=\"quran-arabic-font text-success\">التَّقْوَى</span><br />\r\n<br />\r\n(அவர்களைத் தக்வாவின் வாசகத்தில் நிலைத்திருக்கச் செய்தான்;) அதன் பொருள் \"லா இலாஹ இல்லல்லாஹ் (அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை), அவன் தனித்தவன், அவனுக்கு இணை இல்லை\" என்பதாகும். மேலும் உயர்ந்தோனான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">أَحَقَّ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَأَهْلَهَا</span><br />\r\n<br />\r\n(அவர்கள் அதற்குத் தகுதியுடையவர்களாகவும், அதற்குரியவர்களாகவும் இருந்தார்கள்) அதாவது, இணைவைப்பாளர்களை விட முஃமின்களே அந்தச் சொல்லைக் கூறுவதற்கு மிகவும் தகுதியானவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيماً</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் அனைத்துப் பொருட்களையும் நன்கறிந்தவனாக இருக்கிறான்) அதாவது, நன்மைக்குத் தகுதியானவர் யார், தீமைக்குத் தகுதியானவர் யார் என்பதை அவன் நன்கறிவான்.<br />\r\n<br />\r\n<strong>ஹுதைபிய்யா நிகழ்வு மற்றும் சமாதான உடன்படிக்கை குறித்த ஹதீஸ்கள்</strong><br />\r\n<br />\r\nஅல்-புகாரி (ரஹ்) அவர்கள் தனது 'ஸஹீஹ்' நூலில், 'நிபந்தனைகள்' (கிதாபுஷ் ஷுரூத்) எனும் அத்தியாயத்தில் பதிவு செய்துள்ளார்கள்: அல்-மிஸ்வர் பின் மக்ரமா (ரழி) மற்றும் மர்வான் பின் அல்-ஹகம் (ரழி) ஆகிய இருவரும் ஒருவருக்கொருவர் சான்றளித்து அறிவித்ததாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஹுதைபிய்யா காலத்தில் தங்களின் தோழர்கள் பல நூறு பேருடன் புறப்பட்டார்கள். அவர்கள் துல்-ஹுலைஃபாவை அடைந்தபோது, பலிப் பிராணிகளுக்கு மாலை அணிவித்து, அடையாளமிட்டு, உம்ராவிற்காக இஹ்ராம் அணிந்தார்கள். பின்னர் பனூ குஸாஆ கோத்திரத்தைச் சேர்ந்த சிலரை உளவு பார்க்க அனுப்பிவிட்டுப் பயணத்தைத் தொடர்ந்தார்கள். அவர்கள் அல்-அஷ்தாத் எனும் கிராமத்தை அடைந்தபோது, உளவாளிகள் திரும்பி வந்து, 'குறைஷிகள் உங்களுக்கு எதிராக அஹாபிஷ் பழங்குடியினர் உள்ளிட்ட பெரும் படைகளைத் திரட்டியுள்ளனர். அவர்கள் உங்களைத் தடுத்துப் போரிடத் தீர்மானித்துள்ளனர்' என்று கூறினார்கள். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَشِيرُوا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ،</span> <span class=\"quran-arabic-font text-success\">أَتُرَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">نَمِيلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عِيَالِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَذَرَارِيِّ</span> <span class=\"quran-arabic-font text-success\">هؤُلَاءِ،</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُونَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَصُدُّونَا</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْبَيْتِ؟</span>»<br />\r\n<br />\r\n(மக்களே! எனக்கு ஆலோசனை கூறுங்கள்! இறை இல்லத்திற்குச் செல்ல விடாமல் நம்மைத் தடுக்கும் இவர்களுடைய குடும்பத்தினர் மற்றும் பிள்ளைகள் மீது நாம் தாக்குதல் நடத்தலாமா?)\" மற்றொரு அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«(<span class=\"quran-arabic-font text-success\">أَ</span>)<span class=\"quran-arabic-font text-success\">تُرَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">نَمِيلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ذَرَارِيِّ</span> <span class=\"quran-arabic-font text-success\">هؤُلَاءِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَعَانُوهُمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">يَأْتُونَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">قَطَعَ</span> <span class=\"quran-arabic-font text-success\">عُنُقًا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُشْرِكِينَ،</span> <span class=\"quran-arabic-font text-success\">وَإِلَّا</span> <span class=\"quran-arabic-font text-success\">تَرَكْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">مَحْزُونِين</span>»<br />\r\n<br />\r\n(குறைஷிகளுக்கு உதவியவர்களின் குடும்பங்களைத் தாக்கலாம் என நினைக்கிறீர்களா? அவர்கள் நம்மை எதிர்க்க வந்தால், அல்லாஹ் இணைவைப்பாளர்களின் பலத்தைக் குறைத்திருப்பான். இல்லையெனில், அவர்களைத் துக்கத்தில் விட்டுவிடுவோம்!)\" மற்றுமொரு அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">قَعَدُوا</span> <span class=\"quran-arabic-font text-success\">قَعَدُوا</span> <span class=\"quran-arabic-font text-success\">مَوْتُورِينَ</span> <span class=\"quran-arabic-font text-success\">مَجْهُودِينَ</span> <span class=\"quran-arabic-font text-success\">مَحْزُونِينَ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">نَجَوْا</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">عُنُقًا</span> <span class=\"quran-arabic-font text-success\">قَطَعَهَا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span>. <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">تُرَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">نَؤُمَّ</span> <span class=\"quran-arabic-font text-success\">الْبَيْتَ</span> <span class=\"quran-arabic-font text-success\">فَمَنْ</span> <span class=\"quran-arabic-font text-success\">صَدَّنَا</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">قَاتَلْنَاه</span>»<br />\r\n<br />\r\n(அவர்கள் அமைதியாக இருந்தால் துக்கத்திலும் சோர்விலும் இருப்பார்கள். ஒருவேளை தப்பித்தாலும், அவர்களின் வலிமையை அல்லாஹ் முறித்திருப்பான். அல்லது நாம் நேராக இறை இல்லத்தை நோக்கிச் செல்வோமா? யாராவது நம்மைத் தடுத்தால் அவர்களுடன் போரிடுவோமா?) அப்போது அபூபக்கர் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதரே! நீங்கள் இறை இல்லத்தை ஜியாரத் செய்யவே வந்தீர்கள்; யாரையும் கொல்லவோ போர் புரியவோ வரவில்லை. எனவே, இறை இல்லத்தை நோக்கிப் புறப்படுங்கள். நம்மை யாராவது தடுத்தால் அவர்களுடன் போரிடுவோம்.\" மற்றொரு அறிவிப்பில் அபூபக்கர் (ரழி) அவர்கள், \"நாங்கள் உம்ரா செய்ய மட்டுமே வந்தோம், போரிட வரவில்லை என்பதை அல்லாஹ்வும் அவனது தூதரும் அறிவார்கள். இருப்பினும் யாராவது எங்களைத் தடுத்தால் அவருடன் போரிடுவோம்\" என்று கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَرُوحُوا</span> <span class=\"quran-arabic-font text-success\">إِذَن</span>»<br />\r\n<br />\r\n(அப்படியானால் புறப்படுங்கள்.) மற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَامْضُوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اسْمِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>»<br />\r\n<br />\r\n(உயர்ந்தோனான அல்லாஹ்வின் பெயரால் புறப்படுங்கள்.) என்று கூறினார்கள். அவர்கள் சிறிது தூரம் சென்றபோது நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">خَالِدَ</span> <span class=\"quran-arabic-font text-success\">بْنَ</span> <span class=\"quran-arabic-font text-success\">الْوَلِيدِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">خَيْلٍ</span> <span class=\"quran-arabic-font text-success\">لِقُرَيْشٍ</span> <span class=\"quran-arabic-font text-success\">طَلِيعَةً،</span> <span class=\"quran-arabic-font text-success\">فَخُذُوا</span> <span class=\"quran-arabic-font text-success\">ذَاتَ</span> <span class=\"quran-arabic-font text-success\">الْيَمِين</span>»<br />\r\n<br />\r\n(குறைஷிகளின் குதிரைப்படைக்குத் தலைமை தாங்கி காலித் பின் அல்-வலீத் முன்னணியில் வந்து கொண்டிருக்கிறார்; எனவே நீங்கள் வலதுபுறப் பாதையில் செல்லுங்கள்.) அல்லாஹ்வின் மீது ஆணையாக, முஸ்லிம் படைகளின் அணிவகுப்பினால் எழுந்த புழுதிப் படலத்தைப் பார்க்கும் வரை காலித் அதை உணரவில்லை. உடனே அவர் குறைஷிகளுக்கு எச்சரிக்கை செய்யத் திரும்பினார். நபி (ஸல்) அவர்கள் முன்னேறிச் சென்று ஒரு மலைப்பாதையை (தநிய்யா) அடைந்தார்கள். அப்போது நபி (ஸல்) அவர்களின் 'அல்-கஸ்வா' எனும் ஒட்டகம் திடீரென அமர்ந்துவிட்டது. மக்கள் அதை எழுப்ப முயன்றும் அது அசையவில்லை. \"அல்-கஸ்வா அடம்பிடிக்கிறது!\" என்று மக்கள் கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">خَلَأَتِ</span> <span class=\"quran-arabic-font text-success\">الْقَصْوَاءُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">ذَاكَ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">بِخُلُقٍ،</span> <span class=\"quran-arabic-font text-success\">وَلكِنْ</span> <span class=\"quran-arabic-font text-success\">حَبَسَها</span> <span class=\"quran-arabic-font text-success\">حَابِسُ</span> <span class=\"quran-arabic-font text-success\">الْفِيل</span>»<br />\r\n<br />\r\n(அல்-கஸ்வா அடம்பிடிக்கவில்லை, அது அதன் குணமும் இல்லை. முன்பு யானையைத் தடுத்தவனே (அல்லாஹ்) இன்று இதையும் தடுத்துள்ளான்.) பின்னர் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَسْأَلُونِّي</span> <span class=\"quran-arabic-font text-success\">خُطَّةً</span> <span class=\"quran-arabic-font text-success\">يُعَظِّمُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">حُرُمَاتِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَعْطَيْتُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهَا</span>»<br />\r\n<br />\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக, அல்லாஹ்வின் புனிதங்களை மதிக்கும் விதமாக அவர்கள் எந்த நிபந்தனையை முன்வைத்தாலும் அதை நான் ஏற்றுக்கொள்வேன்.) பின்னர் நபி (ஸல்) அவர்கள் அதைக் அதட்டியதும் அது எழுந்தது. அவர்கள் திசையை மாற்றி ஹுதைபிய்யாவின் எல்லைப் பகுதிக்குச் சென்றார்கள். அங்கு மிகக் குறைந்த அளவு தண்ணீருடைய ஒரு குழி இருந்தது. மக்கள் அதைச் சிறிது நேரத்தில் தீர்த்துவிட்டனர். தாகத்தால் அவர்கள் கஷ்டப்பட்டபோது நபி (ஸல்) அவர்கள் தங்களின் அம்பறாத்தூணியிலிருந்து ஒரு அம்பை எடுத்துக் கொடுத்தார்கள். அதை அந்தக் குழியில் நட்டதும், அல்லாஹ்வின் மீது ஆணையாக, தண்ணீர் பொங்கி வழிந்தது. அனைவரும் தாகம் தணிந்து திரும்பும் வரை தண்ணீர் சுரந்து கொண்டே இருந்தது.<br />\r\n<br />\r\nஅவர்கள் அங்கு தங்கியிருந்தபோது பனூ குஸாஆ கோத்திரத்தைச் சேர்ந்த புதைல் பின் வர்கா சிலருடன் வந்தார். அவர்கள் திஹாமா பகுதியைச் சேர்ந்த நபி (ஸல்) அவர்களின் நம்பிக்கைக்குரிய ஆலோசகர்களாக இருந்தனர். புதைல் கூறினான்: 'கஅப் பின் லுஅய் மற்றும் ஆமிர் பின் லுஅய் கோத்திரத்தினர் ஹுதைபிய்யாவின் நீர்நிலைகளில் முகாமிட்டுள்ளனர். அவர்கள் போரிடத் தயாராகப் பால் ஒட்டகங்களுடன் வந்துள்ளனர்; உங்களைக் கஃபாவிற்குள் நுழைய விடமாட்டார்கள்.' அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">نَجِىءْ</span> <span class=\"quran-arabic-font text-success\">لِقِتَالِ</span> <span class=\"quran-arabic-font text-success\">أَحَدٍ،</span> <span class=\"quran-arabic-font text-success\">وَلكِنْ</span> <span class=\"quran-arabic-font text-success\">جِئْنَا</span> <span class=\"quran-arabic-font text-success\">مُعْتَمِرِينَ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">قُرَيْشًا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">نَهَكَتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَرْبُ،</span> <span class=\"quran-arabic-font text-success\">وَأَضَرَّتْ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">شَاؤُوا</span> <span class=\"quran-arabic-font text-success\">مَادَدْتُهُمْ</span> <span class=\"quran-arabic-font text-success\">مُدَّةً</span> <span class=\"quran-arabic-font text-success\">وَيُخَلُّوا</span> <span class=\"quran-arabic-font text-success\">بَيْنِي</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَظْهَرْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">شَاءُوا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَدْخُلُوا</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">فَعَلُوا،</span> <span class=\"quran-arabic-font text-success\">وَإِلَّا</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَمُّوا،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَبَوْا</span> <span class=\"quran-arabic-font text-success\">فَوَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَأُقَاتِلَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَمْرِي</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">تَنْفَرِدَ</span> <span class=\"quran-arabic-font text-success\">سَالِفَتِي</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">لَيُنْفِذَنَّ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">أَمْرَه</span>»<br />\r\n<br />\r\n(நாங்கள் யாருடனும் போரிட வரவில்லை, உம்ரா செய்யவே வந்துள்ளோம். தொடர் போர்களால் குறைஷிகள் பலவீனமடைந்துள்ளனர். அவர்கள் விரும்பினால் நான் அவர்களுடன் ஒரு குறிப்பிட்ட காலத்திற்குச் சமாதான உடன்படிக்கை செய்துகொள்கிறேன். அந்த இடைப்பட்ட காலத்தில் அவர்கள் எனக்கும் மக்களுக்கும் இடையே குறுக்கிடக் கூடாது. நான் மற்றவர்களிடம் வெற்றி பெற்றால், மக்கள் இஸ்லாத்தில் நுழைவது போல குறைஷிகளும் விரும்பினால் நுழையலாம். அல்லது அவர்கள் ஓய்வெடுக்கட்டும். ஆனால் அவர்கள் உடன்படிக்கையை மறுத்தால், என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக, நான் கொல்லப்படும் வரை என் கொள்கைக்காகப் போரிடுவேன். அல்லாஹ் நிச்சயம் தன் மார்க்கத்தை வெற்றி பெறச் செய்வான்.) புதைல் அவர்கள் இச்செய்தியைப் போய்ச் சொன்னார். குறைஷிகளில் இருந்த விவரமற்றவர்கள் அதை அலட்சியப்படுத்தினாலும், அறிவுடையவர்கள் நபி (ஸல்) அவர்கள் சொன்னதைக் கேட்க விரும்பினார்கள்.<br />\r\n<br />\r\nபின்னர் உர்வா பின் மஸ்ஊத் எழுந்து மக்களிடம் உரையாடினார். அவர், 'முஹம்மது ஒரு நியாயமான கோரிக்கையை வைத்துள்ளார், அதை ஏற்றுக்கொண்டு என்னை அவரிடம் பேச்சுவார்த்தைக்கு அனுப்புங்கள்' என்றார். அவ்வாறே அவர் நபி (ஸல்) அவர்களிடம் சென்று பேசினார். நபி (ஸல்) அவர்கள் புதைலிடம் சொன்னதையே அவரிடமும் கூறினார்கள். அப்போது உர்வா, 'முஹம்மதே! உங்கள் சொந்த உறவுகளையே நீங்கள் அழிக்கப் போகிறீர்களா? இதற்கு முன் எந்த அரபியாவது தன் இனத்தையே அழித்ததாகக் கேள்விப்பட்டதுண்டா? ஒருவேளை நீங்கள் தோற்றால், உங்கள் பின்னால் இருக்கும் இந்தக் கலவையான கூட்டம் உங்களைத் தனியாக விட்டுவிட்டு ஓடிவிடுவார்கள்' என்று கூறினார். இதைக் கேட்டு ஆத்திரமடைந்த அபூபக்கர் (ரழி) அவர்கள், அவரிடம், \"அல்-லாத் (சிலையின்) மர்ம உறுப்பைச் சப்புவாயாக!\" எனக் கூறி, \"நாங்கள் அவரை விட்டுவிட்டு ஓடுவோமா?\" என்று கேட்டார்கள். உர்வா \"யார் இது?\" என்று கேட்டதற்கு, அவர் \"அபூபக்கர்\" என்று மக்கள் கூறினர். உர்வா கூறினார், \"என் மீது நீங்கள் செய்த ஒரு உபகாரத்திற்கு நான் ஈடு செய்ய வேண்டியுள்ளது, இல்லையென்றால் உங்களுக்குப் பதிலடி கொடுத்திருப்பேன்.\"<br />\r\n<br />\r\nஉர்வா பேசிக்கொண்டிருக்கும்போது நபி (ஸல்) அவர்களின் தாடியைத் தொட்டுப் பேச முயன்றார். அப்போது நபி (ஸல்) அவர்களின் தலைக்கு அருகில் கவசம் அணிந்து வாளுடன் நின்று கொண்டிருந்த அல்-முகீரா பின் ஷுஃபா (ரழி), உர்வாவின் கையை வாளின் கைப்பிடியால் தட்டி, \"அல்லாஹ்வின் தூதரின் (ஸல்) தாடியிலிருந்து கையை எடு\" என்றார். அவர் தனது மருமகனான அல்-முகீரா (ரழி) என்பதை அறிந்ததும், அவரது பழைய துரோகச் செயலைக் குறிப்பிட்டார் (இஸ்லாத்திற்கு முன் அவர் சிலரைக் கொன்றுவிட்டு மக்காவிலிருந்து தப்பி ஓடியிருந்தார்). அதற்கு நபி (ஸல்) அவர்கள், \"உன் இஸ்லாத்தை நான் ஏற்றுக் கொள்கிறேன், ஆனால் உன் முறையற்ற சொத்தை நான் தொடமாட்டேன்\" என்று கூறினார்கள். உர்வா அந்தச் சபையைக் கவனித்தார். நபி (ஸல்) அவர்கள் உமிழ்ந்தால் கூட அதைத் தங்கள் கைகளில் ஏந்தி முகத்தில் பூசிக் கொள்ளும் தோழர்களின் அன்பைக் கண்டார். அவர்கள் உளுச் செய்தால் மீதமுள்ள தண்ணீருக்காகப் போட்டியிடுவதையும், அவர்கள் பேசும்போது அமைதியாக இருப்பதையும் கண்டு வியந்தார். உர்வா திரும்பிச் சென்று குறைஷிகளிடம் கூறினார்: \"மக்களே! நான் சீசர், கிஸ்ரா மற்றும் நஜாஷி போன்ற மன்னர்களிடம் தூது சென்றிருக்கிறேன். ஆனால் முஹம்மது (ஸல்) அவர்களின் தோழர்கள் அவருக்குக் கொடுக்கும் மரியாதையை நான் எங்கும் கண்டதில்லை. அவர் ஒரு நல்ல வழியை முன்வைத்துள்ளார், அதை ஏற்றுக்கொள்ளுங்கள்.\"<br />\r\n<br />\r\nபின்னர் பனூ கினானாவைச் சேர்ந்த ஒரு மனிதர் வர, அவர் பலி ஒட்டகங்களை மதிப்பவர் என்பதால் நபி (ஸல்) அவர்கள் ஒட்டகங்களை அவர் முன் காட்டச் செய்தார்கள். அதைப் பார்த்த அவர், \"சுப்ஹானல்லாஹ்! இவர்களைத் தடுப்பது முறையல்ல\" என்றார். பிறகு மிக்ரஸ் பின் ஹஃப்ஸ் வந்தபோது நபி (ஸல்) அவர்கள், \"அவன் ஒரு தீய மனிதன்\" என்று கூறினார்கள். அவர் பேசிக் கொண்டிருக்கும்போதே சுஹைல் பின் அம்ர் வந்தார். அப்போது நபி (ஸல்) அவர்கள், \"இப்போது உங்கள் காரியம் எளிதாகிவிட்டது (ஸஹுல)\" என்று கூறினார்கள். சுஹைல் உடன்படிக்கை செய்ய முன்வந்தார். நபி (ஸல்) அவர்கள் அலி (ரழி) அவர்களை அழைத்து, \"பிஸ்மில்லாஹிர் ரஹ்மானிர் ரஹீம் (அளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்) என்று எழுது\" என்றார்கள். சுஹைல், \"அர்-ரஹ்மான் என்றால் என்னவென்று எங்களுக்குத் தெரியாது; வழக்கப்படி 'பிஸ்மிக்கல்லாஹும்ம' (அல்லாஹ்வே உன் பெயரால்) என்றே எழுது\" என்றார். தோழர்கள் மறுத்தாலும் நபி (ஸல்) அவர்கள் அப்படியே எழுதச் சொன்னார்கள்.<br />\r\n<br />\r\nபின்னர் \"அல்லாஹ்வின் தூதர் முஹம்மது செய்துகொண்ட உடன்படிக்கை\" என்று சொல்ல, சுஹைல், \"நீங்கள் அல்லாஹ்வின் தூதர் என்று நாங்கள் நம்பியிருந்தால் உங்களைத் தடுத்திருக்க மாட்டோமே! எனவே 'முஹம்மது பின் அப்துல்லாஹ்' என்று எழுதுங்கள்\" என்றான். நபி (ஸல்) அவர்கள், \"அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் என்னை மறுத்தாலும் நான் அல்லாஹ்வின் தூதர்தான்; 'முஹம்மது பின் அப்துல்லாஹ்' என்றே எழுது\" என்று அலி (ரழி) அவர்களிடம் கூறினார்கள். அலி (ரழி) அவர்கள் அந்தப் பெயரை அழிக்கத் தயங்கியபோது, நபி (ஸல்) அவர்களே அந்த இடத்தை அழித்தார்கள். அடுத்த ஆண்டு வரலாம் என்பது உள்ளிட்ட நிபந்தனைகள் எழுதப்பட்டன. அப்போது, ஒரு நிபந்தனையாக 'மக்காவிலிருந்து யாராவது முஸ்லிமாக மதினாவிற்கு வந்தால் அவரைத் திருப்பி அனுப்ப வேண்டும்' என்பது சேர்க்கப்பட்டது.<br />\r\n<br />\r\nபேச்சுவார்த்தை நடந்து கொண்டிருக்கும்போதே, சங்கிலிகளால் பிணைக்கப்பட்டிருந்த அபூ ஜந்தல் பின் சுஹைல் (ரழி) தப்பித்து வந்து முஸ்லிம்களிடம் விழுந்தார். சுஹைல், \"இந்த ஒப்பந்தத்தின்படி இவரைத் தான் நான் முதலில் திரும்பக் கேட்கிறேன்\" என்றார். நபி (ஸல்) அவர்கள் எவ்வளவோ கேட்டும் சுஹைல் விடாப்பிடியாக மறுத்துவிட்டார். அபூ ஜந்தல் (ரழி), \"முஸ்லிம்களே! நான் முஸ்லிமாக வந்த பிறகும் மீண்டும் இணைவைப்பாளர்களிடம் ஒப்படைக்கப்படுகிறேனா?\" என்று கதறினார். அவர் அல்லாஹ்வின் பாதையில் மிகக் கடுமையாகச் சித்திரவதை செய்யப்பட்டிருந்தார்.<br />\r\n<br />\r\nஉமர் (ரழி) அவர்கள் மிகுந்த கவலையுடன் நபி (ஸல்) அவர்களிடம் சென்று, \"நீங்கள் அல்லாஹ்வின் தூதர் இல்லையா? நம் மார்க்கம் சத்தியமானது இல்லையா?\" என்று கேட்டார். நபி (ஸல்) அவர்கள் \"ஆம்\" என்றார்கள். \"பிறகு நாம் ஏன் இப்படிப் பணிந்து போக வேண்டும்?\" என்று கேட்டதற்கு, நபி (ஸல்) அவர்கள், \"நான் அல்லாஹ்வின் தூதர்; அவனுக்கு நான் மாறு செய்ய மாட்டேன். அவன் எனக்கு உதவி செய்வான்\" என்றார்கள். பின்னர் உமர் (ரழி) அவர்கள் அபூபக்கர் (ரழி) அவர்களிடம் சென்று அதே கேள்விகளைக் கேட்க, அவரும் அதே பதிலையே அளித்தார். \"அவர் அல்லாஹ்வின் தூதர், அவரைப் பற்றிக் கொள்; அவர் சத்தியத்தில் இருக்கிறார்\" என்று அபூபக்கர் (ரழி) கூறினார். உமர் (ரழி) அவர்கள் பின்னாளில் கூறுகையில், \"அன்று நான் கேட்ட அந்தக் கேள்விகளுக்காகப் பரிகாரமாகப் பல நற்செயல்களைச் செய்தேன்\" என்றார்.<br />\r\n<br />\r\nஉடன்படிக்கை முடிந்ததும் நபி (ஸல்) அவர்கள், \"எழுந்து உங்கள் பலிகளை நிறைவேற்றி, தலைமுடியை மழித்துக் கொள்ளுங்கள்\" என்று மூன்று முறை கூறினார்கள். எவரும் எழாததைக் கண்டு கவலையுடன் உம்மு ஸலமா (ரழி) அவர்களிடம் சென்று முறையிட்டார்கள். அவர், \"நீங்கள் யாரிடமும் பேசாமல் வெளியே சென்று உங்கள் பலியை அறுத்து முடியை மழித்துக் கொள்ளுங்கள்; அதைப் பார்த்தால் அவர்களும் செய்வார்கள்\" என்று அறிவுரை கூறினார். அவ்வாறே நபி (ஸல்) அவர்கள் செய்ய, தோழர்கள் அனைவரும் கவலையுடன் ஒருவருக்கொருவர் தலைமுடியை மழித்துக் கொண்டனர். பின்னர் சூரா அல்-மும்தஹினாவின் வசனங்கள் அருளப்பட்டன.<br />\r\n<br />\r\nநபி (ஸல்) அவர்கள் மதினாவிற்குத் திரும்பியபோது, அபூ பஸீர் (ரழி) எனும் முஸ்லிம் மக்காவிலிருந்து தப்பி வந்தார். குறைஷிகள் அவரைத் திரும்பக் கேட்டு இருவரை அனுப்பினார்கள். நபி (ஸல்) அவர்கள் உடன்படிக்கையின்படி அவரைத் திருப்பி அனுப்பினார். வழியில் துல்-ஹுலைஃபாவில் தங்கியிருந்தபோது, அபூ பஸீர் தந்திரமாக ஒருவனின் வாளை வாங்கி அவனைக் கொன்றுவிட்டார். மற்றவன் தப்பி ஓடி மதினாவிற்கு வந்து நபி (ஸல்) அவர்களிடம் முறையிட்டான். அபூ பஸீர் அங்கு வந்து, \"அல்லாஹ்வின் தூதரே! உங்கள் உடன்படிக்கையை நீங்கள் நிறைவேற்றிவிட்டீர்கள்; அல்லாஹ் என்னைக் காப்பாற்றிவிட்டான்\" என்றார். நபி (ஸல்) அவர்கள், \"அவனுடைய தாய்க்குத் துக்கமே! அவனுக்கு உதவியாளர்கள் இருந்தால் அவன் ஒரு பெரும் போரை மூட்டுபவனாக இருப்பான்\" என்று கூறினார்கள்.<br />\r\n<br />\r\nஅபூ பஸீர் (ரழி) அங்கிருந்து தப்பித்துக் கடற்கரையோரப் பகுதிக்குச் சென்றார். அங்கு அபூ ஜந்தல் (ரழி) அவர்களும் வந்து இணைந்தார். இப்படியாக மக்காவிலிருந்து தப்பி வரும் முஸ்லிம்கள் அங்கு ஒரு குழுவாகச் சேர்ந்தனர். அவர்கள் குறைஷிகளின் வியாபாரக் கூட்டங்களைத் தாக்கத் தொடங்கினர். ஒருகட்டத்தில் பொறுக்க முடியாத குறைஷிகள், அந்த முஸ்லிம்களை மதினாவிற்கே அழைத்துக் கொள்ளுமாறு நபி (ஸல்) அவர்களுக்குச் செய்தி அனுப்பினார்கள். அப்போதுதான் சூரா அல்-ஃபத்ஹின் 24-வது வசனம் மற்றும் 26-வது வசனங்கள் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டன.<br />\r\n<br />\r\nஇமாம் அஹ்மத் மற்றும் அல்-புகாரி ஆகியோர் பதிவு செய்துள்ள மற்றுமொரு அறிவிப்பில், அலி (ரழி) அவர்கள் \"அல்லாஹ்வின் தூதர்\" என்ற பட்டத்தை அழிக்கத் தயங்கியபோது, நபி (ஸல்) அவர்களே அதைத் துடைத்தார்கள். பட்டத்தை அழிப்பதனால் நபித்துவம் மறைந்துவிடாது என்று அவர்களுக்குப் புரிய வைத்தார்கள். மேலும் ஹுதைபிய்யா நாளில் நபி (ஸல்) அவர்கள் எழுபது ஒட்டகங்களைப் பலியிட்டார்கள்; அதில் அபூ ஜஹ்லுக்குச் சொந்தமான வெள்ளி மூக்கு வளையமிடப்பட்ட ஒரு ஒட்டகமும் இருந்தது. அந்த ஒட்டகம் கஅபாவை நோக்கித் தடுக்கப்பட்டபோது, தன் குட்டியைப் பிரிந்த தாய் அழுவது போல அழுதது என்று இப்னு அப்பாஸ் (ரழி) அறிவிக்கிறார்கள்.<br />\r\n<br />","text":"ஹுதைபிய்யா உடன்படிக்கையிலிருந்து பெறப்பட்ட சில நன்மைகள்\n\r\n\n\r\nஉயர்ந்தோனான அல்லாஹ் கூறுகிறான், குறைஷிகளைச் சேர்ந்த அரபு இணைவைப்பாளர்களும், அவனுடைய தூதருக்கு எதிராக அவர்களுக்கு உதவி செய்த அவர்களது கூட்டாளிகளும்,\n\r\n\n\r\nهُمُ الَّذِينَ كَفَرُواْ\n\r\n\n\r\n(நிராகரித்தவர்கள் அவர்களே), அவர்கள் நிச்சயமாக நிராகரிப்பாளர்கள்,\n\r\n\n\r\nوَصَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ\n\r\n\n\r\n(மேலும் மஸ்ஜிதுல் ஹராமிற்குச் செல்லவிடாமல் உங்களைத் தடுத்தார்கள்) 'நீங்கள் அதன் உரிமையாளர்களாகவும், அதற்குப் பொறுப்பேற்க தகுதியுடையவர்களாகவும் இருந்தபோதிலும்,'\n\r\n\n\r\nوَالْهَدْىَ مَعْكُوفاً أَن يَبْلُغَ مَحِلَّهُ\n\r\n\n\r\n(மேலும், பலிப் பிராணிகளை அவை அறுக்கப்படும் இடத்தை அடையவிடாமல் தடுத்து நிறுத்தினார்கள்.) அத்துமீறல் மற்றும் பிடிவாதத்தின் காரணமாக, பலிப் பிராணிகள் அறுக்கப்படும் இடத்திற்குச் செல்வதை அவர்கள் தடுத்தார்கள். பலியிடுவதற்காகக் கொண்டு வரப்பட்ட எழுபது ஒட்டகங்கள் அங்கே இருந்தன; இது குறித்து இன்ஷா அல்லாஹ் (அல்லாஹ் நாடினால்) பின்னர் விளக்குவோம். உயர்ந்தவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلَوْلاَ رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَـتٌ\n\r\n\n\r\n(நம்பிக்கை கொண்ட ஆண்களும் பெண்களும் இல்லாதிருந்திருந்தால்) 'அதாவது மக்காவாசிகளிடையே தங்கள் ஈமானை (நம்பிக்கையை) மறைத்து வாழ்ந்து வந்தவர்கள். இணைவைப்பாளர்களிடமிருந்து தங்கள் உயிருக்கு ஆபத்து ஏற்படும் என அஞ்சி அவர்கள் மறைந்து வாழ்ந்தார்கள். இல்லையெனில், நாம் மக்காவாசிகள் மீது உங்களுக்கு ஆதிக்கத்தை வழங்கியிருப்போம்; நீங்கள் அவர்களை முழுமையாக அழித்திருப்பீர்கள். எனினும், அவர்களிடையே முஃமின்களான (நம்பிக்கையாளர்களான) சில ஆண்களும் பெண்களும் வாழ்ந்து கொண்டிருந்தார்கள். அவர்கள் முஃமின்கள் என்பது உங்களுக்குத் தெரிந்திருக்கவில்லை; ஒருவேளை நீங்கள் அவர்களை அறியாமல் கொல்ல நேரிட்டிருக்கலாம்.' அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nلَّمْ تَعْلَمُوهُمْ أَن تَطَئُوهُمْ فَتُصِيبَكمْ مِّنْهُمْ مَّعَرَّةٌ\n\r\n\n\r\n(நீங்கள் அறியாத நிலையில், அவர்களை நீங்கள் மிதித்து (கொன்று), அதனால் உங்கள் மீது பாவம் ஏற்பட்டிருக்கும்) அதாவது ஒரு தீய மற்றும் தவறான செயல்,\n\r\n\n\r\nبِغَيْرِ عِلْمٍ لِّيُدْخِلَ اللَّهُ فِى رَحْمَتِهِ مَن يَشَآءُ\n\r\n\n\r\n((உங்கள்) அறிவில்லாமல், அல்லாஹ் தான் நாடியவர்களைத் தன் அருளில் நுழைவிப்பதற்காக) மக்காவின் இணைவைப்பாளர்களுக்கான தண்டனையை அல்லாஹ் தாமதப்படுத்தினான். அவர்களிடையே வாழ்ந்த முஃமின்களைக் காப்பாற்றுவதற்காகவும், அந்த இணைவைப்பாளர்களில் பலர் இஸ்லாத்தை ஏற்றுக் கொள்வதற்காகவும் இவ்வாறு செய்தான். உயர்ந்தவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான்:\n\r\n\n\r\nلَوْ تَزَيَّلُواْ\n\r\n\n\r\n(அவர்கள் பிரிந்திருந்தால்), அதாவது நிராகரிப்பாளர்களும் அவர்களிடையே வாழ்ந்த முஃமின்களும் தனித்தனியாகப் பிரிந்திருந்தால்,\n\r\n\n\r\nلَعَذَّبْنَا الَّذِينَ كَفَرُواْ مِنْهُمْ عَذَاباً أَلِيماً\n\r\n\n\r\n(அவர்களில் நிராகரித்தவர்களை நிச்சயமாக நாம் நோவினை செய்யும் வேதனையால் தண்டித்திருப்போம்) 'நாம் நிராகரிப்பாளர்கள் மீது உங்களுக்கு வெற்றியை அளித்திருப்போம்; நீங்கள் அவர்களைக் கடுமையாகத் தாக்கியிருப்பீர்கள்.' உயர்ந்தவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِذْ جَعَلَ الَّذِينَ كَفَرُواْ فِى قُلُوبِهِمُ الْحَمِيَّةَ حَمِيَّةَ الْجَـهِلِيَّةِ\n\r\n\n\r\n(நிராகரிப்பாளர்கள் தங்கள் இதயங்களில் அறியாமைக் காலத்துப் பெருமையையும் ஆணவத்தையும் கொண்டிருந்தபோது,) உடன்படிக்கை ஆவணத்தில் 'அளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்' என்றும், 'அல்லாஹ்வின் தூதர் முஹம்மது (ஸல்) அவர்களால் ஒப்புக்கொள்ளப்பட்ட நிபந்தனைகள் இவை' என்றும் எழுத அவர்கள் மறுத்தபோது,\n\r\n\n\r\nفَأَنزَلَ اللَّهُ سَكِينَتَهُ عَلَى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ التَّقْوَى\n\r\n\n\r\n(அப்போது அல்லாஹ் தன் தூதர் மீதும், முஃமின்கள் மீதும் தனது அமைதியையும் நிம்மதியையும் இறக்கினான். மேலும் அவர்களைத் 'தக்வா'வின் (இறை அச்சத்தின்) வாசகத்திலேயே நிலைத்திருக்கச் செய்தான்;) முஜாஹித் அவர்களின் கூற்றுப்படி, தக்வாவின் வாசகம் என்பது 'தூய்மையான உள்ளத்தைக்' குறிக்கிறது. அதா பின் அபீ ரபாஹ் அவர்கள் கூறுகையில், \"அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவர் வேறு யாருமில்லை, அவன் தனித்தவன், அவனுக்கு இணை யாரும் இல்லை. ஆட்சியதிகாரம் அவனுக்கே உரியது, புகழனைத்தும் அவனுக்கே. அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் கொண்டவன்\" என்பதாகும். யூனுஸ் பின் புகைர் அவர்கள் அஸ்-ஸுஹ்ரியிடமிருந்தும், அவர் உர்வாவிலிருந்தும், அவர் அல்-மிஸ்வரிடமிருந்தும் அறிவித்ததாக இப்னு இஸ்ஹாக் கூறுகிறார்:\n\r\n\n\r\nوَأَلْزَمَهُمْ كَلِمَةَ التَّقْوَى\n\r\n\n\r\n(அவர்களைத் தக்வாவின் வாசகத்தில் நிலைத்திருக்கச் செய்தான்;) அதன் பொருள் \"லா இலாஹ இல்லல்லாஹ் (அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை), அவன் தனித்தவன், அவனுக்கு இணை இல்லை\" என்பதாகும். மேலும் உயர்ந்தோனான அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَكَانُواْ أَحَقَّ بِهَا وَأَهْلَهَا\n\r\n\n\r\n(அவர்கள் அதற்குத் தகுதியுடையவர்களாகவும், அதற்குரியவர்களாகவும் இருந்தார்கள்) அதாவது, இணைவைப்பாளர்களை விட முஃமின்களே அந்தச் சொல்லைக் கூறுவதற்கு மிகவும் தகுதியானவர்கள்.\n\r\n\n\r\nوَكَانَ اللَّهُ بِكُلِّ شَىْءٍ عَلِيماً\n\r\n\n\r\n(மேலும் அல்லாஹ் அனைத்துப் பொருட்களையும் நன்கறிந்தவனாக இருக்கிறான்) அதாவது, நன்மைக்குத் தகுதியானவர் யார், தீமைக்குத் தகுதியானவர் யார் என்பதை அவன் நன்கறிவான்.\n\r\n\n\r\nஹுதைபிய்யா நிகழ்வு மற்றும் சமாதான உடன்படிக்கை குறித்த ஹதீஸ்கள்\n\r\n\n\r\nஅல்-புகாரி (ரஹ்) அவர்கள் தனது 'ஸஹீஹ்' நூலில், 'நிபந்தனைகள்' (கிதாபுஷ் ஷுரூத்) எனும் அத்தியாயத்தில் பதிவு செய்துள்ளார்கள்: அல்-மிஸ்வர் பின் மக்ரமா (ரழி) மற்றும் மர்வான் பின் அல்-ஹகம் (ரழி) ஆகிய இருவரும் ஒருவருக்கொருவர் சான்றளித்து அறிவித்ததாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஹுதைபிய்யா காலத்தில் தங்களின் தோழர்கள் பல நூறு பேருடன் புறப்பட்டார்கள். அவர்கள் துல்-ஹுலைஃபாவை அடைந்தபோது, பலிப் பிராணிகளுக்கு மாலை அணிவித்து, அடையாளமிட்டு, உம்ராவிற்காக இஹ்ராம் அணிந்தார்கள். பின்னர் பனூ குஸாஆ கோத்திரத்தைச் சேர்ந்த சிலரை உளவு பார்க்க அனுப்பிவிட்டுப் பயணத்தைத் தொடர்ந்தார்கள். அவர்கள் அல்-அஷ்தாத் எனும் கிராமத்தை அடைந்தபோது, உளவாளிகள் திரும்பி வந்து, 'குறைஷிகள் உங்களுக்கு எதிராக அஹாபிஷ் பழங்குடியினர் உள்ளிட்ட பெரும் படைகளைத் திரட்டியுள்ளனர். அவர்கள் உங்களைத் தடுத்துப் போரிடத் தீர்மானித்துள்ளனர்' என்று கூறினார்கள். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَشِيرُوا أَيُّهَا النَّاسُ عَلَيَّ، أَتُرَوْنَ أَنْ نَمِيلَ عَلَى عِيَالِهِمْ وَذَرَارِيِّ هؤُلَاءِ، الَّذِينَ يُرِيدُونَ أَنْ يَصُدُّونَا عَنِ الْبَيْتِ؟»\n\r\n\n\r\n(மக்களே! எனக்கு ஆலோசனை கூறுங்கள்! இறை இல்லத்திற்குச் செல்ல விடாமல் நம்மைத் தடுக்கும் இவர்களுடைய குடும்பத்தினர் மற்றும் பிள்ளைகள் மீது நாம் தாக்குதல் நடத்தலாமா?)\" மற்றொரு அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«(أَ)تُرَوْنَ أَنْ نَمِيلَ عَلَى ذَرَارِيِّ هؤُلَاءِ الَّذِينَ أَعَانُوهُمْ، فَإِنْ يَأْتُونَا كَانَ اللهُ قَدْ قَطَعَ عُنُقًا مِنَ الْمُشْرِكِينَ، وَإِلَّا تَرَكْنَاهُمْ مَحْزُونِين»\n\r\n\n\r\n(குறைஷிகளுக்கு உதவியவர்களின் குடும்பங்களைத் தாக்கலாம் என நினைக்கிறீர்களா? அவர்கள் நம்மை எதிர்க்க வந்தால், அல்லாஹ் இணைவைப்பாளர்களின் பலத்தைக் குறைத்திருப்பான். இல்லையெனில், அவர்களைத் துக்கத்தில் விட்டுவிடுவோம்!)\" மற்றுமொரு அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَإِنْ قَعَدُوا قَعَدُوا مَوْتُورِينَ مَجْهُودِينَ مَحْزُونِينَ، وَإِنْ نَجَوْا يَكُنْ عُنُقًا قَطَعَهَا اللهُ عَزَّ وَجَلَّ. أَمْ تُرَوْنَ أَنْ نَؤُمَّ الْبَيْتَ فَمَنْ صَدَّنَا عَنْهُ قَاتَلْنَاه»\n\r\n\n\r\n(அவர்கள் அமைதியாக இருந்தால் துக்கத்திலும் சோர்விலும் இருப்பார்கள். ஒருவேளை தப்பித்தாலும், அவர்களின் வலிமையை அல்லாஹ் முறித்திருப்பான். அல்லது நாம் நேராக இறை இல்லத்தை நோக்கிச் செல்வோமா? யாராவது நம்மைத் தடுத்தால் அவர்களுடன் போரிடுவோமா?) அப்போது அபூபக்கர் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதரே! நீங்கள் இறை இல்லத்தை ஜியாரத் செய்யவே வந்தீர்கள்; யாரையும் கொல்லவோ போர் புரியவோ வரவில்லை. எனவே, இறை இல்லத்தை நோக்கிப் புறப்படுங்கள். நம்மை யாராவது தடுத்தால் அவர்களுடன் போரிடுவோம்.\" மற்றொரு அறிவிப்பில் அபூபக்கர் (ரழி) அவர்கள், \"நாங்கள் உம்ரா செய்ய மட்டுமே வந்தோம், போரிட வரவில்லை என்பதை அல்லாஹ்வும் அவனது தூதரும் அறிவார்கள். இருப்பினும் யாராவது எங்களைத் தடுத்தால் அவருடன் போரிடுவோம்\" என்று கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَرُوحُوا إِذَن»\n\r\n\n\r\n(அப்படியானால் புறப்படுங்கள்.) மற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«فَامْضُوا عَلَى اسْمِ اللهِ تَعَالَى»\n\r\n\n\r\n(உயர்ந்தோனான அல்லாஹ்வின் பெயரால் புறப்படுங்கள்.) என்று கூறினார்கள். அவர்கள் சிறிது தூரம் சென்றபோது நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ خَالِدَ بْنَ الْوَلِيدِ فِي خَيْلٍ لِقُرَيْشٍ طَلِيعَةً، فَخُذُوا ذَاتَ الْيَمِين»\n\r\n\n\r\n(குறைஷிகளின் குதிரைப்படைக்குத் தலைமை தாங்கி காலித் பின் அல்-வலீத் முன்னணியில் வந்து கொண்டிருக்கிறார்; எனவே நீங்கள் வலதுபுறப் பாதையில் செல்லுங்கள்.) அல்லாஹ்வின் மீது ஆணையாக, முஸ்லிம் படைகளின் அணிவகுப்பினால் எழுந்த புழுதிப் படலத்தைப் பார்க்கும் வரை காலித் அதை உணரவில்லை. உடனே அவர் குறைஷிகளுக்கு எச்சரிக்கை செய்யத் திரும்பினார். நபி (ஸல்) அவர்கள் முன்னேறிச் சென்று ஒரு மலைப்பாதையை (தநிய்யா) அடைந்தார்கள். அப்போது நபி (ஸல்) அவர்களின் 'அல்-கஸ்வா' எனும் ஒட்டகம் திடீரென அமர்ந்துவிட்டது. மக்கள் அதை எழுப்ப முயன்றும் அது அசையவில்லை. \"அல்-கஸ்வா அடம்பிடிக்கிறது!\" என்று மக்கள் கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا خَلَأَتِ الْقَصْوَاءُ وَمَا ذَاكَ لَهَا بِخُلُقٍ، وَلكِنْ حَبَسَها حَابِسُ الْفِيل»\n\r\n\n\r\n(அல்-கஸ்வா அடம்பிடிக்கவில்லை, அது அதன் குணமும் இல்லை. முன்பு யானையைத் தடுத்தவனே (அல்லாஹ்) இன்று இதையும் தடுத்துள்ளான்.) பின்னர் அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَالَّذِي نَفْسِي بِيَدِهِ لَا يَسْأَلُونِّي خُطَّةً يُعَظِّمُونَ فِيهَا حُرُمَاتِ اللهِ تَعَالَى إِلَّا أَعْطَيْتُهُمْ إِيَّاهَا»\n\r\n\n\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக, அல்லாஹ்வின் புனிதங்களை மதிக்கும் விதமாக அவர்கள் எந்த நிபந்தனையை முன்வைத்தாலும் அதை நான் ஏற்றுக்கொள்வேன்.) பின்னர் நபி (ஸல்) அவர்கள் அதைக் அதட்டியதும் அது எழுந்தது. அவர்கள் திசையை மாற்றி ஹுதைபிய்யாவின் எல்லைப் பகுதிக்குச் சென்றார்கள். அங்கு மிகக் குறைந்த அளவு தண்ணீருடைய ஒரு குழி இருந்தது. மக்கள் அதைச் சிறிது நேரத்தில் தீர்த்துவிட்டனர். தாகத்தால் அவர்கள் கஷ்டப்பட்டபோது நபி (ஸல்) அவர்கள் தங்களின் அம்பறாத்தூணியிலிருந்து ஒரு அம்பை எடுத்துக் கொடுத்தார்கள். அதை அந்தக் குழியில் நட்டதும், அல்லாஹ்வின் மீது ஆணையாக, தண்ணீர் பொங்கி வழிந்தது. அனைவரும் தாகம் தணிந்து திரும்பும் வரை தண்ணீர் சுரந்து கொண்டே இருந்தது.\n\r\n\n\r\nஅவர்கள் அங்கு தங்கியிருந்தபோது பனூ குஸாஆ கோத்திரத்தைச் சேர்ந்த புதைல் பின் வர்கா சிலருடன் வந்தார். அவர்கள் திஹாமா பகுதியைச் சேர்ந்த நபி (ஸல்) அவர்களின் நம்பிக்கைக்குரிய ஆலோசகர்களாக இருந்தனர். புதைல் கூறினான்: 'கஅப் பின் லுஅய் மற்றும் ஆமிர் பின் லுஅய் கோத்திரத்தினர் ஹுதைபிய்யாவின் நீர்நிலைகளில் முகாமிட்டுள்ளனர். அவர்கள் போரிடத் தயாராகப் பால் ஒட்டகங்களுடன் வந்துள்ளனர்; உங்களைக் கஃபாவிற்குள் நுழைய விடமாட்டார்கள்.' அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّا لَمْ نَجِىءْ لِقِتَالِ أَحَدٍ، وَلكِنْ جِئْنَا مُعْتَمِرِينَ، وَإِنَّ قُرَيْشًا قَدْ نَهَكَتْهُمُ الْحَرْبُ، وَأَضَرَّتْ بِهِمْ، فَإِنْ شَاؤُوا مَادَدْتُهُمْ مُدَّةً وَيُخَلُّوا بَيْنِي وَبَيْنَ النَّاسِ، فَإِنْ أَظْهَرْ، فَإِنْ شَاءُوا أَنْ يَدْخُلُوا فِيمَا دَخَلَ فِيهِ النَّاسُ فَعَلُوا، وَإِلَّا فَقَدْ جَمُّوا، وَإِنْ هُمْ أَبَوْا فَوَالَّذِي نَفْسِي بِيَدِهِ لَأُقَاتِلَنَّهُمْ عَلَى أَمْرِي هذَا حَتْى تَنْفَرِدَ سَالِفَتِي أَوْ لَيُنْفِذَنَّ اللهُ أَمْرَه»\n\r\n\n\r\n(நாங்கள் யாருடனும் போரிட வரவில்லை, உம்ரா செய்யவே வந்துள்ளோம். தொடர் போர்களால் குறைஷிகள் பலவீனமடைந்துள்ளனர். அவர்கள் விரும்பினால் நான் அவர்களுடன் ஒரு குறிப்பிட்ட காலத்திற்குச் சமாதான உடன்படிக்கை செய்துகொள்கிறேன். அந்த இடைப்பட்ட காலத்தில் அவர்கள் எனக்கும் மக்களுக்கும் இடையே குறுக்கிடக் கூடாது. நான் மற்றவர்களிடம் வெற்றி பெற்றால், மக்கள் இஸ்லாத்தில் நுழைவது போல குறைஷிகளும் விரும்பினால் நுழையலாம். அல்லது அவர்கள் ஓய்வெடுக்கட்டும். ஆனால் அவர்கள் உடன்படிக்கையை மறுத்தால், என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக, நான் கொல்லப்படும் வரை என் கொள்கைக்காகப் போரிடுவேன். அல்லாஹ் நிச்சயம் தன் மார்க்கத்தை வெற்றி பெறச் செய்வான்.) புதைல் அவர்கள் இச்செய்தியைப் போய்ச் சொன்னார். குறைஷிகளில் இருந்த விவரமற்றவர்கள் அதை அலட்சியப்படுத்தினாலும், அறிவுடையவர்கள் நபி (ஸல்) அவர்கள் சொன்னதைக் கேட்க விரும்பினார்கள்.\n\r\n\n\r\nபின்னர் உர்வா பின் மஸ்ஊத் எழுந்து மக்களிடம் உரையாடினார். அவர், 'முஹம்மது ஒரு நியாயமான கோரிக்கையை வைத்துள்ளார், அதை ஏற்றுக்கொண்டு என்னை அவரிடம் பேச்சுவார்த்தைக்கு அனுப்புங்கள்' என்றார். அவ்வாறே அவர் நபி (ஸல்) அவர்களிடம் சென்று பேசினார். நபி (ஸல்) அவர்கள் புதைலிடம் சொன்னதையே அவரிடமும் கூறினார்கள். அப்போது உர்வா, 'முஹம்மதே! உங்கள் சொந்த உறவுகளையே நீங்கள் அழிக்கப் போகிறீர்களா? இதற்கு முன் எந்த அரபியாவது தன் இனத்தையே அழித்ததாகக் கேள்விப்பட்டதுண்டா? ஒருவேளை நீங்கள் தோற்றால், உங்கள் பின்னால் இருக்கும் இந்தக் கலவையான கூட்டம் உங்களைத் தனியாக விட்டுவிட்டு ஓடிவிடுவார்கள்' என்று கூறினார். இதைக் கேட்டு ஆத்திரமடைந்த அபூபக்கர் (ரழி) அவர்கள், அவரிடம், \"அல்-லாத் (சிலையின்) மர்ம உறுப்பைச் சப்புவாயாக!\" எனக் கூறி, \"நாங்கள் அவரை விட்டுவிட்டு ஓடுவோமா?\" என்று கேட்டார்கள். உர்வா \"யார் இது?\" என்று கேட்டதற்கு, அவர் \"அபூபக்கர்\" என்று மக்கள் கூறினர். உர்வா கூறினார், \"என் மீது நீங்கள் செய்த ஒரு உபகாரத்திற்கு நான் ஈடு செய்ய வேண்டியுள்ளது, இல்லையென்றால் உங்களுக்குப் பதிலடி கொடுத்திருப்பேன்.\"\n\r\n\n\r\nஉர்வா பேசிக்கொண்டிருக்கும்போது நபி (ஸல்) அவர்களின் தாடியைத் தொட்டுப் பேச முயன்றார். அப்போது நபி (ஸல்) அவர்களின் தலைக்கு அருகில் கவசம் அணிந்து வாளுடன் நின்று கொண்டிருந்த அல்-முகீரா பின் ஷுஃபா (ரழி), உர்வாவின் கையை வாளின் கைப்பிடியால் தட்டி, \"அல்லாஹ்வின் தூதரின் (ஸல்) தாடியிலிருந்து கையை எடு\" என்றார். அவர் தனது மருமகனான அல்-முகீரா (ரழி) என்பதை அறிந்ததும், அவரது பழைய துரோகச் செயலைக் குறிப்பிட்டார் (இஸ்லாத்திற்கு முன் அவர் சிலரைக் கொன்றுவிட்டு மக்காவிலிருந்து தப்பி ஓடியிருந்தார்). அதற்கு நபி (ஸல்) அவர்கள், \"உன் இஸ்லாத்தை நான் ஏற்றுக் கொள்கிறேன், ஆனால் உன் முறையற்ற சொத்தை நான் தொடமாட்டேன்\" என்று கூறினார்கள். உர்வா அந்தச் சபையைக் கவனித்தார். நபி (ஸல்) அவர்கள் உமிழ்ந்தால் கூட அதைத் தங்கள் கைகளில் ஏந்தி முகத்தில் பூசிக் கொள்ளும் தோழர்களின் அன்பைக் கண்டார். அவர்கள் உளுச் செய்தால் மீதமுள்ள தண்ணீருக்காகப் போட்டியிடுவதையும், அவர்கள் பேசும்போது அமைதியாக இருப்பதையும் கண்டு வியந்தார். உர்வா திரும்பிச் சென்று குறைஷிகளிடம் கூறினார்: \"மக்களே! நான் சீசர், கிஸ்ரா மற்றும் நஜாஷி போன்ற மன்னர்களிடம் தூது சென்றிருக்கிறேன். ஆனால் முஹம்மது (ஸல்) அவர்களின் தோழர்கள் அவருக்குக் கொடுக்கும் மரியாதையை நான் எங்கும் கண்டதில்லை. அவர் ஒரு நல்ல வழியை முன்வைத்துள்ளார், அதை ஏற்றுக்கொள்ளுங்கள்.\"\n\r\n\n\r\nபின்னர் பனூ கினானாவைச் சேர்ந்த ஒரு மனிதர் வர, அவர் பலி ஒட்டகங்களை மதிப்பவர் என்பதால் நபி (ஸல்) அவர்கள் ஒட்டகங்களை அவர் முன் காட்டச் செய்தார்கள். அதைப் பார்த்த அவர், \"சுப்ஹானல்லாஹ்! இவர்களைத் தடுப்பது முறையல்ல\" என்றார். பிறகு மிக்ரஸ் பின் ஹஃப்ஸ் வந்தபோது நபி (ஸல்) அவர்கள், \"அவன் ஒரு தீய மனிதன்\" என்று கூறினார்கள். அவர் பேசிக் கொண்டிருக்கும்போதே சுஹைல் பின் அம்ர் வந்தார். அப்போது நபி (ஸல்) அவர்கள், \"இப்போது உங்கள் காரியம் எளிதாகிவிட்டது (ஸஹுல)\" என்று கூறினார்கள். சுஹைல் உடன்படிக்கை செய்ய முன்வந்தார். நபி (ஸல்) அவர்கள் அலி (ரழி) அவர்களை அழைத்து, \"பிஸ்மில்லாஹிர் ரஹ்மானிர் ரஹீம் (அளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்) என்று எழுது\" என்றார்கள். சுஹைல், \"அர்-ரஹ்மான் என்றால் என்னவென்று எங்களுக்குத் தெரியாது; வழக்கப்படி 'பிஸ்மிக்கல்லாஹும்ம' (அல்லாஹ்வே உன் பெயரால்) என்றே எழுது\" என்றார். தோழர்கள் மறுத்தாலும் நபி (ஸல்) அவர்கள் அப்படியே எழுதச் சொன்னார்கள்.\n\r\n\n\r\nபின்னர் \"அல்லாஹ்வின் தூதர் முஹம்மது செய்துகொண்ட உடன்படிக்கை\" என்று சொல்ல, சுஹைல், \"நீங்கள் அல்லாஹ்வின் தூதர் என்று நாங்கள் நம்பியிருந்தால் உங்களைத் தடுத்திருக்க மாட்டோமே! எனவே 'முஹம்மது பின் அப்துல்லாஹ்' என்று எழுதுங்கள்\" என்றான். நபி (ஸல்) அவர்கள், \"அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் என்னை மறுத்தாலும் நான் அல்லாஹ்வின் தூதர்தான்; 'முஹம்மது பின் அப்துல்லாஹ்' என்றே எழுது\" என்று அலி (ரழி) அவர்களிடம் கூறினார்கள். அலி (ரழி) அவர்கள் அந்தப் பெயரை அழிக்கத் தயங்கியபோது, நபி (ஸல்) அவர்களே அந்த இடத்தை அழித்தார்கள். அடுத்த ஆண்டு வரலாம் என்பது உள்ளிட்ட நிபந்தனைகள் எழுதப்பட்டன. அப்போது, ஒரு நிபந்தனையாக 'மக்காவிலிருந்து யாராவது முஸ்லிமாக மதினாவிற்கு வந்தால் அவரைத் திருப்பி அனுப்ப வேண்டும்' என்பது சேர்க்கப்பட்டது.\n\r\n\n\r\nபேச்சுவார்த்தை நடந்து கொண்டிருக்கும்போதே, சங்கிலிகளால் பிணைக்கப்பட்டிருந்த அபூ ஜந்தல் பின் சுஹைல் (ரழி) தப்பித்து வந்து முஸ்லிம்களிடம் விழுந்தார். சுஹைல், \"இந்த ஒப்பந்தத்தின்படி இவரைத் தான் நான் முதலில் திரும்பக் கேட்கிறேன்\" என்றார். நபி (ஸல்) அவர்கள் எவ்வளவோ கேட்டும் சுஹைல் விடாப்பிடியாக மறுத்துவிட்டார். அபூ ஜந்தல் (ரழி), \"முஸ்லிம்களே! நான் முஸ்லிமாக வந்த பிறகும் மீண்டும் இணைவைப்பாளர்களிடம் ஒப்படைக்கப்படுகிறேனா?\" என்று கதறினார். அவர் அல்லாஹ்வின் பாதையில் மிகக் கடுமையாகச் சித்திரவதை செய்யப்பட்டிருந்தார்.\n\r\n\n\r\nஉமர் (ரழி) அவர்கள் மிகுந்த கவலையுடன் நபி (ஸல்) அவர்களிடம் சென்று, \"நீங்கள் அல்லாஹ்வின் தூதர் இல்லையா? நம் மார்க்கம் சத்தியமானது இல்லையா?\" என்று கேட்டார். நபி (ஸல்) அவர்கள் \"ஆம்\" என்றார்கள். \"பிறகு நாம் ஏன் இப்படிப் பணிந்து போக வேண்டும்?\" என்று கேட்டதற்கு, நபி (ஸல்) அவர்கள், \"நான் அல்லாஹ்வின் தூதர்; அவனுக்கு நான் மாறு செய்ய மாட்டேன். அவன் எனக்கு உதவி செய்வான்\" என்றார்கள். பின்னர் உமர் (ரழி) அவர்கள் அபூபக்கர் (ரழி) அவர்களிடம் சென்று அதே கேள்விகளைக் கேட்க, அவரும் அதே பதிலையே அளித்தார். \"அவர் அல்லாஹ்வின் தூதர், அவரைப் பற்றிக் கொள்; அவர் சத்தியத்தில் இருக்கிறார்\" என்று அபூபக்கர் (ரழி) கூறினார். உமர் (ரழி) அவர்கள் பின்னாளில் கூறுகையில், \"அன்று நான் கேட்ட அந்தக் கேள்விகளுக்காகப் பரிகாரமாகப் பல நற்செயல்களைச் செய்தேன்\" என்றார்.\n\r\n\n\r\nஉடன்படிக்கை முடிந்ததும் நபி (ஸல்) அவர்கள், \"எழுந்து உங்கள் பலிகளை நிறைவேற்றி, தலைமுடியை மழித்துக் கொள்ளுங்கள்\" என்று மூன்று முறை கூறினார்கள். எவரும் எழாததைக் கண்டு கவலையுடன் உம்மு ஸலமா (ரழி) அவர்களிடம் சென்று முறையிட்டார்கள். அவர், \"நீங்கள் யாரிடமும் பேசாமல் வெளியே சென்று உங்கள் பலியை அறுத்து முடியை மழித்துக் கொள்ளுங்கள்; அதைப் பார்த்தால் அவர்களும் செய்வார்கள்\" என்று அறிவுரை கூறினார். அவ்வாறே நபி (ஸல்) அவர்கள் செய்ய, தோழர்கள் அனைவரும் கவலையுடன் ஒருவருக்கொருவர் தலைமுடியை மழித்துக் கொண்டனர். பின்னர் சூரா அல்-மும்தஹினாவின் வசனங்கள் அருளப்பட்டன.\n\r\n\n\r\nநபி (ஸல்) அவர்கள் மதினாவிற்குத் திரும்பியபோது, அபூ பஸீர் (ரழி) எனும் முஸ்லிம் மக்காவிலிருந்து தப்பி வந்தார். குறைஷிகள் அவரைத் திரும்பக் கேட்டு இருவரை அனுப்பினார்கள். நபி (ஸல்) அவர்கள் உடன்படிக்கையின்படி அவரைத் திருப்பி அனுப்பினார். வழியில் துல்-ஹுலைஃபாவில் தங்கியிருந்தபோது, அபூ பஸீர் தந்திரமாக ஒருவனின் வாளை வாங்கி அவனைக் கொன்றுவிட்டார். மற்றவன் தப்பி ஓடி மதினாவிற்கு வந்து நபி (ஸல்) அவர்களிடம் முறையிட்டான். அபூ பஸீர் அங்கு வந்து, \"அல்லாஹ்வின் தூதரே! உங்கள் உடன்படிக்கையை நீங்கள் நிறைவேற்றிவிட்டீர்கள்; அல்லாஹ் என்னைக் காப்பாற்றிவிட்டான்\" என்றார். நபி (ஸல்) அவர்கள், \"அவனுடைய தாய்க்குத் துக்கமே! அவனுக்கு உதவியாளர்கள் இருந்தால் அவன் ஒரு பெரும் போரை மூட்டுபவனாக இருப்பான்\" என்று கூறினார்கள்.\n\r\n\n\r\nஅபூ பஸீர் (ரழி) அங்கிருந்து தப்பித்துக் கடற்கரையோரப் பகுதிக்குச் சென்றார். அங்கு அபூ ஜந்தல் (ரழி) அவர்களும் வந்து இணைந்தார். இப்படியாக மக்காவிலிருந்து தப்பி வரும் முஸ்லிம்கள் அங்கு ஒரு குழுவாகச் சேர்ந்தனர். அவர்கள் குறைஷிகளின் வியாபாரக் கூட்டங்களைத் தாக்கத் தொடங்கினர். ஒருகட்டத்தில் பொறுக்க முடியாத குறைஷிகள், அந்த முஸ்லிம்களை மதினாவிற்கே அழைத்துக் கொள்ளுமாறு நபி (ஸல்) அவர்களுக்குச் செய்தி அனுப்பினார்கள். அப்போதுதான் சூரா அல்-ஃபத்ஹின் 24-வது வசனம் மற்றும் 26-வது வசனங்கள் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டன.\n\r\n\n\r\nஇமாம் அஹ்மத் மற்றும் அல்-புகாரி ஆகியோர் பதிவு செய்துள்ள மற்றுமொரு அறிவிப்பில், அலி (ரழி) அவர்கள் \"அல்லாஹ்வின் தூதர்\" என்ற பட்டத்தை அழிக்கத் தயங்கியபோது, நபி (ஸல்) அவர்களே அதைத் துடைத்தார்கள். பட்டத்தை அழிப்பதனால் நபித்துவம் மறைந்துவிடாது என்று அவர்களுக்குப் புரிய வைத்தார்கள். மேலும் ஹுதைபிய்யா நாளில் நபி (ஸல்) அவர்கள் எழுபது ஒட்டகங்களைப் பலியிட்டார்கள்; அதில் அபூ ஜஹ்லுக்குச் சொந்தமான வெள்ளி மூக்கு வளையமிடப்பட்ட ஒரு ஒட்டகமும் இருந்தது. அந்த ஒட்டகம் கஅபாவை நோக்கித் தடுக்கப்பட்டபோது, தன் குட்டியைப் பிரிந்த தாய் அழுவது போல அழுதது என்று இப்னு அப்பாஸ் (ரழி) அறிவிக்கிறார்கள்."},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=48&ayah=28\" class=\"link\">48:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 48:28 ஐ பார்க்கவும்"},"28":{"html":"<strong>அல்லாஹ் தன் தூதருக்குக் காட்டிய உண்மையான கனவை நிச்சயமாக நனவாக்கினான்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு கனவில் தாம் மக்காவிற்குள் நுழைவதையும், இறையில்லத்தைச் சுற்றி தவாஃப் செய்வதையும் கண்டார்கள். அவர்கள் மதீனாவில் இருந்தபோதே இக்கனவைப் பற்றித் தம் தோழர்களிடம் (ரழி) கூறினார்கள். ஹிஜ்ரி ஆறாம் ஆண்டு அல்-ஹுதைபிய்யா உடன்படிக்கையின்போது அவர்கள் மக்காவிற்குப் புறப்பட்டபோது, நபி (ஸல்) அவர்களின் கனவு அந்த ஆண்டிலேயே நனவாகும் என்பதில் அவர்களில் யாருக்கும் எவ்வித சந்தேகமும் இருக்கவில்லை. ஆனால், அந்த ஆண்டு சமாதான உடன்படிக்கை செய்யப்பட்டு, அடுத்த ஆண்டு மக்காவிற்கு வர அனுமதிக்கப்பட்டு, அவர்கள் மதீனாவிற்குத் திரும்ப வேண்டிய நிலை ஏற்பட்டபோது, சில தோழர்களுக்கு (ரழி) அது அதிருப்தியை ஏற்படுத்தியது. உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் இதைப் பற்றிக் கேட்டார்கள்: \"நாம் இறையில்லத்திற்குச் சென்று அதைச் சுற்றி தவாஃப் செய்வோம் என்று நீங்கள் எங்களிடம் கூறவில்லையா?\" அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">أَفَأَخْبَرْتُكَ</span> <span class=\"quran-arabic-font text-success\">أَنَّكَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِيهِ</span> <span class=\"quran-arabic-font text-success\">عَامَكَ</span> <span class=\"quran-arabic-font text-success\">هذَا؟</span>»<br />\r\n<br />\r\n(ஆம். ஆனால் இந்த ஆண்டே நீங்கள் அங்கு செல்வீர்கள் என்று நான் உங்களிடம் கூறினேனா?) உமர் (ரழி) அவர்கள் \"இல்லை\" என்றார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَإِنَّكَ</span> <span class=\"quran-arabic-font text-success\">آتِيهِ</span> <span class=\"quran-arabic-font text-success\">وَمُطَّوِّفٌ</span> <span class=\"quran-arabic-font text-success\">بِه</span>»<br />\r\n<br />\r\n(நிச்சயமாக நீங்கள் அங்கு சென்று அதைச் சுற்றி தவாஃப் செய்வீர்கள்.) இதே பதிலைத்தான் அபூபக்ர் அஸ்-சித்தீக் (ரழி) அவர்களிடமிருந்தும் உமர் (ரழி) அவர்கள் எழுத்துக்கு எழுத்து மாறாமல் பெற்றார்கள். இதனால்தான் கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّقَدْ</span> <span class=\"quran-arabic-font text-success\">صَدَقَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">رَسُولَهُ</span> <span class=\"quran-arabic-font text-success\">الرُّؤْيَا</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">لَتَدْخُلُنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدَ</span> <span class=\"quran-arabic-font text-success\">الْحَرَامَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் தன் தூதருக்குக் காட்டிய கனவை உண்மையாகவே நனவாக்கினான். அல்லாஹ் நாடினால், நீங்கள் நிச்சயமாக அல்-மஸ்ஜித் அல்-ஹராமிற்குள் நுழைவீர்கள்.) இந்த விஷயம் நிச்சயமாக நிகழ வேண்டும் என்று அவன் நாடினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ءَامِنِينَ</span><br />\r\n<br />\r\n(பாதுகாப்புடன்,) அதாவது நீங்கள் அங்கு நுழையும்போது அச்சமற்றவர்களாக இருப்பீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُحَلِّقِينَ</span> <span class=\"quran-arabic-font text-success\">رُءُوسَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمُقَصِّرِينَ</span><br />\r\n<br />\r\n((அப்போது உங்களில் சிலர்) தலைமுடியை மழித்தவர்களாகவும், (சிலர்) தலைமுடியைக் குறைத்தவர்களாகவும் இருப்பீர்கள்.) அவ்வாறே அவர்களில் சிலர் தலைமுடியை மழித்துக்கொண்டனர், சிலர் குறைத்துக்கொண்டனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியதாக புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் (ஸஹீஹைன்) பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">رَحِمَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْمُحَلِّقِين</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! தலைமுடியை மழித்துக்கொள்பவர்களுக்குக் கருணை புரிவாயாக.) மக்கள், \"அல்லாஹ்வின் தூதரே! தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்காகவும் பிரார்த்தியுங்கள்\" என்றார்கள். அவர்கள் மீண்டும் கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">رَحِمَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْمُحَلِّقِين</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! தலைமுடியை மழித்துக்கொள்பவர்களுக்குக் கருணை புரிவாயாக.) மக்கள், \"அல்லாஹ்வின் தூதரே! தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்காகவும் பிரார்த்தியுங்கள்\" என்றார்கள். நபி (ஸல்) அவர்கள் மீண்டுமொருமுறை,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">رَحِمَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْمُحَلِّقِين</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! தலைமுடியை மழித்துக்கொள்பவர்களுக்குக் கருணை புரிவாயாக.) என்று கூறினார்கள். மக்கள், \"அல்லாஹ்வின் தூதரே! தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்காகவும் பிரார்த்தியுங்கள்\" என்றார்கள். நபி (ஸல்) அவர்கள் (மூன்றாவது அல்லது நான்காவது முறையாக):<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالْمُقَصِّرِين</span>»<br />\r\n<br />\r\n(தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்கும் கருணை புரிவாயாக) என்று கூறினார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَخَافُونَ</span><br />\r\n<br />\r\n(பயமற்றவர்களாக), இது அவர்கள் மக்காவிற்குள் நுழையும்போது எவ்வித அச்சமுமின்றிப் பாதுகாப்பாக இருப்பார்கள் என்பதைக் குறிக்கிறது. இது அடுத்த ஆண்டு, அதாவது ஹிஜ்ரி ஏழாம் ஆண்டு துல்-கஃதா மாதத்தில் நிறைவேற்றப்பட்ட உம்ராவின் (உம்ரத்துல் களா) போது நிகழ்ந்தது.<br />\r\n<br />\r\nஹிஜ்ரி ஆறாம் ஆண்டு துல்-கஃதா மாதத்தில் அல்-ஹுதைபிய்யாவிலிருந்து திரும்பிய அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனா சென்றார்கள். துல்-ஹஜ் மற்றும் முஹர்ரம் மாதங்களில் அவர்கள் மதீனாவிலேயே தங்கியிருந்தார்கள். பின்னர் ஸஃபர் மாதத்தில் கைபரை நோக்கிப் படையெடுத்துச் சென்றார்கள். அல்லாஹ் அந்த வெற்றியை அவர்களுக்கு வழங்கினான்; அதன் ஒரு பகுதி போரின் மூலமும், மற்றொரு பகுதி மக்கள் சரணடைந்ததன் மூலமும் வசமானது. கைபர் என்பது ஏராளமான பேரீச்ச மரங்களும் விவசாயமும் கொண்ட செழிப்பான மாகாணமாக இருந்தது. நபி (ஸல்) அவர்கள் கைபரின் யூதர்களை அங்கேயே தங்கி விவசாயம் செய்யப் பணித்து, அந்த நிலத்தை ஹுதைபிய்யாவில் கலந்துகொண்ட தோழர்களிடையே பங்கிட்டுக் கொடுத்தார்கள். ஹுதைபிய்யாவில் பங்கேற்ற ஸஹாபாக்களைத் தவிர வேறு யாரும் கைபர் போரில் கலந்துகொள்ளவில்லை. எனினும், எத்தியோப்பியாவிலிருந்து தம் தோழர்களுடன் திரும்பிய ஜஃபர் பின் அபீ தாலிப் (ரழி) அவர்களும், அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்களும் அவர்களது கூட்டத்தினரும் இதில் பங்கேற்றனர். இப்னு ஸைத் என்பாரின் கூற்றுப்படி, அபூ துஜானா சிமாக் பின் கரஷா (ரழி) அவர்களைத் தவிர (ஹுதைபிய்யாவில் இருந்த) வேறு யாரும் இதில் பங்கேற்காமல் இருக்கவில்லை. இது வரலாற்று நூல்களில் விரிவாகப் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\nபின்னர் நபி (ஸல்) அவர்கள் மதீனாவிற்குத் திரும்பினார்கள். ஹிஜ்ரி ஏழாம் ஆண்டு துல்-கஃதா மாதம் வந்தபோது, நபி (ஸல்) அவர்கள் ஹுதைபிய்யாவில் தம்மோடு இருந்தவர்களுடன் உம்ராவிற்காக மக்காவிற்குப் புறப்பட்டார்கள். துல்-ஹுலைஃபா என்ற இடத்தில் இஹ்ராம் அணிந்து, பலிப்பிராணிகளையும் உடன் கொண்டு சென்றார்கள். அறுபது ஒட்டகங்கள் பலிக்காகக் கொண்டு செல்லப்பட்டதாகக் கூறப்படுகிறது. நபி (ஸல்) அவர்களும் தோழர்களும் தல்பியாவை உரக்கக் கூறியவாறு சென்றார்கள். அவர்கள் மர்ருழ்-ழஹ்ரான் எனும் இடத்தை நெருங்கியபோது, முஹம்மது பின் மஸ்லமா (ரழி) அவர்களைக் குதிரைப்படை மற்றும் ஆயுதங்களுடன் தமக்கு முன்னால் நபி (ஸல்) அவர்கள் அனுப்பி வைத்தார்கள்.<br />\r\n<br />\r\nமுன்னேறி வரும் இந்தப் படையைக் கண்ட இணைவைப்பாளர்கள் மிகுந்த அச்சமடைந்தார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களைத் தாக்கப் போகிறார்கள் என்றும், பத்து ஆண்டுகாலப் போர் நிறுத்த ஒப்பந்தத்தை அவர்கள் மீறிவிட்டார்கள் என்றும் எண்ணினார்கள். அவர்கள் இது குறித்து மக்காவாசிகளிடம் தெரிவிக்க விரைந்தார்கள். நபி (ஸல்) அவர்கள் மர்ருழ்-ழஹ்ரான் பகுதியில் முகாமிட்டபோது, ஹரம் எல்லைக்குள் இருந்த சிலைகளை அவர்களால் பார்க்க முடிந்தது. அவர்கள் ஆயுதங்கள், அம்புகள், அம்பு உறைகள் மற்றும் ஈட்டிகளை யஃஜஜ் பள்ளத்தாக்கிற்கு அனுப்பி வைத்தார்கள். அதன் பிறகு, ஒப்பந்தத்தில் குறிப்பிட்டபடி வாள்களை உறைகளுக்குள் வைத்தவர்களாக மக்காவை நோக்கிச் சென்றார்கள்.<br />\r\n<br />\r\nநபி (ஸல்) அவர்கள் மக்காவை நோக்கிச் சென்றுகொண்டிருந்தபோது, குறைஷிகள் மிக்ரஸ் பின் ஹஃப்ஸை அனுப்பினார்கள். அவர், \"முஹம்மதே! நீர் வாக்குறுதியை மீறுபவர் என்று நாங்கள் ஒருபோதும் அறிந்ததில்லை\" என்றார். நபி (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">ذَاكَ؟</span>»<br />\r\n<br />\r\n(நீர் ஏன் அவ்வாறு கூறுகிறீர்?) என்று கேட்டார்கள். மிக்ரஸ், \"நீர் ஆயுதங்கள், அம்புகள் மற்றும் ஈட்டிகளுடன் எங்களை நோக்கி வருகிறீரே!\" என்றார். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَعَثْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَأْجَج</span>»<br />\r\n<br />\r\n(நான் அவ்வாறு செய்யவில்லை, அவை அனைத்தையும் யஃஜஜ் பள்ளத்தாக்கிற்கு அனுப்பிவிட்டேன்.) அதற்கு மிக்ரஸ், \"உம்மைப் பற்றி நாங்கள் அறிந்திருப்பது இதுதான்; நீர் நம்பகமானவர், வாக்குறுதியைக் காப்பவர்\" என்றார்.<br />\r\n<br />\r\nநிராகரிப்பாளர்களின் தலைவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களையும் ஸஹாபாக்களையும் (ரழி) பார்ப்பதைத் தவிர்க்கும் பொருட்டு, ஆத்திரத்துடன் மக்காவை விட்டு வெளியேறினர். ஆனால் மக்காவிலிருந்த ஏனைய ஆண்கள், பெண்கள் மற்றும் குழந்தைகள் வீதிகளிலும் வீட்டுக்கூரைகளிலும் அமர்ந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்களையும் அவர்களது தோழர்களையும் பார்த்துக் கொண்டிருந்தனர். நபி (ஸல்) அவர்கள் தல்பியா கூறியவாறு தம் தோழர்களுடன் மக்காவிற்குள் நுழைந்தார்கள். ஹுதைபிய்யா நாளில் தாம் சவாரி செய்த 'அல்-கஸ்வா' எனும் ஒட்டகத்திலேயே நபி (ஸல்) அவர்கள் அமர்ந்திருக்க, பலிப்பிராணிகளை தூ துவா என்ற இடத்திற்கு அனுப்பி வைத்தார்கள். அன்சாரியான அப்துல்லாஹ் பின் ரவாஹா (ரழி) அவர்கள் நபியவர்களின் ஒட்டகக் கடிவாளத்தைப் பிடித்துக்கொண்டு பின்வரும் கவிதையைப் பாடினார்கள்: \"எவனுடைய மார்க்கத்தைத் தவிர வேறு உண்மையான மார்க்கம் இல்லையோ அவன் பெயரால், முஹம்மது (ஸல்) அவர்கள் எவனுடைய தூதராக இருக்கிறார்களோ அவன் பெயரால், ஓ நிராகரிப்பாளர்களின் பிள்ளைகளே! அவர் வழியை விட்டு விலகி நில்லுங்கள். இந்த வஹீ (இறைச்செய்தி)யை நீங்கள் ஏற்கும்படி நாங்கள் உங்களுடன் போரிட்டதைப் போலவே, இன்று அதன் விளக்கத்தை நிறைவேற்ற உங்களை வற்புறுத்துவோம். இது தலைகளைத் துண்டிக்கும் கடுமையான போர்; தோழன் தன் தோழனைப் பிரிக்கும் போர். அர்-ரஹ்மான் தன் வஹீ (இறைச்செய்தி)யை இறக்கினான், தன் தூதருக்கு முன் ஓதப்படும் பக்கங்களில் (வேதத்தில்) உள்ளது: அல்லாஹ்வின் பாதையில் மரணிப்பதே சிறந்த மரணம். இறைவா! அதன் கூற்றுகளை நான் நம்புகிறேன்.\" இக்கதை பல்வேறு அறிவிப்புகளில் தொகுக்கப்பட்டுள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ள செய்தியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் அவர்களது தோழர்களும் மக்காவிற்கு வந்தபோது, யத்ரிப் (மதீனா) காய்ச்சலால் அவர்கள் பலவீனமடைந்திருந்தனர். இதைக் கேள்விப்பட்ட இணைவைப்பாளர்கள், 'மதீனாக் காய்ச்சலால் பலவீனமடைந்த ஒரு கூட்டம் உங்களிடம் வரப்போகிறது' என்று செய்தியைப் பரப்பினர். அவர்கள் அல்-ஹிஜ்ருக்கு அருகிலுள்ள பகுதியில் அமர்ந்திருந்தனர். இணைவைப்பாளர்கள் பேசுவதை அல்லாஹ் தன் நபிக்குத் தெரிவித்தான். எனவே, இணைவைப்பாளர்களுக்குத் தங்கள் வலிமையைக் காட்டுவதற்காக தவாஃபின் முதல் மூன்று சுற்றுகளில் 'ரமல்' (தோள்களை அசைத்து வேகமாக நடத்தல்) செய்யுமாறு நபி (ஸல்) அவர்கள் தம் தோழர்களுக்குக் கட்டளையிட்டார்கள். அதன்படி தோழர்கள் முதல் மூன்று சுற்றுகளில் ரமல் செய்தனர். இரு மூலைகளுக்கு இடையே சாதாரணமாக நடக்கும்படி நபி (ஸல்) அவர்கள் அவர்களுக்குக் கட்டளையிட்டார்கள், ஏனெனில் அங்கிருந்து இணைவைப்பாளர்கள் அவர்களைப் பார்க்க முடியாது. தோழர்கள் மீதான இரக்கத்தினால், தவாஃபின் அனைத்து சுற்றுகளிலும் ரமல் செய்யுமாறு அவர்கள் கட்டளையிடவில்லை. இதைக் கண்ட இணைவைப்பாளர்கள், 'இவர்களா காய்ச்சலால் பலவீனமடைந்தவர்கள் என்று நீங்கள் கூறினீர்கள்? இவர்கள் இன்னாரை விடவும் அதிக வலிமையுடன் இருக்கிறார்களே!' என்று வியப்புடன் கூறினர்.\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிமிலும் இடம்பெற்றுள்ளது.<br />\r\n<br />\r\nமற்றொரு அறிவிப்பில், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் அவர்களது தோழர்களும் துல்-கஃதா மாதம் நான்காம் நாள் காலை மக்காவிற்கு வந்தார்கள். மதீனாக் காய்ச்சல் அவர்களைப் பலவீனப்படுத்திவிட்டதாக இணைவைப்பாளர்கள் பேசிக்கொண்டதால், நபி (ஸல்) அவர்கள் தவாஃபின் முதல் மூன்று சுற்றுகளில் ரமல் செய்யுமாறு தோழர்களுக்குக் கட்டளையிட்டார்கள். தோழர்கள் மீதான இரக்கத்தினால், தவாஃபின் அனைத்து சுற்றுகளிலும் ரமல் செய்யுமாறு அவர்கள் கட்டளையிடவில்லை.\" அல்-புகாரி பதிவு செய்த செய்தியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில்: \"நபியவர்கள் உடன்படிக்கையின்படி வந்த ஆண்டில் 'ரமல் செய்யுங்கள்' என்று கூறினார்கள். இணைவைப்பாளர்கள் குஅய்கிஆன் மலையிலிருந்து பார்த்துக் கொண்டிருந்தபோது, தம் வலிமையை அவர்களுக்குக் காட்ட இவ்வாறு செய்தார்கள்.\" மேலும், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இணைவைப்பாளர்களுக்குத் தம் வலிமையைக் காட்டுவதற்காகவே கஃபாவைத் தவாஃப் செய்தபோதும், அஸ்-ஸஃபா மற்றும் அல்-மர்வாவுக்கு இடையே ஸயீ செய்தபோதும் அவ்வாறு செய்தார்கள்.\"<br />\r\n<br />\r\nஅல்-புகாரி பதிவு செய்த செய்தியில் அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உம்ராவிற்காகப் புறப்பட்டபோது குறைஷி இணைவைப்பாளர்கள் அவர்களைத் தடுத்தனர். எனவே நபி (ஸல்) அவர்கள் ஹுதைபிய்யாவிலேயே பலிப்பிராணிகளை அறுத்து, தலைமுடியை மழித்துக்கொண்டனர். அடுத்த ஆண்டு உம்ரா செய்வதாகவும், வாள்களைத் தவிர வேறு ஆயுதங்களைக் கொண்டு வரமாட்டோம் என்றும், அவர்கள் அனுமதிக்கும் காலத்திற்கு மேல் மக்காவில் தங்கமாட்டோம் என்றும் அவர்களுடன் ஒரு முறையான உடன்படிக்கை செய்தனர். அதன்படி அடுத்த ஆண்டு நபி (ஸல்) அவர்கள் உம்ராவை நிறைவேற்றி, ஒப்பந்தப்படி மக்காவிற்குள் நுழைந்தார்கள். அவர்கள் மூன்று நாட்கள் தங்கிய பிறகு இணைவைப்பாளர்கள் அங்கிருந்து வெளியேறுமாறு கூற, நபியவர்களும் வெளியேறினார்கள்.\" அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَعَلِمَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">فَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فَتْحاً</span> <span class=\"quran-arabic-font text-success\">قَرِيباً</span><br />\r\n<br />\r\n(நீங்கள் அறியாதவற்றை அவன் அறிந்திருந்தான்; மேலும், அதற்கப்பால் ஒரு சமீபத்திய வெற்றியையும் அவன் வழங்கினான்.) அதாவது, ஹுதைபிய்யா ஆண்டில் நீங்கள் மக்காவிற்குள் நுழைவதைத் தடுத்து உங்களைத் திருப்பி அனுப்பியதில் உள்ள நன்மையையும் பலனையும் கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ் அறிந்திருந்தான். நீங்கள் அறியாதவற்றை அவன் அறிந்திருந்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span><br />\r\n<br />\r\n(மேலும், அதற்கப்பால் அவன் வழங்கினான்) - அதாவது நபியவர்கள் கண்ட கனவில் வாக்களிக்கப்பட்டபடி நீங்கள் மக்காவிற்குள் நுழைவதற்கு முன்பே, ஒரு சமீபத்திய வெற்றியை வழங்கினான். அதுவே உங்களுக்கும் உங்கள் இணைவைப்பாளர் எதிரிகளுக்கும் இடையே ஏற்பட்ட சமாதான உடன்படிக்கையாகும்.<br />\r\n<br />\r\n<strong>முஸ்லிம்கள் அறியப்பட்ட உலகையும், இறுதியில் முழு உலகையும் கைப்பற்றுவார்கள் என்ற நற்செய்தி</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் எதிரிகளையும் பூமியின் ஏனைய மக்களையும் வெற்றி கொள்வார்கள் என்று நம்பிக்கையாளர்களுக்கு நற்செய்தி வழங்கி, கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَرْسَلَ</span> <span class=\"quran-arabic-font text-success\">رَسُولَهُ</span> <span class=\"quran-arabic-font text-success\">بِالْهُدَى</span> <span class=\"quran-arabic-font text-success\">وَدِينِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span><br />\r\n<br />\r\n(அவனே தன் தூதரை நேர்வழியுடனும் சத்திய மார்க்கத்துடனும் அனுப்பினான்.) அதாவது பயனுள்ள அறிவோடும் நற்செயல்களோடும் அனுப்பினான். நிச்சயமாக இஸ்லாமிய ஷரீஆ அறிவு மற்றும் செயல் ஆகிய இரு காரணிகளைக் கொண்டுள்ளது. இதில் உள்ள மார்க்க அறிவு உண்மையானது, இதன் செயல்பாடுகள் அங்கீகரிக்கப்பட்டவை. எனவே, இந்த மார்க்கம் சொல்லும் செய்திகளும் கொள்கைகளும் உண்மையானவை; அதன் கட்டளைகள் நீதியானவை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيُظْهِرَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الدِّينِ</span> <span class=\"quran-arabic-font text-success\">كُلِّهِ</span><br />\r\n<br />\r\n(அதனை எல்லா மார்க்கங்களையும் விட மேலோங்கச் செய்வதற்காக.) பூமியில் உள்ள அரேபியர்கள், அரேபியர் அல்லாதவர்கள் என அனைவரின் மார்க்கங்களையும் விட - அவர்கள் எத்தகைய கொள்கை உடையவர்களாக இருந்தாலும் சரி, நாத்திகர்களாகவோ அல்லது இணைவைப்பாளர்களாகவோ இருந்தாலும் சரி - அதனை மேலோங்கச் செய்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَفَى</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">شَهِيداً</span><br />\r\n<br />\r\n(மேலும், சாட்சியாக அல்லாஹ்வே போதுமானவன்.) முஹம்மது (ஸல்) அவர்கள் அவனது தூதர் என்பதற்கும், அவன் அவருக்கு வெற்றியை அளிப்பான் என்பதற்கும் அல்லாஹ்வே போதுமான சாட்சியாக இருக்கிறான். கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ்வே அனைத்தையும் நன்கறிந்தவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ் தன் தூதருக்குக் காட்டிய உண்மையான கனவை நிச்சயமாக நனவாக்கினான்\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு கனவில் தாம் மக்காவிற்குள் நுழைவதையும், இறையில்லத்தைச் சுற்றி தவாஃப் செய்வதையும் கண்டார்கள். அவர்கள் மதீனாவில் இருந்தபோதே இக்கனவைப் பற்றித் தம் தோழர்களிடம் (ரழி) கூறினார்கள். ஹிஜ்ரி ஆறாம் ஆண்டு அல்-ஹுதைபிய்யா உடன்படிக்கையின்போது அவர்கள் மக்காவிற்குப் புறப்பட்டபோது, நபி (ஸல்) அவர்களின் கனவு அந்த ஆண்டிலேயே நனவாகும் என்பதில் அவர்களில் யாருக்கும் எவ்வித சந்தேகமும் இருக்கவில்லை. ஆனால், அந்த ஆண்டு சமாதான உடன்படிக்கை செய்யப்பட்டு, அடுத்த ஆண்டு மக்காவிற்கு வர அனுமதிக்கப்பட்டு, அவர்கள் மதீனாவிற்குத் திரும்ப வேண்டிய நிலை ஏற்பட்டபோது, சில தோழர்களுக்கு (ரழி) அது அதிருப்தியை ஏற்படுத்தியது. உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் இதைப் பற்றிக் கேட்டார்கள்: \"நாம் இறையில்லத்திற்குச் சென்று அதைச் சுற்றி தவாஃப் செய்வோம் என்று நீங்கள் எங்களிடம் கூறவில்லையா?\" அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«بَلَى أَفَأَخْبَرْتُكَ أَنَّكَ تَأْتِيهِ عَامَكَ هذَا؟»\n\r\n\n\r\n(ஆம். ஆனால் இந்த ஆண்டே நீங்கள் அங்கு செல்வீர்கள் என்று நான் உங்களிடம் கூறினேனா?) உமர் (ரழி) அவர்கள் \"இல்லை\" என்றார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَإِنَّكَ آتِيهِ وَمُطَّوِّفٌ بِه»\n\r\n\n\r\n(நிச்சயமாக நீங்கள் அங்கு சென்று அதைச் சுற்றி தவாஃப் செய்வீர்கள்.) இதே பதிலைத்தான் அபூபக்ர் அஸ்-சித்தீக் (ரழி) அவர்களிடமிருந்தும் உமர் (ரழி) அவர்கள் எழுத்துக்கு எழுத்து மாறாமல் பெற்றார்கள். இதனால்தான் கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nلَّقَدْ صَدَقَ اللَّهُ رَسُولَهُ الرُّؤْيَا بِالْحَقِّ لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِن شَآءَ اللَّهُ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் தன் தூதருக்குக் காட்டிய கனவை உண்மையாகவே நனவாக்கினான். அல்லாஹ் நாடினால், நீங்கள் நிச்சயமாக அல்-மஸ்ஜித் அல்-ஹராமிற்குள் நுழைவீர்கள்.) இந்த விஷயம் நிச்சயமாக நிகழ வேண்டும் என்று அவன் நாடினான்.\n\r\n\n\r\nءَامِنِينَ\n\r\n\n\r\n(பாதுகாப்புடன்,) அதாவது நீங்கள் அங்கு நுழையும்போது அச்சமற்றவர்களாக இருப்பீர்கள்.\n\r\n\n\r\nمُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ\n\r\n\n\r\n((அப்போது உங்களில் சிலர்) தலைமுடியை மழித்தவர்களாகவும், (சிலர்) தலைமுடியைக் குறைத்தவர்களாகவும் இருப்பீர்கள்.) அவ்வாறே அவர்களில் சிலர் தலைமுடியை மழித்துக்கொண்டனர், சிலர் குறைத்துக்கொண்டனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியதாக புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் (ஸஹீஹைன்) பதிவாகியுள்ளது:\n\r\n\n\r\n«رَحِمَ اللهُ الْمُحَلِّقِين»\n\r\n\n\r\n(யா அல்லாஹ்! தலைமுடியை மழித்துக்கொள்பவர்களுக்குக் கருணை புரிவாயாக.) மக்கள், \"அல்லாஹ்வின் தூதரே! தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்காகவும் பிரார்த்தியுங்கள்\" என்றார்கள். அவர்கள் மீண்டும் கூறினார்கள்,\n\r\n\n\r\n«رَحِمَ اللهُ الْمُحَلِّقِين»\n\r\n\n\r\n(யா அல்லாஹ்! தலைமுடியை மழித்துக்கொள்பவர்களுக்குக் கருணை புரிவாயாக.) மக்கள், \"அல்லாஹ்வின் தூதரே! தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்காகவும் பிரார்த்தியுங்கள்\" என்றார்கள். நபி (ஸல்) அவர்கள் மீண்டுமொருமுறை,\n\r\n\n\r\n«رَحِمَ اللهُ الْمُحَلِّقِين»\n\r\n\n\r\n(யா அல்லாஹ்! தலைமுடியை மழித்துக்கொள்பவர்களுக்குக் கருணை புரிவாயாக.) என்று கூறினார்கள். மக்கள், \"அல்லாஹ்வின் தூதரே! தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்காகவும் பிரார்த்தியுங்கள்\" என்றார்கள். நபி (ஸல்) அவர்கள் (மூன்றாவது அல்லது நான்காவது முறையாக):\n\r\n\n\r\n«وَالْمُقَصِّرِين»\n\r\n\n\r\n(தலைமுடியைக் குறைத்துக்கொள்பவர்களுக்கும் கருணை புரிவாயாக) என்று கூறினார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nلاَ تَخَافُونَ\n\r\n\n\r\n(பயமற்றவர்களாக), இது அவர்கள் மக்காவிற்குள் நுழையும்போது எவ்வித அச்சமுமின்றிப் பாதுகாப்பாக இருப்பார்கள் என்பதைக் குறிக்கிறது. இது அடுத்த ஆண்டு, அதாவது ஹிஜ்ரி ஏழாம் ஆண்டு துல்-கஃதா மாதத்தில் நிறைவேற்றப்பட்ட உம்ராவின் (உம்ரத்துல் களா) போது நிகழ்ந்தது.\n\r\n\n\r\nஹிஜ்ரி ஆறாம் ஆண்டு துல்-கஃதா மாதத்தில் அல்-ஹுதைபிய்யாவிலிருந்து திரும்பிய அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனா சென்றார்கள். துல்-ஹஜ் மற்றும் முஹர்ரம் மாதங்களில் அவர்கள் மதீனாவிலேயே தங்கியிருந்தார்கள். பின்னர் ஸஃபர் மாதத்தில் கைபரை நோக்கிப் படையெடுத்துச் சென்றார்கள். அல்லாஹ் அந்த வெற்றியை அவர்களுக்கு வழங்கினான்; அதன் ஒரு பகுதி போரின் மூலமும், மற்றொரு பகுதி மக்கள் சரணடைந்ததன் மூலமும் வசமானது. கைபர் என்பது ஏராளமான பேரீச்ச மரங்களும் விவசாயமும் கொண்ட செழிப்பான மாகாணமாக இருந்தது. நபி (ஸல்) அவர்கள் கைபரின் யூதர்களை அங்கேயே தங்கி விவசாயம் செய்யப் பணித்து, அந்த நிலத்தை ஹுதைபிய்யாவில் கலந்துகொண்ட தோழர்களிடையே பங்கிட்டுக் கொடுத்தார்கள். ஹுதைபிய்யாவில் பங்கேற்ற ஸஹாபாக்களைத் தவிர வேறு யாரும் கைபர் போரில் கலந்துகொள்ளவில்லை. எனினும், எத்தியோப்பியாவிலிருந்து தம் தோழர்களுடன் திரும்பிய ஜஃபர் பின் அபீ தாலிப் (ரழி) அவர்களும், அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்களும் அவர்களது கூட்டத்தினரும் இதில் பங்கேற்றனர். இப்னு ஸைத் என்பாரின் கூற்றுப்படி, அபூ துஜானா சிமாக் பின் கரஷா (ரழி) அவர்களைத் தவிர (ஹுதைபிய்யாவில் இருந்த) வேறு யாரும் இதில் பங்கேற்காமல் இருக்கவில்லை. இது வரலாற்று நூல்களில் விரிவாகப் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nபின்னர் நபி (ஸல்) அவர்கள் மதீனாவிற்குத் திரும்பினார்கள். ஹிஜ்ரி ஏழாம் ஆண்டு துல்-கஃதா மாதம் வந்தபோது, நபி (ஸல்) அவர்கள் ஹுதைபிய்யாவில் தம்மோடு இருந்தவர்களுடன் உம்ராவிற்காக மக்காவிற்குப் புறப்பட்டார்கள். துல்-ஹுலைஃபா என்ற இடத்தில் இஹ்ராம் அணிந்து, பலிப்பிராணிகளையும் உடன் கொண்டு சென்றார்கள். அறுபது ஒட்டகங்கள் பலிக்காகக் கொண்டு செல்லப்பட்டதாகக் கூறப்படுகிறது. நபி (ஸல்) அவர்களும் தோழர்களும் தல்பியாவை உரக்கக் கூறியவாறு சென்றார்கள். அவர்கள் மர்ருழ்-ழஹ்ரான் எனும் இடத்தை நெருங்கியபோது, முஹம்மது பின் மஸ்லமா (ரழி) அவர்களைக் குதிரைப்படை மற்றும் ஆயுதங்களுடன் தமக்கு முன்னால் நபி (ஸல்) அவர்கள் அனுப்பி வைத்தார்கள்.\n\r\n\n\r\nமுன்னேறி வரும் இந்தப் படையைக் கண்ட இணைவைப்பாளர்கள் மிகுந்த அச்சமடைந்தார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களைத் தாக்கப் போகிறார்கள் என்றும், பத்து ஆண்டுகாலப் போர் நிறுத்த ஒப்பந்தத்தை அவர்கள் மீறிவிட்டார்கள் என்றும் எண்ணினார்கள். அவர்கள் இது குறித்து மக்காவாசிகளிடம் தெரிவிக்க விரைந்தார்கள். நபி (ஸல்) அவர்கள் மர்ருழ்-ழஹ்ரான் பகுதியில் முகாமிட்டபோது, ஹரம் எல்லைக்குள் இருந்த சிலைகளை அவர்களால் பார்க்க முடிந்தது. அவர்கள் ஆயுதங்கள், அம்புகள், அம்பு உறைகள் மற்றும் ஈட்டிகளை யஃஜஜ் பள்ளத்தாக்கிற்கு அனுப்பி வைத்தார்கள். அதன் பிறகு, ஒப்பந்தத்தில் குறிப்பிட்டபடி வாள்களை உறைகளுக்குள் வைத்தவர்களாக மக்காவை நோக்கிச் சென்றார்கள்.\n\r\n\n\r\nநபி (ஸல்) அவர்கள் மக்காவை நோக்கிச் சென்றுகொண்டிருந்தபோது, குறைஷிகள் மிக்ரஸ் பின் ஹஃப்ஸை அனுப்பினார்கள். அவர், \"முஹம்மதே! நீர் வாக்குறுதியை மீறுபவர் என்று நாங்கள் ஒருபோதும் அறிந்ததில்லை\" என்றார். நபி (ஸல்) அவர்கள்,\n\r\n\n\r\n«وَمَا ذَاكَ؟»\n\r\n\n\r\n(நீர் ஏன் அவ்வாறு கூறுகிறீர்?) என்று கேட்டார்கள். மிக்ரஸ், \"நீர் ஆயுதங்கள், அம்புகள் மற்றும் ஈட்டிகளுடன் எங்களை நோக்கி வருகிறீரே!\" என்றார். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَمْ يَكُنْ ذلِكَ وَقَدْ بَعَثْنَا بِهِ إِلَى يَأْجَج»\n\r\n\n\r\n(நான் அவ்வாறு செய்யவில்லை, அவை அனைத்தையும் யஃஜஜ் பள்ளத்தாக்கிற்கு அனுப்பிவிட்டேன்.) அதற்கு மிக்ரஸ், \"உம்மைப் பற்றி நாங்கள் அறிந்திருப்பது இதுதான்; நீர் நம்பகமானவர், வாக்குறுதியைக் காப்பவர்\" என்றார்.\n\r\n\n\r\nநிராகரிப்பாளர்களின் தலைவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களையும் ஸஹாபாக்களையும் (ரழி) பார்ப்பதைத் தவிர்க்கும் பொருட்டு, ஆத்திரத்துடன் மக்காவை விட்டு வெளியேறினர். ஆனால் மக்காவிலிருந்த ஏனைய ஆண்கள், பெண்கள் மற்றும் குழந்தைகள் வீதிகளிலும் வீட்டுக்கூரைகளிலும் அமர்ந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்களையும் அவர்களது தோழர்களையும் பார்த்துக் கொண்டிருந்தனர். நபி (ஸல்) அவர்கள் தல்பியா கூறியவாறு தம் தோழர்களுடன் மக்காவிற்குள் நுழைந்தார்கள். ஹுதைபிய்யா நாளில் தாம் சவாரி செய்த 'அல்-கஸ்வா' எனும் ஒட்டகத்திலேயே நபி (ஸல்) அவர்கள் அமர்ந்திருக்க, பலிப்பிராணிகளை தூ துவா என்ற இடத்திற்கு அனுப்பி வைத்தார்கள். அன்சாரியான அப்துல்லாஹ் பின் ரவாஹா (ரழி) அவர்கள் நபியவர்களின் ஒட்டகக் கடிவாளத்தைப் பிடித்துக்கொண்டு பின்வரும் கவிதையைப் பாடினார்கள்: \"எவனுடைய மார்க்கத்தைத் தவிர வேறு உண்மையான மார்க்கம் இல்லையோ அவன் பெயரால், முஹம்மது (ஸல்) அவர்கள் எவனுடைய தூதராக இருக்கிறார்களோ அவன் பெயரால், ஓ நிராகரிப்பாளர்களின் பிள்ளைகளே! அவர் வழியை விட்டு விலகி நில்லுங்கள். இந்த வஹீ (இறைச்செய்தி)யை நீங்கள் ஏற்கும்படி நாங்கள் உங்களுடன் போரிட்டதைப் போலவே, இன்று அதன் விளக்கத்தை நிறைவேற்ற உங்களை வற்புறுத்துவோம். இது தலைகளைத் துண்டிக்கும் கடுமையான போர்; தோழன் தன் தோழனைப் பிரிக்கும் போர். அர்-ரஹ்மான் தன் வஹீ (இறைச்செய்தி)யை இறக்கினான், தன் தூதருக்கு முன் ஓதப்படும் பக்கங்களில் (வேதத்தில்) உள்ளது: அல்லாஹ்வின் பாதையில் மரணிப்பதே சிறந்த மரணம். இறைவா! அதன் கூற்றுகளை நான் நம்புகிறேன்.\" இக்கதை பல்வேறு அறிவிப்புகளில் தொகுக்கப்பட்டுள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ள செய்தியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் அவர்களது தோழர்களும் மக்காவிற்கு வந்தபோது, யத்ரிப் (மதீனா) காய்ச்சலால் அவர்கள் பலவீனமடைந்திருந்தனர். இதைக் கேள்விப்பட்ட இணைவைப்பாளர்கள், 'மதீனாக் காய்ச்சலால் பலவீனமடைந்த ஒரு கூட்டம் உங்களிடம் வரப்போகிறது' என்று செய்தியைப் பரப்பினர். அவர்கள் அல்-ஹிஜ்ருக்கு அருகிலுள்ள பகுதியில் அமர்ந்திருந்தனர். இணைவைப்பாளர்கள் பேசுவதை அல்லாஹ் தன் நபிக்குத் தெரிவித்தான். எனவே, இணைவைப்பாளர்களுக்குத் தங்கள் வலிமையைக் காட்டுவதற்காக தவாஃபின் முதல் மூன்று சுற்றுகளில் 'ரமல்' (தோள்களை அசைத்து வேகமாக நடத்தல்) செய்யுமாறு நபி (ஸல்) அவர்கள் தம் தோழர்களுக்குக் கட்டளையிட்டார்கள். அதன்படி தோழர்கள் முதல் மூன்று சுற்றுகளில் ரமல் செய்தனர். இரு மூலைகளுக்கு இடையே சாதாரணமாக நடக்கும்படி நபி (ஸல்) அவர்கள் அவர்களுக்குக் கட்டளையிட்டார்கள், ஏனெனில் அங்கிருந்து இணைவைப்பாளர்கள் அவர்களைப் பார்க்க முடியாது. தோழர்கள் மீதான இரக்கத்தினால், தவாஃபின் அனைத்து சுற்றுகளிலும் ரமல் செய்யுமாறு அவர்கள் கட்டளையிடவில்லை. இதைக் கண்ட இணைவைப்பாளர்கள், 'இவர்களா காய்ச்சலால் பலவீனமடைந்தவர்கள் என்று நீங்கள் கூறினீர்கள்? இவர்கள் இன்னாரை விடவும் அதிக வலிமையுடன் இருக்கிறார்களே!' என்று வியப்புடன் கூறினர்.\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிமிலும் இடம்பெற்றுள்ளது.\n\r\n\n\r\nமற்றொரு அறிவிப்பில், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் அவர்களது தோழர்களும் துல்-கஃதா மாதம் நான்காம் நாள் காலை மக்காவிற்கு வந்தார்கள். மதீனாக் காய்ச்சல் அவர்களைப் பலவீனப்படுத்திவிட்டதாக இணைவைப்பாளர்கள் பேசிக்கொண்டதால், நபி (ஸல்) அவர்கள் தவாஃபின் முதல் மூன்று சுற்றுகளில் ரமல் செய்யுமாறு தோழர்களுக்குக் கட்டளையிட்டார்கள். தோழர்கள் மீதான இரக்கத்தினால், தவாஃபின் அனைத்து சுற்றுகளிலும் ரமல் செய்யுமாறு அவர்கள் கட்டளையிடவில்லை.\" அல்-புகாரி பதிவு செய்த செய்தியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில்: \"நபியவர்கள் உடன்படிக்கையின்படி வந்த ஆண்டில் 'ரமல் செய்யுங்கள்' என்று கூறினார்கள். இணைவைப்பாளர்கள் குஅய்கிஆன் மலையிலிருந்து பார்த்துக் கொண்டிருந்தபோது, தம் வலிமையை அவர்களுக்குக் காட்ட இவ்வாறு செய்தார்கள்.\" மேலும், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இணைவைப்பாளர்களுக்குத் தம் வலிமையைக் காட்டுவதற்காகவே கஃபாவைத் தவாஃப் செய்தபோதும், அஸ்-ஸஃபா மற்றும் அல்-மர்வாவுக்கு இடையே ஸயீ செய்தபோதும் அவ்வாறு செய்தார்கள்.\"\n\r\n\n\r\nஅல்-புகாரி பதிவு செய்த செய்தியில் அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உம்ராவிற்காகப் புறப்பட்டபோது குறைஷி இணைவைப்பாளர்கள் அவர்களைத் தடுத்தனர். எனவே நபி (ஸல்) அவர்கள் ஹுதைபிய்யாவிலேயே பலிப்பிராணிகளை அறுத்து, தலைமுடியை மழித்துக்கொண்டனர். அடுத்த ஆண்டு உம்ரா செய்வதாகவும், வாள்களைத் தவிர வேறு ஆயுதங்களைக் கொண்டு வரமாட்டோம் என்றும், அவர்கள் அனுமதிக்கும் காலத்திற்கு மேல் மக்காவில் தங்கமாட்டோம் என்றும் அவர்களுடன் ஒரு முறையான உடன்படிக்கை செய்தனர். அதன்படி அடுத்த ஆண்டு நபி (ஸல்) அவர்கள் உம்ராவை நிறைவேற்றி, ஒப்பந்தப்படி மக்காவிற்குள் நுழைந்தார்கள். அவர்கள் மூன்று நாட்கள் தங்கிய பிறகு இணைவைப்பாளர்கள் அங்கிருந்து வெளியேறுமாறு கூற, நபியவர்களும் வெளியேறினார்கள்.\" அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nفَعَلِمَ مَا لَمْ تَعْلَمُواْ فَجَعَلَ مِن دُونِ ذَلِكَ فَتْحاً قَرِيباً\n\r\n\n\r\n(நீங்கள் அறியாதவற்றை அவன் அறிந்திருந்தான்; மேலும், அதற்கப்பால் ஒரு சமீபத்திய வெற்றியையும் அவன் வழங்கினான்.) அதாவது, ஹுதைபிய்யா ஆண்டில் நீங்கள் மக்காவிற்குள் நுழைவதைத் தடுத்து உங்களைத் திருப்பி அனுப்பியதில் உள்ள நன்மையையும் பலனையும் கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ் அறிந்திருந்தான். நீங்கள் அறியாதவற்றை அவன் அறிந்திருந்தான்.\n\r\n\n\r\nفَجَعَلَ مِن دُونِ ذَلِكَ\n\r\n\n\r\n(மேலும், அதற்கப்பால் அவன் வழங்கினான்) - அதாவது நபியவர்கள் கண்ட கனவில் வாக்களிக்கப்பட்டபடி நீங்கள் மக்காவிற்குள் நுழைவதற்கு முன்பே, ஒரு சமீபத்திய வெற்றியை வழங்கினான். அதுவே உங்களுக்கும் உங்கள் இணைவைப்பாளர் எதிரிகளுக்கும் இடையே ஏற்பட்ட சமாதான உடன்படிக்கையாகும்.\n\r\n\n\r\nமுஸ்லிம்கள் அறியப்பட்ட உலகையும், இறுதியில் முழு உலகையும் கைப்பற்றுவார்கள் என்ற நற்செய்தி\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் எதிரிகளையும் பூமியின் ஏனைய மக்களையும் வெற்றி கொள்வார்கள் என்று நம்பிக்கையாளர்களுக்கு நற்செய்தி வழங்கி, கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nهُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ\n\r\n\n\r\n(அவனே தன் தூதரை நேர்வழியுடனும் சத்திய மார்க்கத்துடனும் அனுப்பினான்.) அதாவது பயனுள்ள அறிவோடும் நற்செயல்களோடும் அனுப்பினான். நிச்சயமாக இஸ்லாமிய ஷரீஆ அறிவு மற்றும் செயல் ஆகிய இரு காரணிகளைக் கொண்டுள்ளது. இதில் உள்ள மார்க்க அறிவு உண்மையானது, இதன் செயல்பாடுகள் அங்கீகரிக்கப்பட்டவை. எனவே, இந்த மார்க்கம் சொல்லும் செய்திகளும் கொள்கைகளும் உண்மையானவை; அதன் கட்டளைகள் நீதியானவை.\n\r\n\n\r\nلِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ\n\r\n\n\r\n(அதனை எல்லா மார்க்கங்களையும் விட மேலோங்கச் செய்வதற்காக.) பூமியில் உள்ள அரேபியர்கள், அரேபியர் அல்லாதவர்கள் என அனைவரின் மார்க்கங்களையும் விட - அவர்கள் எத்தகைய கொள்கை உடையவர்களாக இருந்தாலும் சரி, நாத்திகர்களாகவோ அல்லது இணைவைப்பாளர்களாகவோ இருந்தாலும் சரி - அதனை மேலோங்கச் செய்தான்.\n\r\n\n\r\nوَكَفَى بِاللَّهِ شَهِيداً\n\r\n\n\r\n(மேலும், சாட்சியாக அல்லாஹ்வே போதுமானவன்.) முஹம்மது (ஸல்) அவர்கள் அவனது தூதர் என்பதற்கும், அவன் அவருக்கு வெற்றியை அளிப்பான் என்பதற்கும் அல்லாஹ்வே போதுமான சாட்சியாக இருக்கிறான். கண்ணியமும் மகத்துவமும் மிக்க அல்லாஹ்வே அனைத்தையும் நன்கறிந்தவன்."},"29":{"html":"<strong>உண்மையான இறைநம்பிக்கையாளர்களின் பண்புகளும் அவர்களின் மேன்மையும்</strong><br />\r\n<br />\r\nமுஹம்மது (ஸல்) அவர்கள் நிச்சயமாக அல்லாஹ்வின் தூதர் என்று அல்லாஹ் அறிவிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُّحَمَّدٌ</span> <span class=\"quran-arabic-font text-success\">رَّسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n(முஹம்மது அல்லாஹ்வின் தூதராவார்.) இந்தப் பண்பு அனைத்து அழகான வர்ணனைகளையும் உள்ளடக்கியது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்களை (ரழி) அல்லாஹ் புகழ்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">أَشِدَّآءُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكُفَّارِ</span> <span class=\"quran-arabic-font text-success\">رُحَمَآءُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span><br />\r\n(அவருடன் இருப்பவர்கள் நிராகரிப்பாளர்களிடம் கடுமையானவர்களாகவும், தங்களுக்குள் கருணையுள்ளவர்களாகவும் இருக்கிறார்கள்.)<br />\r\n<br />\r\nகண்ணியமும் உயர்வும் மிக்க அல்லாஹ் மற்றொரு வசனத்தில் (ஆயத்தில்) கூறியவாறு:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">يُحِبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَيُحِبُّونَهُ</span> <span class=\"quran-arabic-font text-success\">أَذِلَّةٍ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">أَعِزَّةٍ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span><br />\r\n(அல்லாஹ் ஒரு சமூகத்தைக் கொண்டு வருவான்; அவர்களை அவன் நேசிப்பான், அவனையும் அவர்கள் நேசிப்பார்கள். அவர்கள் இறைநம்பிக்கையாளர்களிடம் பணிவாகவும், நிராகரிப்பாளர்களிடம் கடுமையாகவும் நடப்பார்கள்.) (<a href=\"qurandisp.php?sura=5&ayah=54\" class=\"link\">5:54</a>). இதுவே இறைநம்பிக்கையாளர்களின் வர்ணனையாகும்: நிராகரிப்பாளர்களிடம் கண்டிப்புடனும், இறைநம்பிக்கையாளர்களிடம் கருணையும் அன்பும் கொண்டவர்களாகவும் இருப்பார்கள். நிராகரிப்பாளர்களுக்கு முன்னால் புன்னகைக்காமல் கடுமையாகவும், தனது இறைநம்பிக்கையாளர் சகோதரருக்கு முன்னால் மகிழ்ச்சியுடன் புன்னகை பூத்த முகத்துடனும் இருப்பார்கள். உயர்ந்தவனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">قَاتِلُواْ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَلُونَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْكُفَّارِ</span> <span class=\"quran-arabic-font text-success\">وَلِيَجِدُواْ</span> <span class=\"quran-arabic-font text-success\">فِيكُمْ</span> <span class=\"quran-arabic-font text-success\">غِلْظَةً</span><br />\r\n(இறைநம்பிக்கை கொண்டவர்களே! உங்களுக்கு அருகிலுள்ள நிராகரிப்பாளர்களுடன் போரிடுங்கள்; அவர்கள் உங்களிடம் கடுமையைக் காணட்டும்.) (<a href=\"qurandisp.php?sura=9&ayah=123\" class=\"link\">9:123</a>).<br />\r\n<br />\r\nநபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">تَوَادِّهِمْ</span> <span class=\"quran-arabic-font text-success\">وَتَرَاحُمِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الْجَسَدِ</span> <span class=\"quran-arabic-font text-success\">الْوَاحِدِ،</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اشْتَكَى</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">عُضْوٌ</span> <span class=\"quran-arabic-font text-success\">تَدَاعَى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">سَائِرُ</span> <span class=\"quran-arabic-font text-success\">الْجَسَدِ</span> <span class=\"quran-arabic-font text-success\">بِالْحُمَّى</span> <span class=\"quran-arabic-font text-success\">وَالسَّهَر</span>»<br />\r\n(பரஸ்பரம் அன்பு பாராட்டுவதிலும் கருணை காட்டுவதிலும் இறைநம்பிக்கையாளர்களுக்கு உவமை ஓர் உடலைப் போன்றதாகும். அதன் ஓர் உறுப்பு நோய்வாய்ப்பட்டால், மற்ற உறுப்புகளும் காய்ச்சல் மற்றும் தூக்கமின்மையால் அதற்குத் துணை நிற்கின்றன.)<br />\r\n<br />\r\nநபி (ஸல்) அவர்கள் மேலும் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">لِلْمُؤْمِنِ</span> <span class=\"quran-arabic-font text-success\">كَالْبُنْيَانِ</span> <span class=\"quran-arabic-font text-success\">يَشُدُّ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُ</span> <span class=\"quran-arabic-font text-success\">بَعْضًا</span>»<br />\r\n(ஓர் இறைநம்பிக்கையாளர் மற்றோர் இறைநம்பிக்கையாளருக்கு ஒரு கட்டிடத்தைப் போன்றவர்; அதன் ஒரு பகுதி மற்றொரு பகுதியை வலுப்படுத்துகிறது.) பிறகு அவர்கள் தனது விரல்களை ஒன்றோடொன்று கோர்த்துக் காட்டினார்கள். இந்த இரு ஹதீஸ்களும் ஸஹீஹ் நூல்களில் இடம்பெற்றுள்ளன. கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَرَاهُمْ</span> <span class=\"quran-arabic-font text-success\">رُكَّعاً</span> <span class=\"quran-arabic-font text-success\">سُجَّداً</span> <span class=\"quran-arabic-font text-success\">يَبْتَغُونَ</span> <span class=\"quran-arabic-font text-success\">فَضْلاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرِضْوَاناً</span><br />\r\n(அவர்கள் ருகூஃ செய்பவர்களாகவும், ஸஜ்தா செய்பவர்களாகவும், அல்லாஹ்விடமிருந்து அருளையும் அவனது பொருத்தத்தையும் தேடுபவர்களாகவும் இருப்பதை நீர் காண்பீர்.)<br />\r\n<br />\r\nஇறைநம்பிக்கையாளர்கள் நற்செயல்கள் புரிவதிலும், வணக்கங்களிலேயே மிகச் சிறந்ததான தொழுகையிலும் சுறுசுறுப்பாக இருப்பவர்கள் என்று அல்லாஹ் விவரிக்கிறான். அதே சமயம், அவர்கள் தொழுகையில் கண்ணியமும் உயர்வும் மிக்க அல்லாஹ்விடம் உளத்தூய்மையுடன் இருந்து, அவனது தாராளமான வெகுமதியை மட்டுமே எதிர்பார்க்கிறார்கள். அல்லாஹ்வின் சிறந்த வெகுமதி அவனது அருட்கொடைகளும், கிருபைகளும், ஏராளமான வாழ்வாதாரங்களும் நிறைந்த சொர்க்கமாகும். அத்துடன், முந்தைய வெகுமதியை விட மேலான அவனது திருப்பொருத்தத்தைப் பெறுவதும் இதில் அடங்கும். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرِضْوَانٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span><br />\r\n(மேலும் அல்லாஹ்வின் திருப்பொருத்தமே மிகப்பெரியது.) (<a href=\"qurandisp.php?sura=9&ayah=72\" class=\"link\">9:72</a>).<br />\r\n<br />\r\nஅடுத்து வரும் உயர்ந்தவனாகிய அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سِيمَاهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَثَرِ</span> <span class=\"quran-arabic-font text-success\">السُّجُودِ</span><br />\r\n(ஸஜ்தாவின் அடையாளங்கள் அவர்களின் முகங்களில் இருக்கும்.) இதற்கு 'அழகிய தோற்றம்' என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் விளக்கியுள்ளதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள். முஜாஹித் மற்றும் பல அறிஞர்கள், \"இதன் பொருள் பணிவும் இறையச்சமும் ஆகும்\" என்று விளக்குகிறார்கள். சிலர், \"நற்செயல் என்பது இதயத்திற்கு ஒளியையும், முகத்திற்குப் பொலிவையும், வாழ்வாதாரத்தில் விசாலத்தையும், மக்களின் இதயங்களில் அன்பையும் ஏற்படுத்துகிறது\" என்று கூறுகின்றனர். இறைநம்பிக்கையாளர்களின் தலைவர் உஸ்மான் பின் அஃப்பான் (ரழி) அவர்கள் கூறினார்கள்: \"யாராவது ஒரு ரகசியத்தை மறைத்து வைத்திருந்தால், அல்லாஹ் அதனை அவரது முகத்திலோ அல்லது அவர் அறியாமல் நழுவும் வார்த்தைகளின் மூலமோ வெளிப்படுத்தியே தீருவான்.\"<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) அவர்கள், நபி (ஸல்) அவர்கள் பின்வருமாறு கூறியதாக அறிவித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْهَدْيَ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَ،</span> <span class=\"quran-arabic-font text-success\">وَالسَّمْتَ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَ،</span> <span class=\"quran-arabic-font text-success\">وَالْاقْتِصَادَ،</span> <span class=\"quran-arabic-font text-success\">جُزْءٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَمْسَةٍ</span> <span class=\"quran-arabic-font text-success\">وَعِشْرِينَ</span> <span class=\"quran-arabic-font text-success\">جُزْءًا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النُّبُوَّة</span>»<br />\r\n(நிச்சயமாக நன்னடத்தை, அழகிய தோற்றம் மற்றும் நிதானம் ஆகியவை நபித்துவத்தின் இருபத்தைந்து பாகங்களில் ஒரு பாகமாகும்.) அபூ தாவூத் அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nஎனவே, தோழர்கள் (ரழி) தூய்மையான எண்ணங்களையும் நற்செயல்களையும் கொண்டிருந்ததால், அவர்களைப் பார்த்த எவரும் அவர்களின் தோற்றத்தையும் நடத்தையையும் விரும்பினர். இமாம் மாலிக் அவர்கள் கூறுகிறார்கள்: \"அஷ்-ஷாமைக் கைப்பற்றிய தோழர்களை (ரழி) பார்த்த கிறிஸ்தவர்கள், 'அல்லாஹ்வின் மீது சத்தியமாக, எங்களுக்குச் சொல்லப்பட்ட தகவல்களின்படி, இந்த மக்கள் (ஈஸா (அலை) அவர்களின்) சீடர்களை விடச் சிறந்தவர்களாக இருக்கிறார்கள்' என்று வியந்ததாக எனக்குத் தகவல் கிடைத்தது.\" அவர்கள் கூறியது உண்மையே; ஏனெனில் இந்தச் சமுதாயத்தைப் பற்றி முந்தைய வேதங்களில் கண்ணியமான முறையில் குறிப்பிடப்பட்டுள்ளது.<br />\r\n<br />\r\nஇந்த உம்மத்தின் மிகச் சிறந்த மற்றும் கண்ணியமானவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்கள் (ரழி) ஆவார்கள். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் அவர்களை முந்தைய வேதங்களிலும் இறைச்செய்திகளிலும் (வஹீ) புகழ்ந்துள்ளான். அதனால்தான் அவன் இங்கு பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَثَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">التَّوْرَاةِ</span><br />\r\n(இதுவே தவ்ராத்தில் அவர்களுக்குள்ள உவமையாகும்.) பிறகு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَثَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الإِنجِيلِ</span> <span class=\"quran-arabic-font text-success\">كَزَرْعٍ</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">شَطْأَهُ</span><br />\r\n(இன்ஜீலில் அவர்களுக்குள்ள உவமையாவது: அது ஒரு பயிரைப் போன்றது; அது தனது முளையை (ஷத்ஆ) வெளிப்படுத்துகிறது.) முளை அல்லது கிளை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَآزَرَهُ</span><br />\r\n(பிறகு அதனை அது வலுப்படுத்துகிறது.) அது தானாக நிற்க முடிகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَغْلَظَ</span><br />\r\n(பின்பு அது தடிமனாகிறது.) வளர்ச்சியடைந்து உயரமாகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَوَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">سُوقِهِ</span> <span class=\"quran-arabic-font text-success\">يُعْجِبُ</span> <span class=\"quran-arabic-font text-success\">الزُّرَّاعَ</span><br />\r\n(பிறகு அது தனது தண்டின் மீது நிமிர்ந்து நின்று பயிரிட்டவர்களை வியக்க வைக்கிறது.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்களை (ரழி) விவரிக்கும் உவமை இதுவேயாகும். ஒரு முளை எவ்வாறு செடியை வலுப்படுத்துமோ, அதுபோலவே அவர்களும் தூதருக்கு உதவியும் ஆதரவும் வெற்றியும் அளித்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيَغِيظَ</span> <span class=\"quran-arabic-font text-success\">بِهِمُ</span> <span class=\"quran-arabic-font text-success\">الْكُفَّارَ</span><br />\r\n(அவர்களைக் கொண்டு அவன் நிராகரிப்பாளர்களை ஆத்திரமூட்டுவதற்காக.) இந்த வசனத்தை ஆதாரமாகக் கொண்டு, இமாம் மாலிக் அவர்கள், ரவாஃபிழ்கள் நிராகரிப்பாளர்கள் என்று கூறினார்கள்; ஏனெனில் அவர்கள் தோழர்களை (ரழி) வெறுக்கிறார்கள். மாலிக் அவர்கள் கூறினார்கள்: \"தோழர்கள் (ரழி) அவர்களை ஆத்திரமூட்டுகிறார்கள்; இந்த வசனத்தின்படி, தோழர்களால் ஆத்திரமடைபவன் ஒரு நிராகரிப்பாளன் ஆவான்.\" பல அறிஞர்கள் மாலிக் அவர்களின் இந்தக் கருத்துடன் உடன்பட்டுள்ளனர். தோழர்களின் (ரழி) சிறப்புகளைக் கூறும் மற்றும் அவர்களைக் குறை கூறுவதைத் தடுக்கும் எண்ணற்ற ஹதீஸ்கள் உள்ளன.<br />\r\n<br />\r\nஅல்லாஹ் அவர்களைப் புகழ்ந்திருப்பதும் அவர்கள் மீது தான் திருப்தி அடைந்ததாக அறிவித்திருப்பதும் அவர்களுக்குப் போதுமானதாகும். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّغْفِرَةً</span><br />\r\n(அவர்களில் இறைநம்பிக்கை கொண்டு நற்செயல்கள் புரிவோருக்கு அல்லாஹ் மன்னிப்பை வாக்குறுதி அளித்துள்ளான்.) இங்கு ‘மின்’ (இல்) என்பது இனத்தை விவரிப்பதாகும்; பகுதியைக் குறிப்பதன்று. அவர்களின் பாவங்களுக்காக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَجْراً</span> <span class=\"quran-arabic-font text-success\">عَظِيماً</span><br />\r\n(மேலும் மகத்தான ஒரு கூலியையும்.) தாராளமான வெகுமதியும் கண்ணியமான வாழ்வாதாரமும் ஆகும். நிச்சயமாக அல்லாஹ்வின் வாக்குறுதி உண்மையானது; அது நிறைவேறியே தீரும், ஒருபோதும் மீறப்படாது அல்லது மாற்றப்படாது.<br />\r\n<br />\r\nநிச்சயமாக, தோழர்களின் (ரழி) நேர்வழியைப் பின்பற்றும் அனைவரும் அவர்களைப் போலவே இருப்பார்கள். இருப்பினும், தோழர்களுக்குரிய சிறந்த நற்பண்புகள், அவர்களுக்குள்ள முன்னுரிமை மற்றும் குணங்களில் அவர்கள் பெற்றுள்ள முழுமை ஆகியவற்றின் காரணமாக, இந்தச் சமுதாயத்தில் எவரும் அவர்களின் அந்தஸ்தை அடைய முடியாது. அல்லாஹ் அவர்கள் மீது திருப்தி அடைவானாக, அவர்களையும் திருப்தி அடையச் செய்வானாக. அவன் அவர்களை அல்-பிர்தவ்ஸ் எனும் சுவனச் சோலைகளில் குடியமர்த்துவானாக; அதனை அவர்களின் நிரந்தர இல்லமாக ஆக்குவானாக. நிச்சயமாக அவன் அவ்வாறே செய்துள்ளான்.<br />\r\n<br />\r\nஇமாம் முஸ்லிம் அவர்கள் தனது ஸஹீஹில் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَسُبُّوا</span> <span class=\"quran-arabic-font text-success\">أَصْحَابِي،</span> <span class=\"quran-arabic-font text-success\">فَوَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْفَقَ</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">أُحُدٍ</span> <span class=\"quran-arabic-font text-success\">ذَهَبًا،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَدْرَكَ</span> <span class=\"quran-arabic-font text-success\">مُدَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">نَصِيفَه</span>»<br />\r\n(எனது தோழர்களைத் திட்டாதீர்கள். எனது உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! உங்களில் ஒருவர் உஹது மலை அளவு தங்கத்தைத் தர்மம் செய்தாலும், அது அவர்களில் ஒருவர் தர்மம் செய்த ஒரு 'முத்' (கைக்குவியளவு) அளவுக்கோ அல்லது அதில் பாதியளவுக்கோ கூட ஈடாகாது.)<br />\r\n<br />\r\nஇத்துடன் ஸூரத்துல் ஃபத்ஹின் தஃப்ஸீர் நிறைவுற்றது; எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"உண்மையான இறைநம்பிக்கையாளர்களின் பண்புகளும் அவர்களின் மேன்மையும்\n\r\n\n\r\nமுஹம்மது (ஸல்) அவர்கள் நிச்சயமாக அல்லாஹ்வின் தூதர் என்று அல்லாஹ் அறிவிக்கிறான்.\n\r\n\n\r\nمُّحَمَّدٌ رَّسُولُ اللَّهِ\n\r\n(முஹம்மது அல்லாஹ்வின் தூதராவார்.) இந்தப் பண்பு அனைத்து அழகான வர்ணனைகளையும் உள்ளடக்கியது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்களை (ரழி) அல்லாஹ் புகழ்கிறான்:\n\r\n\n\r\nوَالَّذِينَ مَعَهُ أَشِدَّآءُ عَلَى الْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ\n\r\n(அவருடன் இருப்பவர்கள் நிராகரிப்பாளர்களிடம் கடுமையானவர்களாகவும், தங்களுக்குள் கருணையுள்ளவர்களாகவும் இருக்கிறார்கள்.)\n\r\n\n\r\nகண்ணியமும் உயர்வும் மிக்க அல்லாஹ் மற்றொரு வசனத்தில் (ஆயத்தில்) கூறியவாறு:\n\r\n\n\r\nفَسَوْفَ يَأْتِى اللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُ أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ\n\r\n(அல்லாஹ் ஒரு சமூகத்தைக் கொண்டு வருவான்; அவர்களை அவன் நேசிப்பான், அவனையும் அவர்கள் நேசிப்பார்கள். அவர்கள் இறைநம்பிக்கையாளர்களிடம் பணிவாகவும், நிராகரிப்பாளர்களிடம் கடுமையாகவும் நடப்பார்கள்.) (5:54). இதுவே இறைநம்பிக்கையாளர்களின் வர்ணனையாகும்: நிராகரிப்பாளர்களிடம் கண்டிப்புடனும், இறைநம்பிக்கையாளர்களிடம் கருணையும் அன்பும் கொண்டவர்களாகவும் இருப்பார்கள். நிராகரிப்பாளர்களுக்கு முன்னால் புன்னகைக்காமல் கடுமையாகவும், தனது இறைநம்பிக்கையாளர் சகோதரருக்கு முன்னால் மகிழ்ச்சியுடன் புன்னகை பூத்த முகத்துடனும் இருப்பார்கள். உயர்ந்தவனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்:\n\r\n\n\r\nيَأَيُّهَا الَّذِينَ ءَامَنُواْ قَاتِلُواْ الَّذِينَ يَلُونَكُمْ مِّنَ الْكُفَّارِ وَلِيَجِدُواْ فِيكُمْ غِلْظَةً\n\r\n(இறைநம்பிக்கை கொண்டவர்களே! உங்களுக்கு அருகிலுள்ள நிராகரிப்பாளர்களுடன் போரிடுங்கள்; அவர்கள் உங்களிடம் கடுமையைக் காணட்டும்.) (9:123).\n\r\n\n\r\nநபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ كَمَثَلِ الْجَسَدِ الْوَاحِدِ، إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالْحُمَّى وَالسَّهَر»\n\r\n(பரஸ்பரம் அன்பு பாராட்டுவதிலும் கருணை காட்டுவதிலும் இறைநம்பிக்கையாளர்களுக்கு உவமை ஓர் உடலைப் போன்றதாகும். அதன் ஓர் உறுப்பு நோய்வாய்ப்பட்டால், மற்ற உறுப்புகளும் காய்ச்சல் மற்றும் தூக்கமின்மையால் அதற்குத் துணை நிற்கின்றன.)\n\r\n\n\r\nநபி (ஸல்) அவர்கள் மேலும் கூறினார்கள்:\n\r\n\n\r\n«الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا»\n\r\n(ஓர் இறைநம்பிக்கையாளர் மற்றோர் இறைநம்பிக்கையாளருக்கு ஒரு கட்டிடத்தைப் போன்றவர்; அதன் ஒரு பகுதி மற்றொரு பகுதியை வலுப்படுத்துகிறது.) பிறகு அவர்கள் தனது விரல்களை ஒன்றோடொன்று கோர்த்துக் காட்டினார்கள். இந்த இரு ஹதீஸ்களும் ஸஹீஹ் நூல்களில் இடம்பெற்றுள்ளன. கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nتَرَاهُمْ رُكَّعاً سُجَّداً يَبْتَغُونَ فَضْلاً مِّنَ اللَّهِ وَرِضْوَاناً\n\r\n(அவர்கள் ருகூஃ செய்பவர்களாகவும், ஸஜ்தா செய்பவர்களாகவும், அல்லாஹ்விடமிருந்து அருளையும் அவனது பொருத்தத்தையும் தேடுபவர்களாகவும் இருப்பதை நீர் காண்பீர்.)\n\r\n\n\r\nஇறைநம்பிக்கையாளர்கள் நற்செயல்கள் புரிவதிலும், வணக்கங்களிலேயே மிகச் சிறந்ததான தொழுகையிலும் சுறுசுறுப்பாக இருப்பவர்கள் என்று அல்லாஹ் விவரிக்கிறான். அதே சமயம், அவர்கள் தொழுகையில் கண்ணியமும் உயர்வும் மிக்க அல்லாஹ்விடம் உளத்தூய்மையுடன் இருந்து, அவனது தாராளமான வெகுமதியை மட்டுமே எதிர்பார்க்கிறார்கள். அல்லாஹ்வின் சிறந்த வெகுமதி அவனது அருட்கொடைகளும், கிருபைகளும், ஏராளமான வாழ்வாதாரங்களும் நிறைந்த சொர்க்கமாகும். அத்துடன், முந்தைய வெகுமதியை விட மேலான அவனது திருப்பொருத்தத்தைப் பெறுவதும் இதில் அடங்கும். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَرِضْوَانٌ مِّنَ اللَّهِ أَكْبَرُ\n\r\n(மேலும் அல்லாஹ்வின் திருப்பொருத்தமே மிகப்பெரியது.) (9:72).\n\r\n\n\r\nஅடுத்து வரும் உயர்ந்தவனாகிய அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nسِيمَاهُمْ فِى وُجُوهِهِمْ مِّنْ أَثَرِ السُّجُودِ\n\r\n(ஸஜ்தாவின் அடையாளங்கள் அவர்களின் முகங்களில் இருக்கும்.) இதற்கு 'அழகிய தோற்றம்' என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் விளக்கியுள்ளதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள். முஜாஹித் மற்றும் பல அறிஞர்கள், \"இதன் பொருள் பணிவும் இறையச்சமும் ஆகும்\" என்று விளக்குகிறார்கள். சிலர், \"நற்செயல் என்பது இதயத்திற்கு ஒளியையும், முகத்திற்குப் பொலிவையும், வாழ்வாதாரத்தில் விசாலத்தையும், மக்களின் இதயங்களில் அன்பையும் ஏற்படுத்துகிறது\" என்று கூறுகின்றனர். இறைநம்பிக்கையாளர்களின் தலைவர் உஸ்மான் பின் அஃப்பான் (ரழி) அவர்கள் கூறினார்கள்: \"யாராவது ஒரு ரகசியத்தை மறைத்து வைத்திருந்தால், அல்லாஹ் அதனை அவரது முகத்திலோ அல்லது அவர் அறியாமல் நழுவும் வார்த்தைகளின் மூலமோ வெளிப்படுத்தியே தீருவான்.\"\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) அவர்கள், நபி (ஸல்) அவர்கள் பின்வருமாறு கூறியதாக அறிவித்தார்கள்:\n\r\n\n\r\n«إِنَّ الْهَدْيَ الصَّالِحَ، وَالسَّمْتَ الصَّالِحَ، وَالْاقْتِصَادَ، جُزْءٌ مِنْ خَمْسَةٍ وَعِشْرِينَ جُزْءًا مِنَ النُّبُوَّة»\n\r\n(நிச்சயமாக நன்னடத்தை, அழகிய தோற்றம் மற்றும் நிதானம் ஆகியவை நபித்துவத்தின் இருபத்தைந்து பாகங்களில் ஒரு பாகமாகும்.) அபூ தாவூத் அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nஎனவே, தோழர்கள் (ரழி) தூய்மையான எண்ணங்களையும் நற்செயல்களையும் கொண்டிருந்ததால், அவர்களைப் பார்த்த எவரும் அவர்களின் தோற்றத்தையும் நடத்தையையும் விரும்பினர். இமாம் மாலிக் அவர்கள் கூறுகிறார்கள்: \"அஷ்-ஷாமைக் கைப்பற்றிய தோழர்களை (ரழி) பார்த்த கிறிஸ்தவர்கள், 'அல்லாஹ்வின் மீது சத்தியமாக, எங்களுக்குச் சொல்லப்பட்ட தகவல்களின்படி, இந்த மக்கள் (ஈஸா (அலை) அவர்களின்) சீடர்களை விடச் சிறந்தவர்களாக இருக்கிறார்கள்' என்று வியந்ததாக எனக்குத் தகவல் கிடைத்தது.\" அவர்கள் கூறியது உண்மையே; ஏனெனில் இந்தச் சமுதாயத்தைப் பற்றி முந்தைய வேதங்களில் கண்ணியமான முறையில் குறிப்பிடப்பட்டுள்ளது.\n\r\n\n\r\nஇந்த உம்மத்தின் மிகச் சிறந்த மற்றும் கண்ணியமானவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்கள் (ரழி) ஆவார்கள். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் அவர்களை முந்தைய வேதங்களிலும் இறைச்செய்திகளிலும் (வஹீ) புகழ்ந்துள்ளான். அதனால்தான் அவன் இங்கு பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nذَلِكَ مَثَلُهُمْ فِى التَّوْرَاةِ\n\r\n(இதுவே தவ்ராத்தில் அவர்களுக்குள்ள உவமையாகும்.) பிறகு கூறுகிறான்:\n\r\n\n\r\nوَمَثَلُهُمْ فِى الإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْأَهُ\n\r\n(இன்ஜீலில் அவர்களுக்குள்ள உவமையாவது: அது ஒரு பயிரைப் போன்றது; அது தனது முளையை (ஷத்ஆ) வெளிப்படுத்துகிறது.) முளை அல்லது கிளை.\n\r\n\n\r\nفَآزَرَهُ\n\r\n(பிறகு அதனை அது வலுப்படுத்துகிறது.) அது தானாக நிற்க முடிகிறது.\n\r\n\n\r\nفَاسْتَغْلَظَ\n\r\n(பின்பு அது தடிமனாகிறது.) வளர்ச்சியடைந்து உயரமாகிறது.\n\r\n\n\r\nفَاسْتَوَى عَلَى سُوقِهِ يُعْجِبُ الزُّرَّاعَ\n\r\n(பிறகு அது தனது தண்டின் மீது நிமிர்ந்து நின்று பயிரிட்டவர்களை வியக்க வைக்கிறது.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்களை (ரழி) விவரிக்கும் உவமை இதுவேயாகும். ஒரு முளை எவ்வாறு செடியை வலுப்படுத்துமோ, அதுபோலவே அவர்களும் தூதருக்கு உதவியும் ஆதரவும் வெற்றியும் அளித்தனர்.\n\r\n\n\r\nلِيَغِيظَ بِهِمُ الْكُفَّارَ\n\r\n(அவர்களைக் கொண்டு அவன் நிராகரிப்பாளர்களை ஆத்திரமூட்டுவதற்காக.) இந்த வசனத்தை ஆதாரமாகக் கொண்டு, இமாம் மாலிக் அவர்கள், ரவாஃபிழ்கள் நிராகரிப்பாளர்கள் என்று கூறினார்கள்; ஏனெனில் அவர்கள் தோழர்களை (ரழி) வெறுக்கிறார்கள். மாலிக் அவர்கள் கூறினார்கள்: \"தோழர்கள் (ரழி) அவர்களை ஆத்திரமூட்டுகிறார்கள்; இந்த வசனத்தின்படி, தோழர்களால் ஆத்திரமடைபவன் ஒரு நிராகரிப்பாளன் ஆவான்.\" பல அறிஞர்கள் மாலிக் அவர்களின் இந்தக் கருத்துடன் உடன்பட்டுள்ளனர். தோழர்களின் (ரழி) சிறப்புகளைக் கூறும் மற்றும் அவர்களைக் குறை கூறுவதைத் தடுக்கும் எண்ணற்ற ஹதீஸ்கள் உள்ளன.\n\r\n\n\r\nஅல்லாஹ் அவர்களைப் புகழ்ந்திருப்பதும் அவர்கள் மீது தான் திருப்தி அடைந்ததாக அறிவித்திருப்பதும் அவர்களுக்குப் போதுமானதாகும். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَعَدَ اللَّهُ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّالِحَاتِ مِنْهُم مَّغْفِرَةً\n\r\n(அவர்களில் இறைநம்பிக்கை கொண்டு நற்செயல்கள் புரிவோருக்கு அல்லாஹ் மன்னிப்பை வாக்குறுதி அளித்துள்ளான்.) இங்கு ‘மின்’ (இல்) என்பது இனத்தை விவரிப்பதாகும்; பகுதியைக் குறிப்பதன்று. அவர்களின் பாவங்களுக்காக.\n\r\n\n\r\nوَأَجْراً عَظِيماً\n\r\n(மேலும் மகத்தான ஒரு கூலியையும்.) தாராளமான வெகுமதியும் கண்ணியமான வாழ்வாதாரமும் ஆகும். நிச்சயமாக அல்லாஹ்வின் வாக்குறுதி உண்மையானது; அது நிறைவேறியே தீரும், ஒருபோதும் மீறப்படாது அல்லது மாற்றப்படாது.\n\r\n\n\r\nநிச்சயமாக, தோழர்களின் (ரழி) நேர்வழியைப் பின்பற்றும் அனைவரும் அவர்களைப் போலவே இருப்பார்கள். இருப்பினும், தோழர்களுக்குரிய சிறந்த நற்பண்புகள், அவர்களுக்குள்ள முன்னுரிமை மற்றும் குணங்களில் அவர்கள் பெற்றுள்ள முழுமை ஆகியவற்றின் காரணமாக, இந்தச் சமுதாயத்தில் எவரும் அவர்களின் அந்தஸ்தை அடைய முடியாது. அல்லாஹ் அவர்கள் மீது திருப்தி அடைவானாக, அவர்களையும் திருப்தி அடையச் செய்வானாக. அவன் அவர்களை அல்-பிர்தவ்ஸ் எனும் சுவனச் சோலைகளில் குடியமர்த்துவானாக; அதனை அவர்களின் நிரந்தர இல்லமாக ஆக்குவானாக. நிச்சயமாக அவன் அவ்வாறே செய்துள்ளான்.\n\r\n\n\r\nஇமாம் முஸ்லிம் அவர்கள் தனது ஸஹீஹில் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\n«لَا تَسُبُّوا أَصْحَابِي، فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ أَحَدَكُمْ أَنْفَقَ مِثْلَ أُحُدٍ ذَهَبًا، مَا أَدْرَكَ مُدَّ أَحَدِهِمْ وَلَا نَصِيفَه»\n\r\n(எனது தோழர்களைத் திட்டாதீர்கள். எனது உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! உங்களில் ஒருவர் உஹது மலை அளவு தங்கத்தைத் தர்மம் செய்தாலும், அது அவர்களில் ஒருவர் தர்மம் செய்த ஒரு 'முத்' (கைக்குவியளவு) அளவுக்கோ அல்லது அதில் பாதியளவுக்கோ கூட ஈடாகாது.)\n\r\n\n\r\nஇத்துடன் ஸூரத்துல் ஃபத்ஹின் தஃப்ஸீர் நிறைவுற்றது; எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
